INSERT INTO `clanky` (`idClanky`, `nadpis`, `upoutavka`, `uryvek`, `obsah`, `created_at`, `updated_at`, `zhlednuti`, `Uzivatele_idUzivatele`, `Kategorie_idKategorie`, `Stav_idStav`) VALUES
(122, 'Hradec Králové chystá rozsáhlou rekonstrukci hlavního nádraží', 'Hradec Králové čeká velká proměna! Hlavní nádraží projde rozsáhlou rekonstrukcí, která přinese modernější zázemí pro cestující, nové nástupiště i lepší propojení s městskou dopravou. Jaké změny se chystají a kdy práce začnou? Čtěte více v článku!', 'Hlavní nádraží v Hradci Králové čeká rozsáhlá rekonstrukce, která zahrnuje modernizaci budovy, obnovu nástupišť, nové informační systémy a lepší propojení s městskou dopravou. Cestující se mohou těšit na větší komfort i rychlejší odbavení. Stavební práce by měly začít v roce 2026 a potrvají přibližně tři roky.', '<h2 data-pm-slice=\"0 0 []\"><strong>Hradec Kr&aacute;lov&eacute; chyst&aacute; rozs&aacute;hlou rekonstrukci hlavn&iacute;ho n&aacute;draž&iacute;</strong></h2>\r\n<p>Hlavn&iacute; n&aacute;draž&iacute; v Hradci Kr&aacute;lov&eacute; ček&aacute; v n&aacute;sleduj&iacute;c&iacute;ch letech rozs&aacute;hl&aacute; rekonstrukce, kter&aacute; z&aacute;sadně proměn&iacute; jeho podobu i funkčnost. Projekt, na němž spolupracuje město Hradec Kr&aacute;lov&eacute; se Spr&aacute;vou železnic, si klade za c&iacute;l modernizovat odbavovac&iacute; prostory, infrastrukturu koleji&scaron;tě a zlep&scaron;it propojen&iacute; s městskou hromadnou dopravou. Celkov&eacute; n&aacute;klady na rekonstrukci se odhaduj&iacute; na několik stovek milionů korun, přičemž č&aacute;st prostředků by měla b&yacute;t hrazena z evropsk&yacute;ch fondů. Oček&aacute;v&aacute; se, že stavebn&iacute; pr&aacute;ce začnou v roce 2026 a potrvaj&iacute; přibližně tři roky.</p>\r\n<h3>Modernizace n&aacute;dražn&iacute; budovy a komfort cestuj&iacute;c&iacute;ch</h3>\r\n<p>Souč&aacute;st&iacute; projektu je kompletn&iacute; rekonstrukce n&aacute;dražn&iacute; budovy, kter&aacute; v současn&eacute; podobě již nevyhovuje současn&yacute;m n&aacute;rokům na cestov&aacute;n&iacute;. C&iacute;lem je nejen zlep&scaron;it komfort pro cestuj&iacute;c&iacute;, ale tak&eacute; zachovat historick&yacute; r&aacute;z budovy, kter&aacute; je důležitou architektonickou souč&aacute;st&iacute; města.</p>\r\n<p>Nov&aacute; odbavovac&iacute; hala nab&iacute;dne modern&iacute; informačn&iacute; syst&eacute;m s digit&aacute;ln&iacute;mi displeji, lep&scaron;&iacute; značen&iacute; pro orientaci cestuj&iacute;c&iacute;ch a přehledněj&scaron;&iacute; rozm&iacute;stěn&iacute; služeb, jako jsou pokladny, ček&aacute;rny či obchody. Důraz bude kladen tak&eacute; na bezbari&eacute;rov&yacute; př&iacute;stup, což zahrnuje v&yacute;tahy a eskal&aacute;tory pro snadněj&scaron;&iacute; pohyb osob se sn&iacute;ženou mobilitou.</p>\r\n<p>V r&aacute;mci &uacute;prav interi&eacute;ru dojde k modernizaci soci&aacute;ln&iacute;ch zař&iacute;zen&iacute;, zvět&scaron;en&iacute; prostoru pro ček&aacute;rny a zaveden&iacute; modern&iacute;ch technologi&iacute;, kter&eacute; umožn&iacute; např&iacute;klad rychlej&scaron;&iacute; odbaven&iacute; nebo bezkontaktn&iacute; platby za služby. Připravuje se i vytvořen&iacute; nov&eacute; odpočinkov&eacute; z&oacute;ny pro cestuj&iacute;c&iacute; a roz&scaron;&iacute;řen&iacute; komerčn&iacute;ch prostor s kav&aacute;rnami a obchody.</p>\r\n<h3>Rekonstrukce koleji&scaron;tě a peronů</h3>\r\n<p>Velk&aacute; č&aacute;st investic půjde tak&eacute; do železničn&iacute; infrastruktury, kter&aacute; je kl&iacute;čov&aacute; pro zv&yacute;&scaron;en&iacute; kapacity a bezpečnosti železničn&iacute;ho provozu. N&aacute;stupi&scaron;tě budou zv&yacute;&scaron;ena, aby umožnila pohodlněj&scaron;&iacute; n&aacute;stup a v&yacute;stup do vlaků, zejm&eacute;na pro osoby se sn&iacute;ženou pohyblivost&iacute;. Současně budou osazena nov&yacute;mi př&iacute;stře&scaron;ky, kter&eacute; nab&iacute;dnou lep&scaron;&iacute; ochranu proti nepř&iacute;zniv&eacute;mu počas&iacute;.</p>\r\n<p>Modernizac&iacute; projdou tak&eacute; koleje a v&yacute;hybky, což umožn&iacute; plynulej&scaron;&iacute; a rychlej&scaron;&iacute; provoz vlaků. V r&aacute;mci rekonstrukce se poč&iacute;t&aacute; i s nov&yacute;m zabezpečovac&iacute;m syst&eacute;mem, kter&yacute; zlep&scaron;&iacute; ř&iacute;zen&iacute; železničn&iacute; dopravy a zv&yacute;&scaron;&iacute; bezpečnost cestuj&iacute;c&iacute;ch.</p>\r\n<h3>Lep&scaron;&iacute; napojen&iacute; na městskou dopravu</h3>\r\n<p>Hlavn&iacute; n&aacute;draž&iacute; v Hradci Kr&aacute;lov&eacute; představuje v&yacute;znamn&yacute; dopravn&iacute; uzel, a proto bude jeho rekonstrukce zahrnovat i &uacute;pravy předn&aacute;dražn&iacute;ho prostoru. Město pl&aacute;nuje vybudovat modern&iacute; dopravn&iacute; termin&aacute;l, kter&yacute; zajist&iacute; pohodlněj&scaron;&iacute; přestupy mezi vlaky, autobusy, trolejbusy a dal&scaron;&iacute;mi formami dopravy.</p>\r\n<p>V r&aacute;mci projektu dojde k &uacute;prav&aacute;m parkovi&scaron;tě pro osobn&iacute; automobily a zv&yacute;&scaron;&iacute; se kapacita parkovac&iacute;ch m&iacute;st pro cyklisty. Poč&iacute;t&aacute; se i s lep&scaron;&iacute;mi možnostmi pro taxislužby a carsharing. Město chce t&iacute;mto krokem podpořit multimod&aacute;ln&iacute; dopravu a motivovat obyvatele k vět&scaron;&iacute;mu využ&iacute;v&aacute;n&iacute; veřejn&eacute; dopravy.</p>\r\n<h3>Harmonogram prac&iacute; a financov&aacute;n&iacute;</h3>\r\n<p>Podle aktu&aacute;ln&iacute;ch pl&aacute;nů by stavebn&iacute; pr&aacute;ce měly zač&iacute;t v roce 2026 a budou prob&iacute;hat ve f&aacute;z&iacute;ch, aby nedo&scaron;lo k &uacute;pln&eacute;mu omezen&iacute; železničn&iacute;ho provozu. Přibližně do roku 2029 by měla b&yacute;t dokončena vět&scaron;ina &uacute;prav a cestuj&iacute;c&iacute; by tak mohli využ&iacute;vat modernizovan&eacute; n&aacute;draž&iacute; v pln&eacute;m rozsahu.</p>\r\n<p>Celkov&eacute; n&aacute;klady na projekt se odhaduj&iacute; na několik stovek milionů korun. Financov&aacute;n&iacute; bude prob&iacute;hat z kombinace st&aacute;tn&iacute;ho rozpočtu, prostředků Spr&aacute;vy železnic, městsk&eacute;ho rozpočtu a evropsk&yacute;ch fondů. Podle představitelů města i železničn&iacute; spr&aacute;vy je c&iacute;lem vytvořit modern&iacute;, efektivn&iacute; a ekologicky &scaron;etrn&yacute; dopravn&iacute; uzel, kter&yacute; bude sloužit nejen obyvatelům Hradce Kr&aacute;lov&eacute;, ale i &scaron;ir&scaron;&iacute;mu regionu.</p>\r\n<h3>Reakce veřejnosti a budoucnost n&aacute;draž&iacute;</h3>\r\n<p>Pl&aacute;novan&aacute; rekonstrukce vzbuzuje velk&yacute; z&aacute;jem mezi obyvateli města i pravideln&yacute;mi cestuj&iacute;c&iacute;mi. Město pl&aacute;nuje uspoř&aacute;dat veřejn&aacute; setk&aacute;n&iacute; a diskuse, kde budou občan&eacute; moci vyj&aacute;dřit sv&eacute; podněty a připom&iacute;nky. Cestuj&iacute;c&iacute; tak budou m&iacute;t možnost ovlivnit budouc&iacute; podobu jednoho z nejv&yacute;znamněj&scaron;&iacute;ch dopravn&iacute;ch uzlů v regionu.</p>\r\n<p>Po dokončen&iacute; rekonstrukce se oček&aacute;v&aacute; nejen zv&yacute;&scaron;en&iacute; komfortu a bezpečnosti pro cestuj&iacute;c&iacute;, ale tak&eacute; zlep&scaron;en&iacute; dopravn&iacute; obslužnosti cel&eacute;ho regionu. Modernizovan&eacute; hlavn&iacute; n&aacute;draž&iacute; se stane důležit&yacute;m centrem veřejn&eacute; dopravy a přispěje k rozvoji městsk&eacute; infrastruktury v Hradci Kr&aacute;lov&eacute;.</p>', '2025-03-03 11:57:58', '2025-03-12 15:43:34', 122, 17, 3, 4),
(123, 'Pardubice získaly dotaci na modernizaci městské hromadné dopravy', 'Velká změna pro MHD v Pardubicích! Město získalo dotaci na modernizaci hromadné dopravy. Čekají nás nové ekologické autobusy a trolejbusy, modernizace zastávek i lepší služby pro cestující. Jaké další novinky se chystají? Čtěte v článku!', 'Pardubice získaly významnou dotaci na modernizaci městské hromadné dopravy. Investice půjdou do nákupu nových ekologických vozidel, modernizace zastávek, zavedení inteligentních semaforů a zlepšení služeb pro cestující. Cílem je snížení emisí, zrychlení dopravy a zvýšení komfortu. První změny se očekávají od roku 2026, přičemž celý projekt by měl být dokončen do roku 2028.', '<h3 data-start=\"0\" data-end=\"74\"><strong data-start=\"4\" data-end=\"72\">Pardubice z&iacute;skaly dotaci na modernizaci městsk&eacute; hromadn&eacute; dopravy</strong></h3>\r\n<p data-start=\"76\" data-end=\"444\"><strong data-start=\"76\" data-end=\"91\">Pardubice &ndash;</strong> Město Pardubice z&iacute;skalo v&yacute;znamnou finančn&iacute; podporu na modernizaci městsk&eacute; hromadn&eacute; dopravy. Dotace ve v&yacute;&scaron;i několika stovek milionů korun umožn&iacute; investice do nov&yacute;ch ekologick&yacute;ch vozidel, vylep&scaron;en&iacute; dopravn&iacute; infrastruktury a zkvalitněn&iacute; služeb pro cestuj&iacute;c&iacute;. Projekt m&aacute; přispět ke sn&iacute;žen&iacute; emis&iacute;, zlep&scaron;en&iacute; plynulosti dopravy a zv&yacute;&scaron;en&iacute; komfortu cestov&aacute;n&iacute;.</p>\r\n<h2 data-start=\"453\" data-end=\"495\"><strong data-start=\"456\" data-end=\"493\">Investice do ekologick&yacute;ch vozidel</strong></h2>\r\n<p data-start=\"497\" data-end=\"851\">Jedn&iacute;m z hlavn&iacute;ch c&iacute;lů modernizace je n&aacute;kup nov&yacute;ch n&iacute;zkoemisn&iacute;ch a bezemisn&iacute;ch vozidel. Pardubice pl&aacute;nuj&iacute; roz&scaron;&iacute;řit svůj vozov&yacute; park o modern&iacute; elektrobusy a trolejbusy, kter&eacute; sn&iacute;ž&iacute; ekologickou z&aacute;těž města. Nov&eacute; vozy budou vybaveny klimatizac&iacute;, n&iacute;zkopodlažn&iacute;m vstupem pro snadněj&scaron;&iacute; př&iacute;stup a modern&iacute;m informačn&iacute;m syst&eacute;mem pro lep&scaron;&iacute; orientaci cestuj&iacute;c&iacute;ch.</p>\r\n<p data-start=\"853\" data-end=\"1041\">&bdquo;Na&scaron;&iacute;m c&iacute;lem je nab&iacute;dnout obyvatelům pohodlnou, spolehlivou a ekologickou dopravu. D&iacute;ky dotaci můžeme urychlit přechod na modern&iacute; vozidla s niž&scaron;&iacute; uhl&iacute;kovou stopou,&ldquo; uvedl prim&aacute;tor města.</p>\r\n<p data-start=\"1043\" data-end=\"1278\">Město rovněž pl&aacute;nuje vyřadit star&scaron;&iacute; dieselov&eacute; autobusy, kter&eacute; již nevyhovuj&iacute; současn&yacute;m ekologick&yacute;m standardům. Modernizace vozov&eacute;ho parku tak bude znamenat nejen &uacute;sporu provozn&iacute;ch n&aacute;kladů, ale tak&eacute; sn&iacute;žen&iacute; hlučnosti a emis&iacute; ve městě.</p>\r\n<h2 data-start=\"1287\" data-end=\"1329\"><strong data-start=\"1290\" data-end=\"1327\">Vylep&scaron;en&iacute; dopravn&iacute; infrastruktury</strong></h2>\r\n<p data-start=\"1331\" data-end=\"1539\">Kromě nov&yacute;ch vozidel se dotace zaměř&iacute; i na zlep&scaron;en&iacute; dopravn&iacute; infrastruktury. Dojde k modernizaci zast&aacute;vek, včetně instalace nov&yacute;ch př&iacute;stře&scaron;ků a elektronick&yacute;ch informačn&iacute;ch tabul&iacute; s aktu&aacute;ln&iacute;mi odjezdy spojů.</p>\r\n<p data-start=\"1541\" data-end=\"1825\">Souč&aacute;st&iacute; projektu je tak&eacute; roz&scaron;&iacute;řen&iacute; preferenčn&iacute;ch opatřen&iacute; pro MHD. Dopravn&iacute; podnik ve spolupr&aacute;ci s městem pl&aacute;nuje instalaci inteligentn&iacute;ch semaforů, kter&eacute; umožn&iacute; plynulej&scaron;&iacute; průjezd autobusů a trolejbusů křižovatkami. Tento syst&eacute;m pomůže sn&iacute;žit zpožděn&iacute; a zv&yacute;&scaron;it efektivitu provozu.</p>\r\n<p data-start=\"1827\" data-end=\"2060\">&bdquo;Chceme, aby MHD byla atraktivn&iacute; alternativou k individu&aacute;ln&iacute; automobilov&eacute; dopravě. Proto investujeme nejen do vozidel, ale tak&eacute; do infrastruktury, kter&aacute; zlep&scaron;&iacute; plynulost a komfort cestov&aacute;n&iacute;,&ldquo; doplnil n&aacute;městek prim&aacute;tora pro dopravu.</p>\r\n<h2 data-start=\"2069\" data-end=\"2104\"><strong data-start=\"2072\" data-end=\"2102\">Lep&scaron;&iacute; služby pro cestuj&iacute;c&iacute;</strong></h2>\r\n<p data-start=\"2106\" data-end=\"2311\">Souč&aacute;st&iacute; modernizace bude i zaveden&iacute; nov&yacute;ch technologi&iacute;, kter&eacute; zlep&scaron;&iacute; služby pro cestuj&iacute;c&iacute;. Pl&aacute;nuje se roz&scaron;&iacute;řen&iacute; možnosti platby bezkontaktn&iacute;mi kartami a mobiln&iacute;mi aplikacemi, což usnadn&iacute; n&aacute;kup j&iacute;zdenek.</p>\r\n<p data-start=\"2313\" data-end=\"2482\">Dal&scaron;&iacute; novinkou bude inteligentn&iacute; pl&aacute;nov&aacute;n&iacute; tras v mobiln&iacute; aplikaci, kter&aacute; umožn&iacute; cestuj&iacute;c&iacute;m l&eacute;pe se orientovat v j&iacute;zdn&iacute;ch ř&aacute;dech a z&iacute;skat aktu&aacute;ln&iacute; informace o provozu.</p>\r\n<p data-start=\"2484\" data-end=\"2642\">Město tak&eacute; pl&aacute;nuje roz&scaron;&iacute;řit syst&eacute;m sd&iacute;len&yacute;ch dopravn&iacute;ch prostředků, jako jsou kola a elektrokoloběžky, a vytvořit lep&scaron;&iacute; n&aacute;vaznosti mezi MHD a cyklodopravou.</p>\r\n<p data-start=\"2644\" data-end=\"2833\">&bdquo;Chceme, aby MHD byla co nejdostupněj&scaron;&iacute; a nejkomfortněj&scaron;&iacute; pro v&scaron;echny skupiny obyvatel, ať už jde o seniory, rodiny s dětmi nebo turisty,&ldquo; uvedl ředitel Dopravn&iacute;ho podniku města Pardubic.</p>\r\n<h2 data-start=\"2842\" data-end=\"2885\"><strong data-start=\"2845\" data-end=\"2883\">Harmonogram a financov&aacute;n&iacute; projektu</strong></h2>\r\n<p data-start=\"2887\" data-end=\"3194\">Podle města by modernizace městsk&eacute; hromadn&eacute; dopravy měla prob&iacute;hat postupně během n&aacute;sleduj&iacute;c&iacute;ch let. Prvn&iacute; nov&eacute; autobusy a trolejbusy by mohly vyjet na pardubick&eacute; silnice již v roce 2026. Infrastrukturn&iacute; &uacute;pravy, včetně modernizace zast&aacute;vek a preferenčn&iacute;ch opatřen&iacute;, budou realizov&aacute;ny postupně do roku 2028.</p>\r\n<p data-start=\"3196\" data-end=\"3411\">Projekt je financov&aacute;n z evropsk&yacute;ch fondů a st&aacute;tn&iacute;ho rozpočtu, přičemž město se pod&iacute;l&iacute; i vlastn&iacute;mi prostředky. Celkov&eacute; n&aacute;klady se odhaduj&iacute; na několik set milionů korun, přičemž vět&scaron;inu pokryj&iacute; pr&aacute;vě z&iacute;skan&eacute; dotace.</p>\r\n<h2 data-start=\"3420\" data-end=\"3460\"><strong data-start=\"3423\" data-end=\"3458\">Co modernizace přinese občanům?</strong></h2>\r\n<p data-start=\"3462\" data-end=\"3586\">D&iacute;ky t&eacute;to investici se Pardubice zařad&iacute; mezi města s modern&iacute; a ekologickou veřejnou dopravou. Cestuj&iacute;c&iacute; se mohou tě&scaron;it na:</p>\r\n<ul>\r\n<li data-start=\"3588\" data-end=\"3961\"><strong data-start=\"3590\" data-end=\"3631\">Nov&eacute; ekologick&eacute; autobusy a trolejbusy</strong> &ndash; ti&scaron;&scaron;&iacute;, pohodlněj&scaron;&iacute; a &scaron;etrněj&scaron;&iacute; k životn&iacute;mu prostřed&iacute;.</li>\r\n<li data-start=\"3588\" data-end=\"3961\"><strong data-start=\"3692\" data-end=\"3718\">Modernizovan&eacute; zast&aacute;vky</strong> &ndash; s lep&scaron;&iacute;m vybaven&iacute;m a aktu&aacute;ln&iacute;mi informacemi.</li>\r\n<li data-start=\"3588\" data-end=\"3961\"><strong data-start=\"3770\" data-end=\"3795\">Plynulej&scaron;&iacute; provoz MHD</strong> &ndash; d&iacute;ky inteligentn&iacute;m semaforům a preferenčn&iacute;m pruhům.</li>\r\n<li data-start=\"3588\" data-end=\"3961\"><strong data-start=\"3854\" data-end=\"3884\">Lep&scaron;&iacute; dostupnost a komfort</strong> &ndash; bezkontaktn&iacute; platby, mobiln&iacute; aplikace a lep&scaron;&iacute; propojen&iacute; s cyklodopravou.</li>\r\n</ul>\r\n<p data-start=\"3963\" data-end=\"4091\">Modernizace MHD je důležit&yacute;m krokem pro udržitelnou mobilitu ve městě a přispěje ke zlep&scaron;en&iacute; kvality života obyvatel Pardubic.</p>', '2025-03-03 12:32:18', '2025-03-18 11:59:32', 5, 17, 3, 4),
(124, 'Silné bouřky zasáhly Královéhradecký kraj, hlášeny výpadky elektřiny', 'Královéhradecký kraj zasáhly silné bouřky! Přívalové deště, vichr a blesky způsobily výpadky elektřiny, popadané stromy a zatopené domy. Hasiči zasahovali u stovek případů a energetici pracují na obnově dodávek. Co všechno bouře napáchala a jaká je aktuální situace? Čtěte v našem článku!', 'Silné bouřky, které v noci zasáhly Královéhradecký kraj, způsobily rozsáhlé škody. Silný vítr lámal stromy, přívalové deště zatopily sklepy a tisíce domácností se ocitly bez elektřiny. Hasiči vyjížděli k stovkám případů a energetici pracují na obnově dodávek. Situace komplikuje i narušená doprava a meteorologové varují před dalšími bouřkami.', '<h3 data-start=\"0\" data-end=\"78\"><strong data-start=\"4\" data-end=\"76\">Siln&eacute; bouřky zas&aacute;hly Kr&aacute;lov&eacute;hradeck&yacute; kraj, hl&aacute;&scaron;eny v&yacute;padky elektřiny</strong></h3>\r\n<p data-start=\"80\" data-end=\"475\"><strong data-start=\"80\" data-end=\"106\">Kr&aacute;lov&eacute;hradeck&yacute; kraj &ndash;</strong> Kr&aacute;lov&eacute;hradeck&yacute; kraj se v noci na ponděl&iacute; pot&yacute;kal s intenzivn&iacute;mi bouřkami, kter&eacute; přinesly siln&yacute; v&iacute;tr, př&iacute;valov&eacute; de&scaron;tě a četn&eacute; v&yacute;padky elektřiny. Bouřkov&yacute; syst&eacute;m, kter&yacute; postupoval přes Českou republiku, způsobil lok&aacute;ln&iacute; z&aacute;plavy, pol&aacute;man&eacute; stromy a naru&scaron;il dod&aacute;vky elektrick&eacute; energie v mnoha obc&iacute;ch. Energetici pracuj&iacute; na obnoven&iacute; s&iacute;tě, zat&iacute;mco hasiči odstraňuj&iacute; &scaron;kody.</p>\r\n<h3 data-start=\"477\" data-end=\"531\"><strong data-start=\"481\" data-end=\"529\">Siln&yacute; v&iacute;tr a př&iacute;valov&eacute; de&scaron;tě způsobily &scaron;kody</strong></h3>\r\n<p data-start=\"533\" data-end=\"885\">Podle meteorologů se bouřky začaly formovat v neděli večer a během noci postupovaly od z&aacute;padu na v&yacute;chod. Doprov&aacute;zel je siln&yacute; v&iacute;tr s n&aacute;razy přes 90 km/h, kter&yacute; l&aacute;mal stromy, strh&aacute;val elektrick&aacute; veden&iacute; a po&scaron;kozoval střechy domů. Na někter&yacute;ch m&iacute;stech napr&scaron;elo během kr&aacute;tk&eacute; doby až 50 milimetrů sr&aacute;žek, což vedlo k zatopen&iacute; sklepů a n&iacute;že položen&yacute;ch ulic.</p>\r\n<p data-start=\"887\" data-end=\"1155\">Nejhor&scaron;&iacute; situace nastala v okresech Hradec Kr&aacute;lov&eacute;, Trutnov a N&aacute;chod, kde hasiči zasahovali u des&iacute;tek př&iacute;padů spadl&yacute;ch stromů a zatopen&yacute;ch objektů. V Hradci Kr&aacute;lov&eacute; museli dokonce evakuovat několik dom&aacute;cnost&iacute;, protože hladina někter&yacute;ch men&scaron;&iacute;ch toků se rychle zvedla.</p>\r\n<p data-start=\"1157\" data-end=\"1397\">&bdquo;Bylo to jako peklo. V&iacute;tr hučel, blesky osvětlovaly oblohu a za chv&iacute;li n&aacute;m voda začala pronikat do domu. Hasiči byli na m&iacute;stě během několika minut a pomohli n&aacute;m odčerpat vodu ze sklepa,&ldquo; popsala situaci pan&iacute; Marie z okraje Hradce Kr&aacute;lov&eacute;.</p>\r\n<h3 data-start=\"1399\" data-end=\"1453\"><strong data-start=\"1403\" data-end=\"1451\">V&yacute;padky elektřiny postihly tis&iacute;ce dom&aacute;cnost&iacute;</strong></h3>\r\n<p data-start=\"1455\" data-end=\"1732\">Siln&eacute; bouřky naru&scaron;ily dod&aacute;vky elektřiny v cel&eacute;m kraji. Nejv&iacute;ce postižen&eacute; byly oblasti kolem Jaroměře, Dvora Kr&aacute;lov&eacute; nad Labem a Nov&eacute; Paky, kde do&scaron;lo k přeru&scaron;en&iacute; veden&iacute; vysok&eacute;ho napět&iacute;. Distribučn&iacute; společnosti evidovaly v rann&iacute;ch hodin&aacute;ch v&yacute;padky u v&iacute;ce než 20 000 odběratelů.</p>\r\n<p data-start=\"1734\" data-end=\"1914\">Energetici od brzk&yacute;ch rann&iacute;ch hodin pracuj&iacute; na oprav&aacute;ch po&scaron;kozen&yacute;ch linek a postupně obnovuj&iacute; dod&aacute;vky. Někter&eacute; dom&aacute;cnosti v&scaron;ak mohou zůstat bez elektřiny až do odpoledn&iacute;ch hodin.</p>\r\n<p data-start=\"1916\" data-end=\"2164\">&bdquo;Na&scaron;e t&yacute;my jsou v ter&eacute;nu od prvn&iacute;ch hl&aacute;&scaron;en&iacute;. Největ&scaron;&iacute;m probl&eacute;mem jsou spadl&eacute; stromy na veden&iacute; a siln&yacute; v&iacute;tr, kter&yacute; komplikoval opravy během noci. Děl&aacute;me v&scaron;e pro to, aby byla elektřina obnovena co nejdř&iacute;ve,&ldquo; uvedl mluvč&iacute; společnosti ČEZ Distribuce.</p>\r\n<h3 data-start=\"2166\" data-end=\"2210\"><strong data-start=\"2170\" data-end=\"2208\">Hasiči zasahovali u stovek př&iacute;padů</strong></h3>\r\n<p data-start=\"2212\" data-end=\"2421\">Kr&aacute;lov&eacute;hradečt&iacute; hasiči hl&aacute;s&iacute; v&iacute;ce než 300 v&yacute;jezdů během noci a brzk&yacute;ch rann&iacute;ch hodin. Nejčastěji odstraňovali popadan&eacute; stromy z komunikac&iacute;, čerpali vodu ze zatopen&yacute;ch objektů a zaji&scaron;ťovali po&scaron;kozen&eacute; střechy.</p>\r\n<p data-start=\"2423\" data-end=\"2676\">V Trutnově např&iacute;klad siln&yacute; v&iacute;tr po&scaron;kodil střechu m&iacute;stn&iacute; &scaron;koly, kterou bylo nutn&eacute; provizorně zabezpečit. V Jaroměři do&scaron;lo k vyvr&aacute;cen&iacute; několika vzrostl&yacute;ch stromů v městsk&eacute;m parku, přičemž jeden z nich zas&aacute;hl zaparkovan&eacute; auto. Na&scaron;těst&iacute; se nikdo nezranil.</p>\r\n<p data-start=\"2678\" data-end=\"2921\">&bdquo;Situace byla extr&eacute;mně n&aacute;ročn&aacute;, ale d&iacute;ky rychl&eacute; reakci na&scaron;ich jednotek se podařilo zabr&aacute;nit vět&scaron;&iacute;m &scaron;kod&aacute;m. Pros&iacute;me obyvatele, aby byli při odstraňov&aacute;n&iacute; n&aacute;sledků opatrn&iacute; a v př&iacute;padě potřeby zavolali odborn&iacute;ky,&ldquo; apeloval krajsk&yacute; hasičsk&yacute; sbor.</p>\r\n<h3 data-start=\"2923\" data-end=\"2975\"><strong data-start=\"2927\" data-end=\"2973\">Meteorologov&eacute; varuj&iacute; před dal&scaron;&iacute;mi bouřkami</strong></h3>\r\n<p data-start=\"2977\" data-end=\"3170\">Podle meteorologů se bouřkov&eacute; počas&iacute; v n&aacute;sleduj&iacute;c&iacute;ch dnech je&scaron;tě nemus&iacute; uklidnit. V&yacute;straha před siln&yacute;mi bouřkami plat&iacute; i pro &uacute;ter&yacute;, přičemž hroz&iacute; dal&scaron;&iacute; siln&eacute; n&aacute;razy větru a intenzivn&iacute; sr&aacute;žky.</p>\r\n<p data-start=\"3172\" data-end=\"3424\">&bdquo;Bouřkov&eacute; syst&eacute;my se budou tvořit i během n&aacute;sleduj&iacute;c&iacute;ch dn&iacute;. Doporučujeme sledovat aktu&aacute;ln&iacute; předpověď a přijmout preventivn&iacute; opatřen&iacute;, zejm&eacute;na zajistit volně položen&eacute; předměty a omezit pohyb venku během bouřky,&ldquo; uvedl Česk&yacute; hydrometeorologick&yacute; &uacute;stav.</p>\r\n<p data-start=\"3426\" data-end=\"3529\">Obyvatel&eacute; kraje by měli b&yacute;t obezřetn&iacute; a připraveni na možn&eacute; komplikace v dopravě i dod&aacute;vk&aacute;ch energi&iacute;.</p>\r\n<h3 data-start=\"3531\" data-end=\"3568\"><strong data-start=\"3535\" data-end=\"3566\">Dopravn&iacute; omezen&iacute; a uzav&iacute;rky</strong></h3>\r\n<p data-start=\"3570\" data-end=\"3846\">Siln&eacute; bouřky a n&aacute;sledky v podobě popadan&yacute;ch stromů ovlivnily tak&eacute; dopravu v regionu. Někter&eacute; silnice byly v rann&iacute;ch hodin&aacute;ch neprůjezdn&eacute;, zejm&eacute;na v okol&iacute; Hořic, Rychnova nad Kněžnou a Dobru&scaron;ky. Silnič&aacute;ři postupně odstraňuj&iacute; přek&aacute;žky, ale řidiči by měli poč&iacute;tat se zdržen&iacute;mi.</p>\r\n<p data-start=\"3848\" data-end=\"4064\">Na železnici do&scaron;lo k v&yacute;padkům na několika trat&iacute;ch kvůli spadl&yacute;m stromům na koleje. Největ&scaron;&iacute; probl&eacute;my byly hl&aacute;&scaron;eny na trati mezi Hradcem Kr&aacute;lov&eacute; a Chlumcem nad Cidlinou, kde musela b&yacute;t č&aacute;st spojů nahrazena autobusy.</p>\r\n<h3 data-start=\"4066\" data-end=\"4104\"><strong data-start=\"4070\" data-end=\"4102\">Jak se chr&aacute;nit před bouřkou?</strong></h3>\r\n<p data-start=\"4106\" data-end=\"4196\">Meteorologov&eacute; i z&aacute;chrann&eacute; složky připom&iacute;naj&iacute; z&aacute;kladn&iacute; pravidla bezpečnosti při bouřk&aacute;ch:</p>\r\n<ul data-start=\"4198\" data-end=\"4574\">\r\n<li data-start=\"4198\" data-end=\"4267\">Nevych&aacute;zejte zbytečně ven a vyh&yacute;bejte se otevřen&yacute;m prostranstv&iacute;m.</li>\r\n<li data-start=\"4268\" data-end=\"4326\">Nepohybujte se v bl&iacute;zkosti stromů, mohly by se zř&iacute;tit.</li>\r\n<li data-start=\"4327\" data-end=\"4422\">Pokud jste na cestě, zastavte na bezpečn&eacute;m m&iacute;stě mimo stromy a nestůjte u kovov&yacute;ch objektů.</li>\r\n<li data-start=\"4423\" data-end=\"4508\">Zajistěte volně položen&eacute; předměty na zahrad&aacute;ch a balkonech, aby je v&iacute;tr neodnesl.</li>\r\n<li data-start=\"4509\" data-end=\"4574\">Sledujte meteorologick&eacute; v&yacute;strahy a pokyny z&aacute;chrann&yacute;ch složek.</li>\r\n</ul>\r\n<h3 data-start=\"4576\" data-end=\"4616\"><strong data-start=\"4580\" data-end=\"4614\">Obnova &scaron;kod potrv&aacute; několik dn&iacute;</strong></h3>\r\n<p data-start=\"4618\" data-end=\"4848\">Ačkoli se hasiči a energetici snaž&iacute; situaci co nejrychleji stabilizovat, obnova &scaron;kod způsoben&yacute;ch nočn&iacute; bouř&iacute; potrv&aacute; několik dn&iacute;. &Uacute;řady doporučuj&iacute; občanům, aby hl&aacute;sili &scaron;kody na majetku a v př&iacute;padě potřeby kontaktovali poji&scaron;ťovny.</p>\r\n<p data-start=\"4850\" data-end=\"5043\" data-is-last-node=\"\" data-is-only-node=\"\">Kr&aacute;lov&eacute;hradeck&yacute; kraj se tak po siln&yacute;ch bouřk&aacute;ch postupně vrac&iacute; k norm&aacute;lu, přesto zůst&aacute;v&aacute; v pohotovosti kvůli možn&yacute;m dal&scaron;&iacute;m př&iacute;valov&yacute;m de&scaron;ťům a větrn&yacute;m n&aacute;razům. Situaci budeme i nad&aacute;le sledovat.</p>', '2025-03-03 12:40:16', '2025-03-12 15:43:34', 5, 17, 3, 4),
(125, 'Rozsáhlý požár lesa u Trutnova: Hasiči bojovali celou noc', 'Lesní požár u Trutnova zaměstnal hasiče na celou noc! Silný vítr a sucho pomohly plamenům rychle se šířit, což vedlo k rozsáhlému zásahu desítek jednotek a nasazení leteckého hašení. Evakuace, výpadky proudu a obrovské škody na přírodě – co všechno se stalo a jaká je situace teď? Čtěte více v našem článku!', 'Rozsáhlý lesní požár u Trutnova zachvátil desítky hektarů porostu a hasiči s ním bojovali celou noc. Kvůli silnému větru a suchu se oheň rychle šířil, což si vyžádalo nasazení desítek jednotek hasičů i vrtulníku s bambivakem. Preventivně muselo být evakuováno několik chat a osad. Příčina požáru zatím není jasná, ale spekuluje se o lidské nedbalosti. Obnova zasažené oblasti potrvá roky a meteorologové varují před dalším nebezpečím požárů kvůli přetrvávajícímu suchu.', '<h1 data-start=\"0\" data-end=\"65\"><strong data-start=\"2\" data-end=\"63\">Rozs&aacute;hl&yacute; pož&aacute;r lesa u Trutnova: Hasiči bojovali celou noc</strong></h1>\r\n<h2 data-start=\"67\" data-end=\"115\"><strong data-start=\"70\" data-end=\"113\">Plameny zachv&aacute;tily des&iacute;tky hektarů lesa</strong></h2>\r\n<p data-start=\"117\" data-end=\"410\">Trutnov &ndash; Rozs&aacute;hl&yacute; pož&aacute;r vypukl v p&aacute;tek večer v lesn&iacute;m porostu nedaleko Trutnova. Plameny se kvůli siln&eacute;mu větru rychle &scaron;&iacute;řily a během několika hodin zachv&aacute;tily des&iacute;tky hektarů lesa. Do boje s ohněm byli nasazeni des&iacute;tky hasičů z cel&eacute;ho regionu, kteř&iacute; s pož&aacute;rem bojovali až do rann&iacute;ch hodin.</p>\r\n<p data-start=\"412\" data-end=\"624\">M&iacute;stn&iacute; obyvatel&eacute; si v&scaron;imli prvn&iacute;ch plamenů kr&aacute;tce po 19. hodině a okamžitě zalarmovali hasiče. Podle svědků se oheň &scaron;&iacute;řil velmi rychle, a to i kvůli dlouhodob&eacute;mu suchu, kter&eacute; sužuje oblast v posledn&iacute;ch t&yacute;dnech.</p>\r\n<p data-start=\"626\" data-end=\"827\"><em data-start=\"626\" data-end=\"783\">\"Viděl jsem oranžovou z&aacute;ři na obloze a během několika minut byl c&iacute;tit siln&yacute; z&aacute;pach kouře. Pak začaly l&eacute;tat jiskry a sly&scaron;eli jsme prask&aacute;n&iacute; hoř&iacute;c&iacute;ch stromů,\"</em> popsal situaci jeden z m&iacute;stn&iacute;ch obyvatel.</p>\r\n<h2 data-start=\"829\" data-end=\"880\"><strong data-start=\"832\" data-end=\"878\">Nasazen&iacute; des&iacute;tek jednotek a leteck&eacute; ha&scaron;en&iacute;</strong></h2>\r\n<p data-start=\"882\" data-end=\"1195\">Kvůli rozsahu pož&aacute;ru byla na m&iacute;sto povol&aacute;na nejen profesion&aacute;ln&iacute; jednotka hasičů, ale tak&eacute; dobrovoln&iacute;ci z okoln&iacute;ch obc&iacute;. Celkem se z&aacute;sahu z&uacute;častnilo v&iacute;ce než 150 hasičů a des&iacute;tky kusů techniky. Kvůli obt&iacute;žně př&iacute;stupn&eacute;mu ter&eacute;nu musely b&yacute;t nasazeny tak&eacute; speci&aacute;ln&iacute; cisterny a drony pro monitorov&aacute;n&iacute; situace z v&yacute;&scaron;ky.</p>\r\n<p data-start=\"1197\" data-end=\"1390\">Ve večern&iacute;ch hodin&aacute;ch bylo rozhodnuto o nasazen&iacute; leteck&eacute;ho ha&scaron;en&iacute;. Hasičsk&yacute; z&aacute;chrann&yacute; sbor povolal vrtuln&iacute;k s bambivakem, kter&yacute; během noci prov&aacute;děl několik shozů vody na nejkritičtěj&scaron;&iacute; m&iacute;sta.</p>\r\n<p data-start=\"1392\" data-end=\"1602\"><em data-start=\"1392\" data-end=\"1578\">\"Hlavn&iacute;m c&iacute;lem bylo zabr&aacute;nit roz&scaron;&iacute;řen&iacute; pož&aacute;ru na přilehl&eacute; oblasti, kde se nach&aacute;zej&iacute; chaty a rekreačn&iacute; objekty. V noci jsme se soustředili na obkl&iacute;čen&iacute; ohně a vytvořen&iacute; pož&aacute;rn&iacute;ch p&aacute;sů,\"</em> uvedl velitel z&aacute;sahu.</p>\r\n<h2 data-start=\"1604\" data-end=\"1638\"><strong data-start=\"1607\" data-end=\"1636\">Evakuace a obavy m&iacute;stn&iacute;ch</strong></h2>\r\n<p data-start=\"1640\" data-end=\"1858\">Kvůli bl&iacute;zkosti obydlen&yacute;ch oblast&iacute; bylo rozhodnuto o preventivn&iacute; evakuaci několika rekreačn&iacute;ch chat a dvou men&scaron;&iacute;ch osad. Obyvatel&eacute; byli vyzv&aacute;ni k opu&scaron;těn&iacute; domovů s t&iacute;m, že se mohou vr&aacute;tit až po &uacute;pln&eacute;m uha&scaron;en&iacute; pož&aacute;ru.</p>\r\n<p data-start=\"1860\" data-end=\"2075\">V průběhu noci se na m&iacute;stě objevila tak&eacute; zdravotnick&aacute; z&aacute;chrann&aacute; služba, kter&aacute; o&scaron;etřila několik hasičů, předev&scaron;&iacute;m kvůli dehydrataci a lehk&yacute;m poraněn&iacute;m způsoben&yacute;m n&aacute;ročn&yacute;m ter&eacute;nem. Na&scaron;těst&iacute; nebyl nikdo v&aacute;žně zraněn.</p>\r\n<h2 data-start=\"2077\" data-end=\"2114\"><strong data-start=\"2080\" data-end=\"2112\">Př&iacute;čina pož&aacute;ru zat&iacute;m nezn&aacute;m&aacute;</strong></h2>\r\n<p data-start=\"2116\" data-end=\"2256\">Hasiči zat&iacute;m neozn&aacute;mili ofici&aacute;ln&iacute; př&iacute;činu pož&aacute;ru, ale mezi možn&yacute;mi sc&eacute;n&aacute;ři se hovoř&iacute; o lidsk&eacute; nedbalosti nebo samovzn&iacute;cen&iacute; such&eacute; vegetace.</p>\r\n<p data-start=\"2258\" data-end=\"2492\"><em data-start=\"2258\" data-end=\"2458\">\"Vy&scaron;etřov&aacute;n&iacute; prob&iacute;h&aacute;, ale podle prvn&iacute;ch informac&iacute; se v m&iacute;stě vyskytovali turist&eacute;, takže nelze vyloučit, že pož&aacute;r mohl b&yacute;t způsoben např&iacute;klad odhozen&yacute;m nedopalkem nebo neopatrnou manipulac&iacute; s ohněm,\"</em> sdělil mluvč&iacute; hasičsk&eacute;ho sboru.</p>\r\n<p data-start=\"2494\" data-end=\"2687\">Vzhledem k dlouhotrvaj&iacute;c&iacute;mu suchu a vysok&yacute;m teplot&aacute;m meteorologov&eacute; varuj&iacute; před dal&scaron;&iacute;mi pož&aacute;ry. Kr&aacute;lov&eacute;hradeck&yacute; kraj proto vyhl&aacute;sil z&aacute;kaz rozděl&aacute;v&aacute;n&iacute; ohně v les&iacute;ch a na voln&yacute;ch prostranstv&iacute;ch.</p>\r\n<h2 data-start=\"2689\" data-end=\"2716\"><strong data-start=\"2692\" data-end=\"2714\">Obnova potrv&aacute; roky</strong></h2>\r\n<p data-start=\"2718\" data-end=\"2993\">Ačkoliv se hasičům podařilo dostat pož&aacute;r pod kontrolu v rann&iacute;ch hodin&aacute;ch, n&aacute;sledky budou patrn&eacute; je&scaron;tě dlouho. Odborn&iacute;ci odhaduj&iacute;, že na obnovu zasažen&eacute; oblasti bude potřeba několik let. Po&scaron;kozen&eacute; stromy budou muset b&yacute;t odstraněny a n&aacute;sledně proběhne v&yacute;sadba nov&eacute;ho porostu.</p>\r\n<p data-start=\"2995\" data-end=\"3215\"><em data-start=\"2995\" data-end=\"3192\">\"Lesy jsou v&yacute;znamnou souč&aacute;st&iacute; krajiny a jejich obnova po tak rozs&aacute;hl&eacute;m pož&aacute;ru nen&iacute; jednoduch&aacute;. Budeme muset počkat, jak se postižen&aacute; oblast bude regenerovat, a podle toho napl&aacute;novat dal&scaron;&iacute; kroky,\"</em> uvedl lesn&iacute; spr&aacute;vce.</p>\r\n<h2 data-start=\"3217\" data-end=\"3254\"><strong data-start=\"3220\" data-end=\"3252\">V&yacute;straha před dal&scaron;&iacute;mi pož&aacute;ry</strong></h2>\r\n<p data-start=\"3256\" data-end=\"3452\">Meteorologov&eacute; varuj&iacute;, že v n&aacute;sleduj&iacute;c&iacute;ch dnech hroz&iacute; kvůli suchu dal&scaron;&iacute; riziko vzniku pož&aacute;rů. Obyvatelům se doporučuje zv&yacute;&scaron;en&aacute; opatrnost při pohybu v př&iacute;rodě a dodržov&aacute;n&iacute; protipož&aacute;rn&iacute;ch opatřen&iacute;.</p>\r\n<p data-start=\"3454\" data-end=\"3681\"><em data-start=\"3454\" data-end=\"3628\">\"Vysok&eacute; teploty a sucho vytv&aacute;řej&iacute; ide&aacute;ln&iacute; podm&iacute;nky pro &scaron;&iacute;řen&iacute; pož&aacute;rů. Každ&yacute; by si měl uvědomit, jak nebezpečn&eacute; může b&yacute;t např&iacute;klad neuhasen&eacute; ohni&scaron;tě nebo odhozen&aacute; cigareta,\"</em> dodal mluvč&iacute; Česk&eacute;ho hydrometeorologick&eacute;ho &uacute;stavu.</p>\r\n<p data-start=\"3683\" data-end=\"3884\" data-is-last-node=\"\" data-is-only-node=\"\">Pož&aacute;r u Trutnova je tak dal&scaron;&iacute;m varov&aacute;n&iacute;m, jak snadno může doj&iacute;t k ekologick&eacute; katastrofě. Obyvatel&eacute; i n&aacute;v&scaron;těvn&iacute;ci př&iacute;rody by proto měli db&aacute;t zv&yacute;&scaron;en&eacute; opatrnosti a dodržovat v&scaron;echna bezpečnostn&iacute; pravidla.</p>', '2025-03-04 11:12:09', '2025-03-12 15:43:34', 14, 17, 3, 4),
(126, 'Nové cyklostezky ve východních Čechách propojí hlavní turistické cíle', 'Nové cyklostezky ve východních Čechách propojí turistické cíle! ???? Už brzy se cyklisté dočkají desítek kilometrů nových tras vedoucích přes historická města, přírodní rezervace i rekreační oblasti. Projekt přinese bezpečnější cestování, ekologická opatření i podporu místní ekonomiky. Jaké změny nás čekají a kdy se nové stezky otevřou? Čtěte více v článku!', 'Východní Čechy čeká rozsáhlé rozšíření sítě cyklostezek, které propojí hlavní turistické cíle regionu. Nové trasy usnadní cykloturistiku i každodenní dojíždění a povedou přes historická města, přírodní rezervace i rekreační oblasti. Projekt klade důraz na bezpečnost, ekologii a podporu místní ekonomiky. První úseky budou dokončeny již příští rok, přičemž celý projekt se plánuje realizovat do roku 2028.', '<h1 data-start=\"0\" data-end=\"77\"><strong data-start=\"2\" data-end=\"75\">Nov&eacute; cyklostezky ve v&yacute;chodn&iacute;ch Čech&aacute;ch propoj&iacute; hlavn&iacute; turistick&eacute; c&iacute;le</strong></h1>\r\n<h2 data-start=\"79\" data-end=\"124\"><strong data-start=\"82\" data-end=\"122\">Nov&eacute; možnosti pro cyklisty i turisty</strong></h2>\r\n<p data-start=\"126\" data-end=\"541\">V&yacute;chodn&iacute; Čechy se mohou tě&scaron;it na rozs&aacute;hl&eacute; roz&scaron;&iacute;řen&iacute; s&iacute;tě cyklostezek, kter&eacute; propoj&iacute; v&yacute;znamn&eacute; turistick&eacute; c&iacute;le v regionu. Projekt, jehož realizace byla zah&aacute;jena zač&aacute;tkem leto&scaron;n&iacute;ho roku, přinese des&iacute;tky kilometrů nov&yacute;ch cyklotras vedouc&iacute;ch přes malebn&eacute; krajiny, historick&aacute; města i př&iacute;rodn&iacute; rezervace. C&iacute;lem projektu je nejen podpořit cykloturistiku, ale tak&eacute; usnadnit m&iacute;stn&iacute;m obyvatelům každodenn&iacute; doj&iacute;žděn&iacute; na kole.</p>\r\n<p data-start=\"543\" data-end=\"811\">Podle krajsk&yacute;ch &uacute;řadů a projektantů by nov&eacute; stezky měly propojit v&yacute;znamn&eacute; lokality, jako jsou Hradec Kr&aacute;lov&eacute;, Pardubice, Česk&aacute; Skalice, Adr&scaron;pach či Litomy&scaron;l. D&iacute;ky tomu se cyklist&eacute; dostanou bezpečně a pohodlně k pam&aacute;tk&aacute;m, rekreačn&iacute;m oblastem i k železničn&iacute;m stanic&iacute;m.</p>\r\n<p data-start=\"813\" data-end=\"1035\"><em data-start=\"813\" data-end=\"982\">\"Chceme vytvořit modern&iacute; s&iacute;ť cyklostezek, kter&aacute; umožn&iacute; bezpečnou a pohodlnou j&iacute;zdu nejen turistům, ale i m&iacute;stn&iacute;m lidem, kteř&iacute; využ&iacute;vaj&iacute; kolo jako dopravn&iacute; prostředek,\"</em> uvedl z&aacute;stupce kraje pro dopravu a infrastrukturu.</p>\r\n<h2 data-start=\"1037\" data-end=\"1100\"><strong data-start=\"1040\" data-end=\"1098\">Trasy povedou přes historick&aacute; města i př&iacute;rodn&iacute; oblasti</strong></h2>\r\n<p data-start=\"1102\" data-end=\"1474\">Jedn&iacute;m z hlavn&iacute;ch c&iacute;lů projektu je zlep&scaron;it dostupnost v&yacute;znamn&yacute;ch kulturn&iacute;ch a historick&yacute;ch pam&aacute;tek. Mezi pl&aacute;novan&eacute; trasy patř&iacute; např&iacute;klad cyklostezka vedouc&iacute; z Hradce Kr&aacute;lov&eacute; do Josefova, kter&aacute; zavede cyklisty k pevnostn&iacute;mu městu s bohatou histori&iacute;. Dal&scaron;&iacute; kl&iacute;čovou trasou bude spojen&iacute; Pardubic s Kunětickou horou, kde se nach&aacute;z&iacute; obl&iacute;ben&yacute; hrad a okoln&iacute; př&iacute;rodn&iacute; rezervace.</p>\r\n<p data-start=\"1476\" data-end=\"1843\">Kromě městsk&yacute;ch a historick&yacute;ch destinac&iacute; se nově budovan&eacute; stezky zaměř&iacute; i na př&iacute;rodu. Obl&iacute;ben&eacute; oblasti, jako jsou Orlick&eacute; hory, Krkono&scaron;sk&eacute; podhůř&iacute; nebo CHKO Broumovsko, se dočkaj&iacute; lep&scaron;&iacute; infrastruktury pro cyklisty. Nov&eacute; trasy budou přizpůsobeny různ&yacute;m &uacute;rovn&iacute;m obt&iacute;žnosti &ndash; od nen&aacute;ročn&yacute;ch stezek pro rodiny s dětmi až po n&aacute;ročněj&scaron;&iacute; horsk&eacute; &uacute;seky pro zku&scaron;en&eacute; cyklisty.</p>\r\n<p data-start=\"1845\" data-end=\"2124\"><em data-start=\"1845\" data-end=\"2082\">\"Přem&yacute;&scaron;leli jsme nad t&iacute;m, aby si každ&yacute; na&scaron;el svou trasu &ndash; ať už jde o rekreačn&iacute; v&yacute;let, sportovn&iacute; j&iacute;zdu nebo doj&iacute;žděn&iacute; do pr&aacute;ce. Na mnoha m&iacute;stech vzniknou tak&eacute; odpočinkov&eacute; z&oacute;ny s lavičkami, informačn&iacute;mi tabulemi a možnost&iacute; občerstven&iacute;,\"</em> doplnil projektov&yacute; manažer cyklostezek.</p>\r\n<h2 data-start=\"2126\" data-end=\"2175\"><strong data-start=\"2129\" data-end=\"2173\">Investice do bezpečnosti a udržitelnosti</strong></h2>\r\n<p data-start=\"2177\" data-end=\"2491\">Projekt je financov&aacute;n z evropsk&yacute;ch dotac&iacute; i krajsk&eacute;ho rozpočtu a klade velk&yacute; důraz na bezpečnost cyklistů. Nov&eacute; trasy budou vybaveny kvalitn&iacute;m povrchem, jasn&yacute;m značen&iacute;m a v někter&yacute;ch &uacute;sec&iacute;ch i osvětlen&iacute;m. Důležitou souč&aacute;st&iacute; je tak&eacute; budov&aacute;n&iacute; bezpečn&yacute;ch přejezdů přes frekventovan&eacute; silnice a mostů přes vodn&iacute; toky.</p>\r\n<p data-start=\"2493\" data-end=\"2718\"><em data-start=\"2493\" data-end=\"2672\">\"Na&scaron;&iacute;m c&iacute;lem je sn&iacute;žit počet nehod a vytvořit prostřed&iacute;, kde se budou cyklist&eacute; c&iacute;tit bezpečně. To znamen&aacute; nejen kvalitn&iacute; infrastrukturu, ale tak&eacute; osvětu mezi řidiči a cyklisty,\"</em> zdůraznil koordin&aacute;tor dopravn&iacute; bezpečnosti.</p>\r\n<p data-start=\"2720\" data-end=\"3041\">Zaj&iacute;mav&yacute;m aspektem projektu je tak&eacute; jeho ekologick&yacute; př&iacute;nos. Cyklostezky povedou tak, aby co nejm&eacute;ně zasahovaly do př&iacute;rody, a v někter&yacute;ch &uacute;sec&iacute;ch budou použity ekologick&eacute; stavebn&iacute; materi&aacute;ly. Kraj pl&aacute;nuje tak&eacute; v&yacute;sadbu nov&yacute;ch stromů pod&eacute;l tras, což zlep&scaron;&iacute; mikroklima a nab&iacute;dne cyklistům př&iacute;jemn&yacute; st&iacute;n během letn&iacute;ch měs&iacute;ců.</p>\r\n<h2 data-start=\"3043\" data-end=\"3086\"><strong data-start=\"3046\" data-end=\"3084\">Podpora turismu a m&iacute;stn&iacute; ekonomiky</strong></h2>\r\n<p data-start=\"3088\" data-end=\"3328\">Nov&eacute; cyklostezky by měly přin&eacute;st tak&eacute; v&yacute;razn&yacute; ekonomick&yacute; impuls pro region. Zv&yacute;&scaron;en&yacute; pohyb turistů podpoř&iacute; m&iacute;stn&iacute; podnikatele, zejm&eacute;na v oblasti gastronomie, ubytov&aacute;n&iacute; a služeb. Pod&eacute;l tras vzniknou nov&eacute; půjčovny kol, opravny i občerstven&iacute;.</p>\r\n<p data-start=\"3330\" data-end=\"3540\">Podnikatel&eacute; v cestovn&iacute;m ruchu projekt v&iacute;taj&iacute;. Mnoz&iacute; již pl&aacute;nuj&iacute; roz&scaron;&iacute;řen&iacute; sv&yacute;ch služeb o nab&iacute;dku speci&aacute;ln&iacute;ch bal&iacute;čků pro cyklisty, včetně ubytov&aacute;n&iacute; s možnost&iacute; &uacute;schovy kol či nab&iacute;jec&iacute;ch stanic pro elektrokola.</p>\r\n<p data-start=\"3542\" data-end=\"3760\"><em data-start=\"3542\" data-end=\"3716\">\"Věř&iacute;m, že nov&eacute; cyklostezky přil&aacute;kaj&iacute; v&iacute;ce turistů a pomohou oživit region. Mnoho lid&iacute; dnes d&aacute;v&aacute; přednost aktivn&iacute; dovolen&eacute;, a to je př&iacute;ležitost, kterou bychom měli využ&iacute;t,\"</em> ř&iacute;k&aacute; majitel penzionu v Orlick&yacute;ch hor&aacute;ch.</p>\r\n<h2 data-start=\"3762\" data-end=\"3807\"><strong data-start=\"3765\" data-end=\"3805\">Kdy se cyklist&eacute; dočkaj&iacute; nov&yacute;ch tras?</strong></h2>\r\n<p data-start=\"3809\" data-end=\"4058\">Prvn&iacute; &uacute;seky cyklostezek by měly b&yacute;t dokončeny již v př&iacute;&scaron;t&iacute;m roce. Hlavn&iacute; č&aacute;st projektu bude realizov&aacute;na postupně až do roku 2028. Celkem se pl&aacute;nuje vybudov&aacute;n&iacute; v&iacute;ce než 200 kilometrů nov&yacute;ch tras, kter&eacute; budou propojeny se st&aacute;vaj&iacute;c&iacute; s&iacute;t&iacute; cyklostezek.</p>\r\n<p data-start=\"4060\" data-end=\"4339\" data-is-last-node=\"\" data-is-only-node=\"\">Obyvatel&eacute; a turist&eacute; se tak mohou tě&scaron;it na bezpečněj&scaron;&iacute; a komfortněj&scaron;&iacute; cyklov&yacute;lety, kter&eacute; je provedou nejkr&aacute;sněj&scaron;&iacute;mi kouty v&yacute;chodn&iacute;ch Čech. Tento ambici&oacute;zn&iacute; projekt slibuje nejen lep&scaron;&iacute; propojen&iacute; turistick&yacute;ch c&iacute;lů, ale i celkov&eacute; zlep&scaron;en&iacute; dopravn&iacute; situace a kvality života v regionu.</p>', '2025-03-04 11:17:39', '2025-03-12 15:43:34', 1, 17, 3, 4);
INSERT INTO `clanky` (`idClanky`, `nadpis`, `upoutavka`, `uryvek`, `obsah`, `created_at`, `updated_at`, `zhlednuti`, `Uzivatele_idUzivatele`, `Kategorie_idKategorie`, `Stav_idStav`) VALUES
(127, 'Rodinné farmy v Krkonoších se potýkají s rostoucími náklady', 'Rodinné farmy v Krkonoších bojují s rostoucími náklady!  Ceny energií, krmiva i pohonných hmot rostou a ohrožují tradiční zemědělství v horských oblastech. Jak se farmáři přizpůsobují a jaké mají možnosti přežití? Čtěte více v článku!', 'Rodinné farmy v Krkonoších čelí rostoucím nákladům na krmivo, energie a údržbu, což ohrožuje jejich další existenci. Místní zemědělci hledají způsoby, jak přežít – investují do obnovitelných zdrojů, přímého prodeje a spolupráce mezi farmami. Přestože situace je složitá, mnozí věří, že tradiční hospodaření má budoucnost, zejména díky podpoře lokální ekonomiky a rozvoji agroturistiky.', '<h1 data-start=\"0\" data-end=\"67\"><strong data-start=\"2\" data-end=\"65\">Rodinn&eacute; farmy v Krkono&scaron;&iacute;ch se pot&yacute;kaj&iacute; s rostouc&iacute;mi n&aacute;klady</strong></h1>\r\n<h2 data-start=\"69\" data-end=\"133\"><strong data-start=\"72\" data-end=\"131\">Zemědělci v horsk&yacute;ch oblastech čel&iacute; st&aacute;le vět&scaron;&iacute;m v&yacute;zv&aacute;m</strong></h2>\r\n<p data-start=\"135\" data-end=\"535\">Rodinn&eacute; farmy v Krkono&scaron;&iacute;ch, kter&eacute; se po generace věnuj&iacute; chovu dobytka, pěstov&aacute;n&iacute; plodin a produkci ml&eacute;čn&yacute;ch v&yacute;robků, se v posledn&iacute;ch letech pot&yacute;kaj&iacute; s rostouc&iacute;mi provozn&iacute;mi n&aacute;klady. Stoupaj&iacute;c&iacute; ceny energi&iacute;, krmiv i pohonn&yacute;ch hmot způsobuj&iacute;, že jejich hospodařen&iacute; se st&aacute;v&aacute; st&aacute;le m&eacute;ně udržiteln&yacute;m. Mnoz&iacute; farm&aacute;ři hledaj&iacute; způsoby, jak přež&iacute;t, aniž by museli omezovat v&yacute;robu nebo propou&scaron;tět zaměstnance.</p>\r\n<p data-start=\"537\" data-end=\"830\"><em data-start=\"537\" data-end=\"757\">\"Ceny krmiva se za posledn&iacute; rok t&eacute;měř zdvojn&aacute;sobily. Elektřina a nafta n&aacute;s stoj&iacute; v&iacute;ce než kdy dř&iacute;v a do toho se zvy&scaron;uj&iacute; i n&aacute;klady na pracovn&iacute; s&iacute;lu. To v&scaron;e n&aacute;s dost&aacute;v&aacute; do situace, kdy se mus&iacute;me rozhodovat, kde u&scaron;etřit,\"</em> ř&iacute;k&aacute; Jan Horsk&yacute;, majitel mal&eacute; rodinn&eacute; farmy v oblasti Pec pod Sněžkou.</p>\r\n<h2 data-start=\"832\" data-end=\"874\"><strong data-start=\"835\" data-end=\"872\">Hlavn&iacute; faktory rostouc&iacute;ch n&aacute;kladů</strong></h2>\r\n<p data-start=\"876\" data-end=\"964\">Rodinn&eacute; farmy v Krkono&scaron;&iacute;ch čel&iacute; řadě probl&eacute;mů, kter&eacute; jejich provoz v&yacute;razně prodražuj&iacute;:</p>\r\n<ul data-start=\"966\" data-end=\"1453\">\r\n<li data-start=\"966\" data-end=\"1076\"><strong data-start=\"968\" data-end=\"984\">Drah&eacute; krmivo</strong> &ndash; Cena sena, obil&iacute; a dal&scaron;&iacute;ch krmiv vzrostla kvůli ne&uacute;rodě a zv&yacute;&scaron;en&yacute;m n&aacute;kladům na dopravu.</li>\r\n<li data-start=\"1077\" data-end=\"1178\"><strong data-start=\"1079\" data-end=\"1099\">Energie a paliva</strong> &ndash; Elektřina a pohonn&eacute; hmoty se staly jednou z největ&scaron;&iacute;ch v&yacute;dajov&yacute;ch položek.</li>\r\n<li data-start=\"1179\" data-end=\"1316\"><strong data-start=\"1181\" data-end=\"1216\">N&aacute;klady na &uacute;držbu a modernizaci</strong> &ndash; Opravy zemědělsk&eacute; techniky a investice do modernizace se kvůli zdražov&aacute;n&iacute; materi&aacute;lů prodražuj&iacute;.</li>\r\n<li data-start=\"1317\" data-end=\"1453\"><strong data-start=\"1319\" data-end=\"1344\">Administrativn&iacute; z&aacute;těž</strong> &ndash; Farm&aacute;ři se mus&iacute; vypoř&aacute;dat s č&iacute;m d&aacute;l př&iacute;sněj&scaron;&iacute;mi předpisy a byrokraci&iacute;, což vyžaduje v&iacute;ce času i financ&iacute;.</li>\r\n</ul>\r\n<p data-start=\"1455\" data-end=\"1595\">Podle statistik zemědělsk&yacute;ch organizac&iacute; se provozn&iacute; n&aacute;klady na farm&aacute;ch v horsk&yacute;ch oblastech za posledn&iacute;ch pět let zv&yacute;&scaron;ily o v&iacute;ce než 40 %.</p>\r\n<h2 data-start=\"1597\" data-end=\"1634\"><strong data-start=\"1600\" data-end=\"1632\">Jak se farm&aacute;ři přizpůsobuj&iacute;?</strong></h2>\r\n<p data-start=\"1636\" data-end=\"1786\">Navzdory složit&eacute; situaci hledaj&iacute; farm&aacute;ři způsoby, jak sn&iacute;žit sv&eacute; n&aacute;klady a udržet sv&eacute; podnik&aacute;n&iacute; v chodu. Někter&eacute; z nejčastěj&scaron;&iacute;ch strategi&iacute; zahrnuj&iacute;:</p>\r\n<ol data-start=\"1788\" data-end=\"2486\">\r\n<li data-start=\"1788\" data-end=\"1926\"><strong data-start=\"1791\" data-end=\"1816\">Vlastn&iacute; v&yacute;robu krmiva</strong> &ndash; Mnoho farm&aacute;řů začalo pěstovat v&iacute;ce vlastn&iacute;ho sena a obil&iacute;, aby sn&iacute;žili z&aacute;vislost na drah&yacute;ch dodavatel&iacute;ch.</li>\r\n<li data-start=\"1927\" data-end=\"2063\"><strong data-start=\"1930\" data-end=\"1960\">Obnoviteln&eacute; zdroje energie</strong> &ndash; Instalace sol&aacute;rn&iacute;ch panelů nebo využ&iacute;v&aacute;n&iacute; bioplynov&yacute;ch stanic pom&aacute;h&aacute; snižovat v&yacute;daje za elektřinu.</li>\r\n<li data-start=\"2064\" data-end=\"2201\"><strong data-start=\"2067\" data-end=\"2092\">Př&iacute;m&yacute; prodej produktů</strong> &ndash; M&iacute;sto prodeje do velk&yacute;ch řetězců se farm&aacute;ři zaměřuj&iacute; na lok&aacute;ln&iacute; trhy, farm&aacute;řsk&eacute; obchody a online prodej.</li>\r\n<li data-start=\"2202\" data-end=\"2341\"><strong data-start=\"2205\" data-end=\"2234\">Sd&iacute;len&iacute; techniky a zdrojů</strong> &ndash; Spolupr&aacute;ce mezi farmami v r&aacute;mci regionu umožňuje sd&iacute;len&iacute; drah&eacute;ho vybaven&iacute; a sn&iacute;žen&iacute; n&aacute;kladů na &uacute;držbu.</li>\r\n<li data-start=\"2342\" data-end=\"2486\"><strong data-start=\"2345\" data-end=\"2364\">Dotace a granty</strong> &ndash; Někteř&iacute; zemědělci se snaž&iacute; využ&iacute;vat st&aacute;tn&iacute; i evropsk&eacute; dotace na podporu ekologick&eacute;ho hospodařen&iacute; a modernizace farmy.</li>\r\n</ol>\r\n<p data-start=\"2488\" data-end=\"2731\"><em data-start=\"2488\" data-end=\"2665\">\"Mus&iacute;me b&yacute;t flexibiln&iacute; a neust&aacute;le hledat nov&eacute; cesty, jak u&scaron;etřit. Př&iacute;m&yacute; prodej na&scaron;ich ml&eacute;čn&yacute;ch v&yacute;robků a spolupr&aacute;ce s m&iacute;stn&iacute;mi restauracemi n&aacute;m pom&aacute;h&aacute; pokr&yacute;t rostouc&iacute; v&yacute;daje,\"</em> ř&iacute;k&aacute; farm&aacute;řka Kateřina Novotn&aacute; z oblasti Rokytnice nad Jizerou.</p>\r\n<h2 data-start=\"2733\" data-end=\"2781\"><strong data-start=\"2736\" data-end=\"2779\">Budoucnost rodinn&yacute;ch farem v Krkono&scaron;&iacute;ch</strong></h2>\r\n<p data-start=\"2783\" data-end=\"3013\">Přestože situace nen&iacute; jednoduch&aacute;, mnoz&iacute; farm&aacute;ři věř&iacute;, že tradičn&iacute; zemědělstv&iacute; v Krkono&scaron;&iacute;ch m&aacute; budoucnost. Kl&iacute;čem k přežit&iacute; je adaptace na nov&eacute; podm&iacute;nky, efektivněj&scaron;&iacute; hospodařen&iacute; a vět&scaron;&iacute; propojen&iacute; s turismem a lok&aacute;ln&iacute; ekonomikou.</p>\r\n<p data-start=\"3015\" data-end=\"3305\">Podle odborn&iacute;ků by mohla pomoci vět&scaron;&iacute; podpora ze strany st&aacute;tu, zjednodu&scaron;en&iacute; byrokracie a investice do modern&iacute;ch technologi&iacute;. Velk&yacute; potenci&aacute;l vid&iacute; farm&aacute;ři tak&eacute; v rozvoji agroturistiky, kter&aacute; by mohla propojit jejich činnost s rostouc&iacute;m z&aacute;jmem turistů o ekologick&eacute; farmy a lok&aacute;ln&iacute; produkty.</p>\r\n<p data-start=\"3307\" data-end=\"3535\"><em data-start=\"3307\" data-end=\"3482\">\"Lid&eacute; st&aacute;le v&iacute;ce hledaj&iacute; kvalitn&iacute; potraviny a zaj&iacute;maj&iacute; se o to, odkud poch&aacute;zej&iacute;. To je &scaron;ance pro mal&eacute; farmy, kter&eacute; mohou nab&iacute;dnout autentick&yacute; z&aacute;žitek a prvotř&iacute;dn&iacute; produkty,\"</em> dod&aacute;v&aacute; odborn&iacute;k na venkovsk&yacute; rozvoj Martin Vesel&yacute;.</p>\r\n<p data-start=\"3537\" data-end=\"3725\" data-is-last-node=\"\" data-is-only-node=\"\">Rodinn&eacute; farmy v Krkono&scaron;&iacute;ch stoj&iacute; před velkou v&yacute;zvou, ale d&iacute;ky inovac&iacute;m, spolupr&aacute;ci a podpoře m&iacute;stn&iacute;ch komunit maj&iacute; st&aacute;le &scaron;anci uspět a zachovat tradičn&iacute; zemědělstv&iacute; i pro budouc&iacute; generace.</p>', '2025-03-04 11:21:59', '2025-03-12 15:42:55', 0, 17, 2, 4),
(128, 'Pardubická chemička expanduje na zahraniční trhy', 'Pardubická chemička rozšiřuje své působení na zahraniční trhy a plánuje významné investice do moderních technologií. Jaké nové možnosti expanze firma využije a jaké výzvy ji čekají? Přečtěte si více v našem článku.', 'Pardubická chemička oznámila ambiciózní expanzi na zahraniční trhy, zejména do Evropy a Asie. Plánuje investice do moderních technologií, automatizace výroby a ekologických inovací, aby zvýšila svou konkurenceschopnost. Firma se zaměří na klíčové trhy, jako jsou Německo, Francie, Polsko, Maďarsko, Čína a Indie. Navzdory výzvám, jako jsou přísné regulace a rostoucí logistické náklady, věří ve svůj úspěch. Cílem je zvýšit podíl exportu na 60 % a otevřít zahraniční výrobní závody do roku 2030.', '<h1 data-start=\"0\" data-end=\"56\"><strong data-start=\"2\" data-end=\"54\">Pardubick&aacute; chemička expanduje na zahraničn&iacute; trhy</strong></h1>\r\n<h2 data-start=\"58\" data-end=\"111\"><strong data-start=\"61\" data-end=\"109\">Nov&eacute; investice a strategie pro glob&aacute;ln&iacute; růst</strong></h2>\r\n<p data-start=\"113\" data-end=\"547\">Pardubick&aacute; chemička, jedna z předn&iacute;ch průmyslov&yacute;ch firem v regionu, ozn&aacute;mila ambici&oacute;zn&iacute; pl&aacute;n expanze na zahraničn&iacute; trhy. Společnost, kter&aacute; se specializuje na v&yacute;robu chemick&yacute;ch l&aacute;tek pro průmyslov&eacute; i farmaceutick&eacute; &uacute;čely, chce pos&iacute;lit svou př&iacute;tomnost zejm&eacute;na v Evropě a Asii. Tento krok přich&aacute;z&iacute; v době, kdy glob&aacute;ln&iacute; chemick&yacute; průmysl čel&iacute; v&yacute;zv&aacute;m spojen&yacute;m s rostouc&iacute;mi n&aacute;klady, environment&aacute;ln&iacute;mi regulacemi a technologick&yacute;mi inovacemi.</p>\r\n<p data-start=\"549\" data-end=\"833\"><em data-start=\"549\" data-end=\"783\">\"Na&scaron;&iacute;m c&iacute;lem je nejen zv&yacute;&scaron;it export na&scaron;ich produktů, ale tak&eacute; nav&aacute;zat dlouhodob&aacute; partnerstv&iacute; s kl&iacute;čov&yacute;mi hr&aacute;či na zahraničn&iacute;ch trz&iacute;ch. Vid&iacute;me obrovsk&yacute; potenci&aacute;l v rozv&iacute;jej&iacute;c&iacute;ch se ekonomik&aacute;ch a chceme se st&aacute;t souč&aacute;st&iacute; jejich růstu,\"</em> uvedl gener&aacute;ln&iacute; ředitel společnosti Petr Nov&aacute;k.</p>\r\n<h2 data-start=\"835\" data-end=\"875\"><strong data-start=\"838\" data-end=\"873\">Kl&iacute;čov&eacute; trhy a strategick&eacute; c&iacute;le</strong></h2>\r\n<p data-start=\"877\" data-end=\"971\">Veden&iacute; chemičky se zaměřilo na několik kl&iacute;čov&yacute;ch trhů, kde vid&iacute; největ&scaron;&iacute; potenci&aacute;l pro růst:</p>\r\n<ul data-start=\"973\" data-end=\"1352\">\r\n<li data-start=\"973\" data-end=\"1120\"><strong data-start=\"975\" data-end=\"996\">Německo a Francie</strong> &ndash; D&iacute;ky siln&eacute;mu průmyslov&eacute;mu sektoru a vysok&eacute; popt&aacute;vce po specializovan&yacute;ch chemik&aacute;li&iacute;ch jsou tyto země strategick&yacute;m c&iacute;lem.</li>\r\n<li data-start=\"1121\" data-end=\"1224\"><strong data-start=\"1123\" data-end=\"1144\">Polsko a Maďarsko</strong> &ndash; Regiony s rostouc&iacute; v&yacute;robn&iacute; kapacitou a př&iacute;zniv&yacute;m podnikatelsk&yacute;m prostřed&iacute;m.</li>\r\n<li data-start=\"1225\" data-end=\"1352\"><strong data-start=\"1227\" data-end=\"1243\">Č&iacute;na a Indie</strong> &ndash; Dva největ&scaron;&iacute; trhy v Asii, kter&eacute; neust&aacute;le expanduj&iacute; v oblasti farmaceutick&eacute;ho a technologick&eacute;ho průmyslu.</li>\r\n</ul>\r\n<p data-start=\"1354\" data-end=\"1479\">Firma pl&aacute;nuje roz&scaron;&iacute;řen&iacute; exportu, investice do nov&yacute;ch v&yacute;robn&iacute;ch kapacit a otevřen&iacute; obchodn&iacute;ch zastoupen&iacute; v těchto regionech.</p>\r\n<h2 data-start=\"1481\" data-end=\"1524\"><strong data-start=\"1484\" data-end=\"1522\">Investice do modern&iacute;ch technologi&iacute;</strong></h2>\r\n<p data-start=\"1526\" data-end=\"1662\">Aby byla firma konkurenceschopn&aacute; na mezin&aacute;rodn&iacute; &uacute;rovni, investuje do inovac&iacute; a modernizace v&yacute;roby. Mezi hlavn&iacute; oblasti investic patř&iacute;:</p>\r\n<ol data-start=\"1664\" data-end=\"2043\">\r\n<li data-start=\"1664\" data-end=\"1778\"><strong data-start=\"1667\" data-end=\"1690\">Automatizace v&yacute;roby</strong> &ndash; Implementace modern&iacute;ch robotick&yacute;ch syst&eacute;mů, kter&eacute; zv&yacute;&scaron;&iacute; efektivitu a sn&iacute;ž&iacute; n&aacute;klady.</li>\r\n<li data-start=\"1779\" data-end=\"1917\"><strong data-start=\"1782\" data-end=\"1808\">Ekologick&eacute; technologie</strong> &ndash; V&yacute;voj nov&yacute;ch v&yacute;robn&iacute;ch postupů s niž&scaron;&iacute; uhl&iacute;kovou stopou, aby firma splnila př&iacute;sn&eacute; environment&aacute;ln&iacute; normy.</li>\r\n<li data-start=\"1918\" data-end=\"2043\"><strong data-start=\"1921\" data-end=\"1939\">V&yacute;zkum a v&yacute;voj</strong> &ndash; Spolupr&aacute;ce s univerzitami a v&yacute;zkumn&yacute;mi institucemi na nov&yacute;ch materi&aacute;lech a chemick&yacute;ch sloučenin&aacute;ch.</li>\r\n</ol>\r\n<p data-start=\"2045\" data-end=\"2250\"><em data-start=\"2045\" data-end=\"2203\">\"Chceme b&yacute;t nejen konkurenceschopn&iacute;, ale tak&eacute; udržitelněj&scaron;&iacute;. Investujeme do zelen&yacute;ch technologi&iacute;, kter&eacute; n&aacute;m pomohou splnit nejnověj&scaron;&iacute; ekologick&eacute; standardy,\"</em> dod&aacute;v&aacute; technologick&yacute; ředitel Martin Svoboda.</p>\r\n<h2 data-start=\"2252\" data-end=\"2285\"><strong data-start=\"2255\" data-end=\"2283\">V&yacute;zvy a přek&aacute;žky expanze</strong></h2>\r\n<p data-start=\"2287\" data-end=\"2379\">Navzdory pozitivn&iacute;m vyhl&iacute;dk&aacute;m firma čel&iacute; několika v&yacute;zv&aacute;m, kter&eacute; mohou expanzi komplikovat:</p>\r\n<ul data-start=\"2381\" data-end=\"2711\">\r\n<li data-start=\"2381\" data-end=\"2515\"><strong data-start=\"2383\" data-end=\"2402\">Př&iacute;sn&eacute; regulace</strong> &ndash; Každ&aacute; země m&aacute; sv&eacute; vlastn&iacute; předpisy a normy pro chemick&yacute; průmysl, což vyžaduje složitou certifikaci produktů.</li>\r\n<li data-start=\"2516\" data-end=\"2610\"><strong data-start=\"2518\" data-end=\"2540\">Logistick&eacute; n&aacute;klady</strong> &ndash; Rostouc&iacute; ceny dopravy a surovin mohou ovlivnit ziskovost exportu.</li>\r\n<li data-start=\"2611\" data-end=\"2711\"><strong data-start=\"2613\" data-end=\"2633\">Konkurenčn&iacute; tlak</strong> &ndash; Velk&eacute; nadn&aacute;rodn&iacute; společnosti již na trz&iacute;ch působ&iacute; a maj&iacute; siln&eacute; postaven&iacute;.</li>\r\n</ul>\r\n<p data-start=\"2713\" data-end=\"2841\">Firma v&scaron;ak věř&iacute;, že d&iacute;ky sv&eacute; dlouholet&eacute; tradici, kvalitě produktů a inovativn&iacute;mu př&iacute;stupu dok&aacute;že na zahraničn&iacute;ch trz&iacute;ch uspět.</p>\r\n<h2 data-start=\"2843\" data-end=\"2900\"><strong data-start=\"2846\" data-end=\"2898\">Budoucnost pardubick&eacute; chemičky na glob&aacute;ln&iacute; sc&eacute;ně</strong></h2>\r\n<p data-start=\"2902\" data-end=\"3158\">Expanze na mezin&aacute;rodn&iacute; trhy je pro pardubickou chemičku historick&yacute;m krokem, kter&yacute; by mohl z&aacute;sadně změnit jej&iacute; postaven&iacute; v průmyslu. Pokud se firmě podař&iacute; &uacute;spě&scaron;ně realizovat sv&eacute; pl&aacute;ny, může se st&aacute;t v&yacute;znamn&yacute;m hr&aacute;čem nejen na evropsk&eacute;m, ale i světov&eacute;m trhu.</p>\r\n<p data-start=\"3160\" data-end=\"3330\">Veden&iacute; společnosti pl&aacute;nuje v př&iacute;&scaron;t&iacute;ch pěti letech zv&yacute;&scaron;it pod&iacute;l exportu na celkov&yacute;ch tržb&aacute;ch až na <strong data-start=\"3258\" data-end=\"3266\">60 %</strong> a do roku 2030 otevř&iacute;t několik zahraničn&iacute;ch v&yacute;robn&iacute;ch z&aacute;vodů.</p>\r\n<p data-start=\"3332\" data-end=\"3562\"><em data-start=\"3332\" data-end=\"3537\">\"Nechceme jen vyv&aacute;žet na&scaron;e produkty, ale tak&eacute; se st&aacute;t souč&aacute;st&iacute; glob&aacute;ln&iacute;ho dodavatelsk&eacute;ho řetězce. Věř&iacute;me, že d&iacute;ky na&scaron;im zku&scaron;enostem a technologick&eacute;mu z&aacute;zem&iacute; m&aacute;me &scaron;anci uspět i na nejn&aacute;ročněj&scaron;&iacute;ch trz&iacute;ch,\"</em> uzav&iacute;r&aacute; ředitel Nov&aacute;k.</p>\r\n<p data-start=\"3564\" data-end=\"3738\" data-is-last-node=\"\" data-is-only-node=\"\">Pardubick&aacute; chemička tak vstupuje do nov&eacute; &eacute;ry sv&eacute;ho v&yacute;voje. Jak se j&iacute; podař&iacute; uspět na mezin&aacute;rodn&iacute; sc&eacute;ně, uk&aacute;žou n&aacute;sleduj&iacute;c&iacute; roky, kter&eacute; budou kl&iacute;čov&eacute; pro jej&iacute; dal&scaron;&iacute; směřov&aacute;n&iacute;.</p>', '2025-03-04 11:24:43', '2025-03-12 15:42:55', 9, 17, 2, 4),
(129, 'Malé pivovary ve východních Čechách hlásí rekordní poptávku', 'Malé pivovary ve východních Čechách zažívají zlaté časy. Zájem o řemeslné pivo roste, zákazníci vyhledávají nové chutě a podpora lokálních výrobců sílí. Jaké pivní styly jsou nejžádanější a jaké výzvy pivovarníky čekají? Přečtěte si více v našem článku.', 'Malé pivovary ve východních Čechách zaznamenávají rekordní poptávku díky rostoucímu zájmu o řemeslné pivo a podporu lokální výroby. Spotřebitelé vyhledávají kvalitní a originální chutě, což vede k rozšíření nabídky speciálních pivních stylů. Přestože pivovary čelí výzvám, jako jsou rostoucí náklady a konkurenční tlak, jejich budoucnost vypadá slibně. Inovace, pivní turismus a ekologická výroba mohou jejich postavení na trhu dále posílit.', '<h1 data-start=\"0\" data-end=\"67\"><strong data-start=\"2\" data-end=\"65\">Mal&eacute; pivovary ve v&yacute;chodn&iacute;ch Čech&aacute;ch hl&aacute;s&iacute; rekordn&iacute; popt&aacute;vku</strong></h1>\r\n<h2 data-start=\"69\" data-end=\"109\"><strong data-start=\"72\" data-end=\"107\">Zlat&aacute; &eacute;ra region&aacute;ln&iacute;ch pivovarů</strong></h2>\r\n<p data-start=\"111\" data-end=\"553\">Mal&eacute; pivovary ve v&yacute;chodn&iacute;ch Čech&aacute;ch zaž&iacute;vaj&iacute; neb&yacute;val&yacute; rozmach. Rostouc&iacute; z&aacute;jem o řemesln&eacute; pivo, podpora lok&aacute;ln&iacute; produkce a touha spotřebitelů po kvalitn&iacute;ch a origin&aacute;ln&iacute;ch chut&iacute;ch vedly k rekordn&iacute; popt&aacute;vce. M&iacute;stn&iacute; pivovarn&iacute;ci hl&aacute;s&iacute; n&aacute;růst prodejů jak v hospod&aacute;ch a restaurac&iacute;ch, tak i v maloobchodn&iacute;m sektoru. Tento trend je patrn&yacute; nejen u dlouhodobě zaveden&yacute;ch pivovarů, ale i u nov&yacute;ch podniků, kter&eacute; se na trhu objevily v posledn&iacute;ch letech.</p>\r\n<p data-start=\"555\" data-end=\"799\"><em data-start=\"555\" data-end=\"731\">\"Z&aacute;kazn&iacute;ci si st&aacute;le v&iacute;ce vyb&iacute;raj&iacute; pivo podle kvality a jedinečnosti. Už to nen&iacute; jen o velk&yacute;ch značk&aacute;ch, lid&eacute; chtěj&iacute; vyzkou&scaron;et něco nov&eacute;ho a ocenit tradičn&iacute; řemeslnou v&yacute;robu,\"</em> ř&iacute;k&aacute; Martin Novotn&yacute;, majitel rodinn&eacute;ho pivovaru v Hradci Kr&aacute;lov&eacute;.</p>\r\n<h2 data-start=\"801\" data-end=\"841\"><strong data-start=\"804\" data-end=\"839\">Co stoj&iacute; za rostouc&iacute; popt&aacute;vkou?</strong></h2>\r\n<p data-start=\"843\" data-end=\"949\">Hlavn&iacute; faktory, kter&eacute; přisp&iacute;vaj&iacute; k rostouc&iacute;mu z&aacute;jmu o region&aacute;ln&iacute; pivovary, lze shrnout do několika bodů:</p>\r\n<ul data-start=\"951\" data-end=\"1673\">\r\n<li data-start=\"951\" data-end=\"1065\"><strong data-start=\"953\" data-end=\"979\">Obliba řemesln&eacute;ho piva</strong> &ndash; Lid&eacute; st&aacute;le v&iacute;ce vyhled&aacute;vaj&iacute; kvalitn&iacute;, poctivě vařen&eacute; pivo s origin&aacute;ln&iacute;mi chutěmi.</li>\r\n<li data-start=\"1066\" data-end=\"1191\"><strong data-start=\"1068\" data-end=\"1094\">Podpora lok&aacute;ln&iacute; v&yacute;roby</strong> &ndash; Spotřebitel&eacute; se snaž&iacute; nakupovat od m&iacute;stn&iacute;ch producentů, č&iacute;mž podporuj&iacute; region&aacute;ln&iacute; ekonomiku.</li>\r\n<li data-start=\"1192\" data-end=\"1347\"><strong data-start=\"1194\" data-end=\"1227\">Gastro trend a pivn&iacute; turismus</strong> &ndash; N&aacute;v&scaron;těvn&iacute;ci restaurac&iacute; a pivn&iacute;ch festivalů chtěj&iacute; zaž&iacute;t něco unik&aacute;tn&iacute;ho, což mal&yacute;m pivovarům otev&iacute;r&aacute; nov&eacute; možnosti.</li>\r\n<li data-start=\"1348\" data-end=\"1515\"><strong data-start=\"1350\" data-end=\"1377\">&Scaron;irok&aacute; nab&iacute;dka speci&aacute;lů</strong> &ndash; Na rozd&iacute;l od průmyslov&yacute;ch pivovarů mohou mal&eacute; pivovary experimentovat s různ&yacute;mi styly, jako jsou IPA, Stout, Saison nebo kysel&aacute; piva.</li>\r\n<li data-start=\"1516\" data-end=\"1673\"><strong data-start=\"1518\" data-end=\"1541\">Rostouc&iacute; distribuce</strong> &ndash; Mnoho pivovarů investovalo do modern&iacute;ch technologi&iacute; a roz&scaron;&iacute;řen&iacute; distribuce, což jim umožňuje dostat sv&eacute; pivo k &scaron;ir&scaron;&iacute;mu publiku.</li>\r\n</ul>\r\n<h2 data-start=\"1675\" data-end=\"1727\"><strong data-start=\"1678\" data-end=\"1725\">Nejž&aacute;daněj&scaron;&iacute; pivn&iacute; styly a sez&oacute;nn&iacute; speci&aacute;ly</strong></h2>\r\n<p data-start=\"1729\" data-end=\"1899\">Mal&eacute; pivovary ve v&yacute;chodn&iacute;ch Čech&aacute;ch se snaž&iacute; oslovit z&aacute;kazn&iacute;ky nejen klasick&yacute;mi lež&aacute;ky, ale i pivn&iacute;mi speci&aacute;ly, kter&eacute; si rychle z&iacute;skaly oblibu. Mezi nejž&aacute;daněj&scaron;&iacute; patř&iacute;:</p>\r\n<ul data-start=\"1901\" data-end=\"2443\">\r\n<li data-start=\"1901\" data-end=\"2006\"><strong data-start=\"1903\" data-end=\"1928\">Světl&eacute; a tmav&eacute; lež&aacute;ky</strong> &ndash; Tradičn&iacute; česk&eacute; pivo, kter&eacute; st&aacute;le tvoř&iacute; z&aacute;kladn&iacute; nab&iacute;dku vět&scaron;iny pivovarů.</li>\r\n<li data-start=\"2007\" data-end=\"2123\"><strong data-start=\"2009\" data-end=\"2033\">India Pale Ale (IPA)</strong> &ndash; Hořk&aacute; a aromatick&aacute; piva s citrusov&yacute;mi a ovocn&yacute;mi t&oacute;ny, kter&aacute; jsou st&aacute;le popul&aacute;rněj&scaron;&iacute;.</li>\r\n<li data-start=\"2124\" data-end=\"2224\"><strong data-start=\"2126\" data-end=\"2144\">Stout a Porter</strong> &ndash; Siln&aacute; tmav&aacute; piva s pražen&yacute;mi t&oacute;ny k&aacute;vy a čokol&aacute;dy, ide&aacute;ln&iacute; na zimn&iacute; měs&iacute;ce.</li>\r\n<li data-start=\"2225\" data-end=\"2341\"><strong data-start=\"2227\" data-end=\"2259\">Kysel&aacute; piva (Sour Ale, Gose)</strong> &ndash; Osvěžuj&iacute;c&iacute;, lehce kysel&aacute; piva, kter&aacute; v posledn&iacute;ch letech zaž&iacute;vaj&iacute; velk&yacute; boom.</li>\r\n<li data-start=\"2342\" data-end=\"2443\"><strong data-start=\"2344\" data-end=\"2364\">Sez&oacute;nn&iacute; speci&aacute;ly</strong> &ndash; Např&iacute;klad v&aacute;nočn&iacute; medov&aacute; piva, podzimn&iacute; d&yacute;ňov&eacute; ale nebo letn&iacute; ovocn&aacute; piva.</li>\r\n</ul>\r\n<p data-start=\"2445\" data-end=\"2668\"><em data-start=\"2445\" data-end=\"2609\">\"Lid&eacute; se už neomezuj&iacute; jen na klasick&yacute; lež&aacute;k. Experimentuj&iacute; a r&aacute;di ochutn&aacute;vaj&iacute; nov&eacute; styly. Pivovary tak maj&iacute; prostor pro inovace a mohou se odli&scaron;it od konkurence,\"</em> vysvětluje sl&aacute;dek Tom&aacute;&scaron; Dvoř&aacute;k z pivovaru v Pardubic&iacute;ch.</p>\r\n<h2 data-start=\"2670\" data-end=\"2706\"><strong data-start=\"2673\" data-end=\"2704\">V&yacute;zvy, kter&yacute;m pivovary čel&iacute;</strong></h2>\r\n<p data-start=\"2708\" data-end=\"2810\">Přestože popt&aacute;vka po region&aacute;ln&iacute;ch pivech roste, mal&eacute; pivovary mus&iacute; ře&scaron;it několik z&aacute;sadn&iacute;ch probl&eacute;mů:</p>\r\n<ol data-start=\"2812\" data-end=\"3361\">\r\n<li data-start=\"2812\" data-end=\"2907\"><strong data-start=\"2815\" data-end=\"2840\">Rostouc&iacute; ceny surovin</strong> &ndash; Chmel, slad i energie zdražuj&iacute;, což zvy&scaron;uje n&aacute;klady na v&yacute;robu.</li>\r\n<li data-start=\"2908\" data-end=\"3022\"><strong data-start=\"2911\" data-end=\"2938\">Distribuce a dostupnost</strong> &ndash; Men&scaron;&iacute; pivovary nemaj&iacute; tak rozs&aacute;hlou s&iacute;ť prodejn&iacute;ch m&iacute;st jako velk&eacute; společnosti.</li>\r\n<li data-start=\"3023\" data-end=\"3142\"><strong data-start=\"3026\" data-end=\"3046\">Konkurenčn&iacute; tlak</strong> &ndash; I nadn&aacute;rodn&iacute; pivovary si v&scaron;imly trendu řemesln&eacute;ho piva a zač&iacute;naj&iacute; vyr&aacute;bět vlastn&iacute; speci&aacute;ly.</li>\r\n<li data-start=\"3143\" data-end=\"3242\"><strong data-start=\"3146\" data-end=\"3168\">Sez&oacute;nnost popt&aacute;vky</strong> &ndash; Zat&iacute;mco v l&eacute;tě je z&aacute;jem obrovsk&yacute;, v zimn&iacute;ch měs&iacute;c&iacute;ch prodeje klesaj&iacute;.</li>\r\n<li data-start=\"3243\" data-end=\"3361\"><strong data-start=\"3246\" data-end=\"3266\">Kapacitn&iacute; limity</strong> &ndash; Někter&eacute; pivovary nest&iacute;haj&iacute; pokr&yacute;t rostouc&iacute; popt&aacute;vku a mus&iacute; investovat do roz&scaron;&iacute;řen&iacute; v&yacute;roby.</li>\r\n</ol>\r\n<p data-start=\"3363\" data-end=\"3580\"><em data-start=\"3363\" data-end=\"3534\">\"Je skvěl&eacute;, že lid&eacute; maj&iacute; z&aacute;jem o na&scaron;e pivo, ale z&aacute;roveň mus&iacute;me čelit v&yacute;zv&aacute;m, kter&eacute; s t&iacute;m přich&aacute;zej&iacute;. Investujeme do roz&scaron;&iacute;řen&iacute; v&yacute;roby a hled&aacute;me nov&eacute; možnosti distribuce,\"</em> ř&iacute;k&aacute; sl&aacute;dek Jan Kr&aacute;l z pivovaru v Trutnově.</p>\r\n<h2 data-start=\"3582\" data-end=\"3639\"><strong data-start=\"3585\" data-end=\"3637\">Budoucnost mal&yacute;ch pivovarů ve v&yacute;chodn&iacute;ch Čech&aacute;ch</strong></h2>\r\n<p data-start=\"3641\" data-end=\"3846\">Přestože provoz mal&yacute;ch pivovarů nen&iacute; bez přek&aacute;žek, jejich budoucnost vypad&aacute; slibně. Oček&aacute;v&aacute; se dal&scaron;&iacute; n&aacute;růst z&aacute;jmu o lok&aacute;ln&iacute; produkci a řemesln&eacute; pivo. Kl&iacute;čov&eacute; faktory, kter&eacute; ovlivn&iacute; dal&scaron;&iacute; v&yacute;voj, zahrnuj&iacute;:</p>\r\n<ul data-start=\"3848\" data-end=\"4302\">\r\n<li data-start=\"3848\" data-end=\"3938\"><strong data-start=\"3850\" data-end=\"3877\">Inovace v pivovarnictv&iacute;</strong> &ndash; Nov&eacute; pivn&iacute; styly, experimenty s kvasinkami a surovinami.</li>\r\n<li data-start=\"3939\" data-end=\"4057\"><strong data-start=\"3941\" data-end=\"3974\">Silněj&scaron;&iacute; marketing a branding</strong> &ndash; Mal&eacute; pivovary se st&aacute;le v&iacute;ce zaměřuj&iacute; na budov&aacute;n&iacute; značky a loajality z&aacute;kazn&iacute;ků.</li>\r\n<li data-start=\"4058\" data-end=\"4157\"><strong data-start=\"4060\" data-end=\"4078\">Pivn&iacute; turismus</strong> &ndash; Prohl&iacute;dky pivovarů, ochutn&aacute;vky a pivn&iacute; festivaly přil&aacute;kaj&iacute; nov&eacute; z&aacute;kazn&iacute;ky.</li>\r\n<li data-start=\"4158\" data-end=\"4302\"><strong data-start=\"4160\" data-end=\"4181\">Ekologick&aacute; v&yacute;roba</strong> &ndash; Udržitelnost se st&aacute;v&aacute; st&aacute;le důležitěj&scaron;&iacute;m faktorem a pivovary se snaž&iacute; minimalizovat svůj dopad na životn&iacute; prostřed&iacute;.</li>\r\n</ul>\r\n<p data-start=\"4304\" data-end=\"4537\">Podle odborn&iacute;ků bude i nad&aacute;le růst segment řemesln&eacute;ho piva, a to nejen v restaurac&iacute;ch, ale i v maloobchodn&iacute;m prodeji. Mal&eacute; pivovary tak maj&iacute; před sebou velk&yacute; potenci&aacute;l a mohou se st&aacute;t je&scaron;tě důležitěj&scaron;&iacute; souč&aacute;st&iacute; česk&eacute; pivn&iacute; kultury.</p>\r\n<p data-start=\"4539\" data-end=\"4741\" data-is-last-node=\"\" data-is-only-node=\"\"><em data-start=\"4539\" data-end=\"4703\">\"Česk&aacute; republika je zn&aacute;m&aacute; jako pivn&iacute; velmoc a mal&eacute; pivovary k tomu v&yacute;znamně přisp&iacute;vaj&iacute;. Pokud budou i nad&aacute;le inovovat a držet kvalitu, ček&aacute; je skvěl&aacute; budoucnost,\"</em> uzav&iacute;r&aacute; pivovarsk&yacute; expert Petr Kov&aacute;ř.</p>', '2025-03-04 11:52:38', '2025-03-12 15:42:55', 3, 17, 2, 4),
(130, 'Nový průmyslový park v Hradci Králové přilákal významného investora', 'Hradec Králové se stává centrem technologického průmyslu. Nový průmyslový park přilákal investora světového významu, který zde plánuje vybudovat moderní výrobní závod. Jaké přínosy to přinese městu a jaké výzvy mohou nastat? Přečtěte si více v našem článku.', 'Nový průmyslový park v Hradci Králové přilákal významného investora, společnost TechnoCorp, která zde vybuduje moderní výrobní závod na polovodičové součástky. Projekt přinese miliardovou investici, stovky nových pracovních míst a podpoří technologický rozvoj regionu. Město zdůrazňuje ekologické standardy a spolupráci s univerzitami, zatímco místní obyvatelé vidí příležitosti i výzvy spojené s rozvojem průmyslu. Výstavba začne příští rok a první fáze má být dokončena do roku 2027.', '<h1 data-start=\"0\" data-end=\"75\"><strong data-start=\"2\" data-end=\"73\">Nov&yacute; průmyslov&yacute; park v Hradci Kr&aacute;lov&eacute; přil&aacute;kal v&yacute;znamn&eacute;ho investora</strong></h1>\r\n<h2 data-start=\"77\" data-end=\"126\"><strong data-start=\"80\" data-end=\"124\">Strategick&aacute; investice pro rozvoj regionu</strong></h2>\r\n<p data-start=\"128\" data-end=\"575\">Hradec Kr&aacute;lov&eacute; se st&aacute;v&aacute; důležit&yacute;m centrem průmyslu a modern&iacute;ch technologi&iacute;. Nově vznikaj&iacute;c&iacute; <strong data-start=\"220\" data-end=\"255\">průmyslov&yacute; park na okraji města</strong> se už nyn&iacute; může pochlubit prvn&iacute;m v&yacute;znamn&yacute;m investorem. Společnost <strong data-start=\"322\" data-end=\"336\">TechnoCorp</strong>, mezin&aacute;rodn&iacute; l&iacute;dr v oblasti v&yacute;roby a v&yacute;voje polovodičov&yacute;ch souč&aacute;stek, ozn&aacute;mila svůj z&aacute;měr vybudovat zde <strong data-start=\"441\" data-end=\"466\">modern&iacute; v&yacute;robn&iacute; z&aacute;vod</strong>. Tato investice přinese <strong data-start=\"491\" data-end=\"524\">stovky nov&yacute;ch pracovn&iacute;ch m&iacute;st</strong> a přispěje k dal&scaron;&iacute;mu ekonomick&eacute;mu růstu regionu.</p>\r\n<p data-start=\"577\" data-end=\"820\"><em data-start=\"577\" data-end=\"749\">\"Hradec Kr&aacute;lov&eacute; m&aacute; ide&aacute;ln&iacute; polohu, kvalitn&iacute; infrastrukturu a dostupnost kvalifikovan&eacute; pracovn&iacute; s&iacute;ly. To byly hlavn&iacute; faktory, kter&eacute; n&aacute;s přesvědčily o investici pr&aacute;vě zde,\"</em> uvedl gener&aacute;ln&iacute; ředitel společnosti TechnoCorp, <strong data-start=\"798\" data-end=\"817\">Michael Hartman</strong>.</p>\r\n<h2 data-start=\"822\" data-end=\"863\"><strong data-start=\"825\" data-end=\"861\">V&yacute;hody nov&eacute;ho průmyslov&eacute;ho parku</strong></h2>\r\n<p data-start=\"865\" data-end=\"1038\">Průmyslov&yacute; park v Hradci Kr&aacute;lov&eacute; byl navržen s důrazem na <strong data-start=\"923\" data-end=\"1001\">modern&iacute; technologie, ekologick&aacute; ře&scaron;en&iacute; a flexibiln&iacute; možnosti pro investory</strong>. Hlavn&iacute; přednosti are&aacute;lu zahrnuj&iacute;:</p>\r\n<ul data-start=\"1040\" data-end=\"1543\">\r\n<li data-start=\"1040\" data-end=\"1163\"><strong data-start=\"1042\" data-end=\"1074\">V&yacute;bornou dopravn&iacute; dostupnost</strong> &ndash; Bl&iacute;zkost d&aacute;lnice D11 spojuj&iacute;c&iacute; Hradec Kr&aacute;lov&eacute; s Prahou a dal&scaron;&iacute;mi kl&iacute;čov&yacute;mi oblastmi.</li>\r\n<li data-start=\"1164\" data-end=\"1291\"><strong data-start=\"1166\" data-end=\"1193\">Kvalitn&iacute; infrastrukturu</strong> &ndash; Modern&iacute; energetick&eacute; s&iacute;tě, dostatečn&aacute; kapacita vody a ekologick&eacute; způsoby hospodařen&iacute; s odpady.</li>\r\n<li data-start=\"1292\" data-end=\"1411\"><strong data-start=\"1294\" data-end=\"1323\">Podporu m&iacute;stn&iacute; samospr&aacute;vy</strong> &ndash; Město poskytlo investičn&iacute; pob&iacute;dky a aktivně spolupracuje na přil&aacute;k&aacute;n&iacute; nov&yacute;ch firem.</li>\r\n<li data-start=\"1412\" data-end=\"1543\"><strong data-start=\"1414\" data-end=\"1436\">Ekologick&yacute; př&iacute;stup</strong> &ndash; Důraz na využit&iacute; obnoviteln&yacute;ch zdrojů energie, minimalizaci emis&iacute; a &scaron;etrn&eacute; nakl&aacute;d&aacute;n&iacute; s vodn&iacute;mi zdroji.</li>\r\n</ul>\r\n<p data-start=\"1545\" data-end=\"1739\"><em data-start=\"1545\" data-end=\"1694\">\"Chceme, aby tento park byl vzorem pro modern&iacute; průmyslov&eacute; z&oacute;ny v Česk&eacute; republice. Udržiteln&yacute; rozvoj a inovace jsou kl&iacute;čem k dlouhodob&eacute; prosperitě,\"</em> doplnil n&aacute;městek prim&aacute;tora <strong data-start=\"1722\" data-end=\"1736\">Petr Nov&aacute;k</strong>.</p>\r\n<h2 data-start=\"1741\" data-end=\"1794\"><strong data-start=\"1744\" data-end=\"1792\">Co přinese investice společnosti TechnoCorp?</strong></h2>\r\n<p data-start=\"1796\" data-end=\"2018\">TechnoCorp pl&aacute;nuje v průmyslov&eacute;m parku vybudovat <strong data-start=\"1845\" data-end=\"1875\">v&yacute;robn&iacute; a v&yacute;vojov&eacute; centrum</strong>, kter&eacute; se zaměř&iacute; na v&yacute;robu polovodičov&yacute;ch souč&aacute;stek pro <strong data-start=\"1932\" data-end=\"1971\">automobilov&yacute; a elektronick&yacute; průmysl</strong>. Projekt zahrnuje několik kl&iacute;čov&yacute;ch aspektů:</p>\r\n<ol data-start=\"2020\" data-end=\"2589\">\r\n<li data-start=\"2020\" data-end=\"2156\"><strong data-start=\"2023\" data-end=\"2060\">Investice ve v&yacute;&scaron;i 2 miliard korun</strong> &ndash; Modern&iacute; z&aacute;vod bude vybaven nejnověj&scaron;&iacute;mi technologiemi a automatizovan&yacute;mi v&yacute;robn&iacute;mi linkami.</li>\r\n<li data-start=\"2157\" data-end=\"2300\"><strong data-start=\"2160\" data-end=\"2196\">Vytvořen&iacute; až 500 pracovn&iacute;ch m&iacute;st</strong> &ndash; Oček&aacute;v&aacute; se n&aacute;bor odborn&iacute;ků v oblasti elektrotechniky, v&yacute;voje softwaru i obsluhy v&yacute;robn&iacute;ch zař&iacute;zen&iacute;.</li>\r\n<li data-start=\"2301\" data-end=\"2474\"><strong data-start=\"2304\" data-end=\"2333\">Spolupr&aacute;ce s univerzitami</strong> &ndash; Společnost pl&aacute;nuje &uacute;zkou spolupr&aacute;ci s <strong data-start=\"2374\" data-end=\"2404\">Univerzitou Hradec Kr&aacute;lov&eacute;</strong> a dal&scaron;&iacute;mi vzděl&aacute;vac&iacute;mi institucemi, aby podpořila v&yacute;zkum a inovace.</li>\r\n<li data-start=\"2475\" data-end=\"2589\"><strong data-start=\"2478\" data-end=\"2499\">Ekologick&aacute; v&yacute;roba</strong> &ndash; Z&aacute;vod bude využ&iacute;vat <strong data-start=\"2522\" data-end=\"2586\">sol&aacute;rn&iacute; panely, recyklaci vody a n&iacute;zkoemisn&iacute; v&yacute;robn&iacute; procesy</strong>.</li>\r\n</ol>\r\n<p data-start=\"2591\" data-end=\"2806\"><em data-start=\"2591\" data-end=\"2763\">\"Na&scaron;e technologie maj&iacute; &scaron;irok&eacute; využit&iacute; v automobilov&eacute;m sektoru, zejm&eacute;na v oblasti elektromobility. D&iacute;ky tomuto z&aacute;vodu budeme moci efektivně reagovat na rostouc&iacute; popt&aacute;vku,\"</em> dodal ředitel v&yacute;voje <strong data-start=\"2785\" data-end=\"2803\">Andreas M&uuml;ller</strong>.</p>\r\n<h2 data-start=\"2808\" data-end=\"2855\"><strong data-start=\"2811\" data-end=\"2853\">Reakce m&iacute;stn&iacute;ch obyvatel a podnikatelů</strong></h2>\r\n<p data-start=\"2857\" data-end=\"3135\">Nov&aacute; investice v regionu vzbudila <strong data-start=\"2891\" data-end=\"2911\">pozitivn&iacute; ohlasy</strong> nejen mezi představiteli města, ale i mezi m&iacute;stn&iacute;mi podnikateli a obyvateli. Podle <strong data-start=\"2995\" data-end=\"3022\">průzkumu mezi obyvateli</strong> vn&iacute;maj&iacute; lid&eacute; tento projekt jako <strong data-start=\"3055\" data-end=\"3098\">př&iacute;ležitost pro zlep&scaron;en&iacute; životn&iacute; &uacute;rovně</strong> a zv&yacute;&scaron;en&iacute; nab&iacute;dky pracovn&iacute;ch m&iacute;st.</p>\r\n<p data-start=\"3137\" data-end=\"3334\"><em data-start=\"3137\" data-end=\"3258\">\"M&aacute;m radost, že se v Hradci Kr&aacute;lov&eacute; rozv&iacute;j&iacute; modern&iacute; průmysl. Může to přil&aacute;kat mlad&eacute; odborn&iacute;ky a pomoci m&iacute;stn&iacute;m firm&aacute;m,\"</em> uvedl podnikatel <strong data-start=\"3276\" data-end=\"3292\">Karel Dvoř&aacute;k</strong>, kter&yacute; provozuje technologick&yacute; startup.</p>\r\n<p data-start=\"3336\" data-end=\"3566\">Na druhou stranu někteř&iacute; <strong data-start=\"3361\" data-end=\"3422\">ekologičt&iacute; aktivist&eacute; upozorňuj&iacute; na možn&eacute; negativn&iacute; dopady</strong> projektu na životn&iacute; prostřed&iacute;. Město v&scaron;ak uji&scaron;ťuje, že průmyslov&yacute; park byl navržen s důrazem na <strong data-start=\"3519\" data-end=\"3563\">ekologick&eacute; standardy a udržiteln&yacute; rozvoj</strong>.</p>\r\n<p data-start=\"3568\" data-end=\"3735\"><em data-start=\"3568\" data-end=\"3679\">\"Budeme pečlivě sledovat dopad na životn&iacute; prostřed&iacute; a zajist&iacute;me, aby byly dodrženy v&scaron;echny ekologick&eacute; normy,\"</em> uvedla radn&iacute; pro životn&iacute; prostřed&iacute; <strong data-start=\"3715\" data-end=\"3732\">Anna Hor&aacute;kov&aacute;</strong>.</p>\r\n<h2 data-start=\"3737\" data-end=\"3758\"><strong data-start=\"3740\" data-end=\"3756\">Co bude d&aacute;l?</strong></h2>\r\n<p data-start=\"3760\" data-end=\"4039\">TechnoCorp pl&aacute;nuje zah&aacute;jit <strong data-start=\"3787\" data-end=\"3841\">v&yacute;stavbu sv&eacute;ho z&aacute;vodu již na zač&aacute;tku př&iacute;&scaron;t&iacute;ho roku</strong>, přičemž prvn&iacute; f&aacute;ze projektu by měla b&yacute;t dokončena do <strong data-start=\"3896\" data-end=\"3915\">konce roku 2027</strong>. Město Hradec Kr&aacute;lov&eacute; mezit&iacute;m <strong data-start=\"3946\" data-end=\"3989\">jedn&aacute; s dal&scaron;&iacute;mi potenci&aacute;ln&iacute;mi investory</strong>, kteř&iacute; by mohli do průmyslov&eacute;ho parku vstoupit.</p>\r\n<p data-start=\"4041\" data-end=\"4313\">Podle odborn&iacute;ků m&aacute; tento projekt <strong data-start=\"4074\" data-end=\"4132\">potenci&aacute;l st&aacute;t se kl&iacute;čov&yacute;m prvkem region&aacute;ln&iacute; ekonomiky</strong>. D&iacute;ky kombinaci modern&iacute; v&yacute;roby, inovac&iacute; a ekologick&yacute;ch opatřen&iacute; může Hradec Kr&aacute;lov&eacute; upevnit svou pozici jako <strong data-start=\"4242\" data-end=\"4310\">jednoho z nejv&yacute;znamněj&scaron;&iacute;ch průmyslov&yacute;ch center v Česk&eacute; republice</strong>.</p>\r\n<p data-start=\"4315\" data-end=\"4505\" data-is-last-node=\"\" data-is-only-node=\"\"><em data-start=\"4315\" data-end=\"4468\">\"Tento projekt je jen zač&aacute;tek. Věř&iacute;me, že průmyslov&yacute; park přil&aacute;k&aacute; dal&scaron;&iacute; inovativn&iacute; společnosti a přinese dlouhodob&yacute; ekonomick&yacute; př&iacute;nos pro cel&yacute; region,\"</em> uzav&iacute;r&aacute; prim&aacute;tor města <strong data-start=\"4492\" data-end=\"4504\">Jan Mal&yacute;</strong>.</p>', '2025-03-04 11:57:21', '2025-03-12 15:42:55', 16, 17, 2, 4),
(131, 'Trh práce v regionu: Kde najdete nejvíce volných míst?', 'Hledáte práci v regionu? Největší poptávka je po technických profesích, zdravotnících a pracovnících ve stavebnictví či logistice. Kde najdete nejvíce volných míst a jak zvýšit své šance na úspěch? Přečtěte si více v našem článku.', 'Trh práce v regionu prochází dynamickými změnami, přičemž největší poptávka je po technických profesích, zdravotnících, pracovnících ve stavebnictví a logistice. Města jako Hradec Králové a Pardubice nabízejí široké možnosti uplatnění v IT, průmyslu i službách. Pro zvýšení šancí na získání zaměstnání je klíčové investovat do vzdělání, sledovat pracovní nabídky a aktivně se zapojit do trhu práce.', '<p data-start=\"0\" data-end=\"60\"><strong data-start=\"0\" data-end=\"58\">Trh pr&aacute;ce v regionu: Kde najdete nejv&iacute;ce voln&yacute;ch m&iacute;st?</strong></p>\r\n<p data-start=\"62\" data-end=\"319\">Situace na trhu pr&aacute;ce se neust&aacute;le vyv&iacute;j&iacute; a v posledn&iacute;ch měs&iacute;c&iacute;ch do&scaron;lo k v&yacute;razn&yacute;m změn&aacute;m v nab&iacute;dce pracovn&iacute;ch pozic v různ&yacute;ch odvětv&iacute;ch. Zat&iacute;mco někter&eacute; sektory čel&iacute; nedostatku kvalifikovan&yacute;ch pracovn&iacute;ků, jin&eacute; se pot&yacute;kaj&iacute; s vy&scaron;&scaron;&iacute; konkurenc&iacute; mezi uchazeči.</p>\r\n<h2 data-start=\"321\" data-end=\"360\"><strong data-start=\"324\" data-end=\"358\">Nejž&aacute;daněj&scaron;&iacute; profese v regionu</strong></h2>\r\n<p data-start=\"361\" data-end=\"482\">Podle aktu&aacute;ln&iacute;ch statistik &uacute;řadu pr&aacute;ce a pracovn&iacute;ch port&aacute;lů jsou v na&scaron;em regionu nejv&iacute;ce popt&aacute;van&eacute; n&aacute;sleduj&iacute;c&iacute; profese:</p>\r\n<ul data-start=\"484\" data-end=\"1384\">\r\n<li data-start=\"484\" data-end=\"724\"><strong data-start=\"486\" data-end=\"505\">Technick&eacute; obory</strong> &ndash; Firmy z oblasti stroj&iacute;renstv&iacute;, elektrotechniky a informačn&iacute;ch technologi&iacute; dlouhodobě hledaj&iacute; odborn&iacute;ky s prax&iacute;. Největ&scaron;&iacute; popt&aacute;vka je po <strong data-start=\"644\" data-end=\"721\">v&yacute;voj&aacute;ř&iacute;ch software, IT administr&aacute;torech, elektrik&aacute;ř&iacute;ch a CNC oper&aacute;torech</strong>.</li>\r\n<li data-start=\"725\" data-end=\"962\"><strong data-start=\"727\" data-end=\"760\">Zdravotnictv&iacute; a soci&aacute;ln&iacute; p&eacute;če</strong> &ndash; Nemocnice, domovy seniorů i soukrom&eacute; kliniky st&aacute;le hledaj&iacute; <strong data-start=\"822\" data-end=\"863\">zdravotn&iacute; sestry, l&eacute;kaře a pečovatele</strong>. Nedostatek person&aacute;lu v těchto oborech je dlouhodob&yacute; probl&eacute;m, kter&yacute; se pandemie jen prohloubila.</li>\r\n<li data-start=\"963\" data-end=\"1169\"><strong data-start=\"965\" data-end=\"1000\">Stavebnictv&iacute; a řemesln&eacute; profese</strong> &ndash; S rostouc&iacute; v&yacute;stavbou nov&yacute;ch projektů je velk&aacute; popt&aacute;vka po <strong data-start=\"1061\" data-end=\"1112\">zedn&iacute;c&iacute;ch, tesař&iacute;ch, klemp&iacute;ř&iacute;ch a instalat&eacute;rech</strong>. Z&aacute;jem je tak&eacute; o odborn&iacute;ky na rekonstrukce a renovace.</li>\r\n<li data-start=\"1170\" data-end=\"1384\"><strong data-start=\"1172\" data-end=\"1194\">Obchod a logistika</strong> &ndash; Růst e-commerce znamen&aacute; v&iacute;ce pracovn&iacute;ch m&iacute;st v <strong data-start=\"1244\" data-end=\"1297\">skladov&eacute; logistice, dopravě a z&aacute;kaznick&eacute;m servisu</strong>. Pracovn&iacute;ci expedice, řidiči n&aacute;kladn&iacute;ch aut i kur&yacute;ři maj&iacute; &scaron;irok&eacute; možnosti uplatněn&iacute;.</li>\r\n</ul>\r\n<h2 data-start=\"1386\" data-end=\"1438\"><strong data-start=\"1389\" data-end=\"1436\">Města s největ&scaron;&iacute;m počtem pracovn&iacute;ch nab&iacute;dek</strong></h2>\r\n<p data-start=\"1439\" data-end=\"1529\">V jednotliv&yacute;ch městech regionu se situace na trhu pr&aacute;ce li&scaron;&iacute; podle dominantn&iacute;ch odvětv&iacute;.</p>\r\n<h3 data-start=\"1531\" data-end=\"1555\"><strong data-start=\"1535\" data-end=\"1553\">Hradec Kr&aacute;lov&eacute;</strong></h3>\r\n<p data-start=\"1556\" data-end=\"1852\">Hlavn&iacute; město regionu nab&iacute;z&iacute; největ&scaron;&iacute; počet voln&yacute;ch m&iacute;st v administrativě, IT a zdravotnictv&iacute;. Univerzitn&iacute; nemocnice pravidelně přij&iacute;m&aacute; zdravotn&iacute;ky a fakultn&iacute; instituce hledaj&iacute; nov&eacute; vědeck&eacute; pracovn&iacute;ky. Siln&aacute; je tak&eacute; popt&aacute;vka po pracovn&iacute;c&iacute;ch v oblasti služeb, zejm&eacute;na v gastronomii a hotelnictv&iacute;.</p>\r\n<h3 data-start=\"1854\" data-end=\"1873\"><strong data-start=\"1858\" data-end=\"1871\">Pardubice</strong></h3>\r\n<p data-start=\"1874\" data-end=\"2108\">Město s v&yacute;znamnou průmyslovou z&aacute;kladnou se soustřed&iacute; na chemick&yacute; průmysl, automobilov&yacute; sektor a logistiku. Pardubick&aacute; chemička roz&scaron;iřuje v&yacute;robu a hled&aacute; nov&eacute; zaměstnance, zat&iacute;mco sklady e-shopů potřebuj&iacute; oper&aacute;tory na tř&iacute;děn&iacute; z&aacute;silek.</p>\r\n<h3 data-start=\"2110\" data-end=\"2136\"><strong data-start=\"2114\" data-end=\"2134\">Trutnov a N&aacute;chod</strong></h3>\r\n<p data-start=\"2137\" data-end=\"2390\">V těchto městech se soustřeďuj&iacute; pracovn&iacute; m&iacute;sta v tradičn&iacute;m průmyslu, jako je textiln&iacute; v&yacute;roba a zpracov&aacute;n&iacute; kovů. Popt&aacute;vka po řemesln&iacute;c&iacute;ch a technick&yacute;ch pracovn&iacute;c&iacute;ch je zde stabiln&iacute;, ale kvůli niž&scaron;&iacute;m mzd&aacute;m doch&aacute;z&iacute; k odlivu pracovn&iacute; s&iacute;ly do vět&scaron;&iacute;ch měst.</p>\r\n<h2 data-start=\"2392\" data-end=\"2439\"><strong data-start=\"2395\" data-end=\"2437\">Jak zv&yacute;&scaron;it sv&eacute; &scaron;ance na z&iacute;sk&aacute;n&iacute; pr&aacute;ce?</strong></h2>\r\n<p data-start=\"2440\" data-end=\"2522\">Konkurence na pracovn&iacute;m trhu je vysok&aacute;, a proto je důležit&eacute; b&yacute;t dobře připraven.</p>\r\n<ol data-start=\"2524\" data-end=\"2974\">\r\n<li data-start=\"2524\" data-end=\"2608\"><strong data-start=\"2527\" data-end=\"2553\">Aktualizujte životopis</strong> &ndash; Jasně uveďte sv&eacute; zku&scaron;enosti, dovednosti a &uacute;spěchy.</li>\r\n<li data-start=\"2609\" data-end=\"2739\"><strong data-start=\"2612\" data-end=\"2640\">Z&iacute;skejte nov&eacute; dovednosti</strong> &ndash; Kurzy a certifikace v IT, jazyc&iacute;ch nebo technick&yacute;ch oborech mohou zv&yacute;&scaron;it va&scaron;i hodnotu na trhu.</li>\r\n<li data-start=\"2740\" data-end=\"2844\"><strong data-start=\"2743\" data-end=\"2763\">Hledejte aktivně</strong> &ndash; Sledujte pracovn&iacute; port&aacute;ly, soci&aacute;ln&iacute; s&iacute;tě i nab&iacute;dky př&iacute;mo na str&aacute;nk&aacute;ch firem.</li>\r\n<li data-start=\"2845\" data-end=\"2974\"><strong data-start=\"2848\" data-end=\"2874\">Využijte rekvalifikaci</strong> &ndash; Pokud se nemůžete uplatnit ve sv&eacute;m oboru, rekvalifikačn&iacute; kurzy v&aacute;m mohou otevř&iacute;t nov&eacute; možnosti.</li>\r\n</ol>\r\n<h2 data-start=\"2976\" data-end=\"3006\"><strong data-start=\"2979\" data-end=\"3004\">Budoucnost trhu pr&aacute;ce</strong></h2>\r\n<p data-start=\"3007\" data-end=\"3232\">Oček&aacute;v&aacute; se, že trh pr&aacute;ce bude v n&aacute;sleduj&iacute;c&iacute;ch letech ovlivněn automatizac&iacute;, digitalizac&iacute; a změnami v ekonomice. Profese spojen&eacute; s technologiemi budou nad&aacute;le růst, zat&iacute;mco někter&eacute; manu&aacute;ln&iacute; pr&aacute;ce mohou b&yacute;t nahrazov&aacute;ny stroji.</p>\r\n<p data-start=\"3234\" data-end=\"3440\" data-is-last-node=\"\" data-is-only-node=\"\">Pokud hled&aacute;te pr&aacute;ci v na&scaron;em regionu, zaměřte se na obory s dlouhodobou perspektivou a investujte do sv&eacute;ho profesn&iacute;ho růstu. Možnost&iacute; je mnoho a spr&aacute;vn&aacute; strategie v&aacute;m pomůže naj&iacute;t ide&aacute;ln&iacute; pracovn&iacute; uplatněn&iacute;.</p>', '2025-03-04 12:01:25', '2025-03-12 15:42:55', 1, 17, 2, 4);
INSERT INTO `clanky` (`idClanky`, `nadpis`, `upoutavka`, `uryvek`, `obsah`, `created_at`, `updated_at`, `zhlednuti`, `Uzivatele_idUzivatele`, `Kategorie_idKategorie`, `Stav_idStav`) VALUES
(132, 'Hudební festival v Litomyšli přivítá světové hvězdy', 'Litomyšl se opět stane centrem hudebního dění! Připravte se na nezapomenutelné koncerty světových hvězd i domácích talentů v jedinečné atmosféře historického města. Festival nabídne pestrý program, doprovodné akce a hudební zážitky pro všechny generace.', 'Hudební festival v Litomyšli přivítá významné světové i české umělce a nabídne pestrý program zahrnující klasickou hudbu, jazz i moderní žánry. Koncerty se uskuteční v historických prostorách města a doprovodný program nabídne workshopy, besedy i prohlídky. Festival spojuje generace a přináší jedinečný kulturní zážitek.', '<article class=\"w-full text-token-text-primary focus-visible:outline-2 focus-visible:outline-offset-[-4px]\" dir=\"auto\" data-testid=\"conversation-turn-87\" data-scroll-anchor=\"true\">\r\n<div class=\"m-auto text-base py-[18px] px-6\">\r\n<div class=\"mx-auto flex flex-1 text-base gap-4 md:gap-5 lg:gap-6 md:max-w-3xl lg:max-w-[40rem] xl:max-w-[48rem]\">\r\n<div class=\"group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn @xs/thread:px-0 @sm/thread:px-1.5 @md/thread:px-4\">\r\n<div class=\"flex-col gap-1 md:gap-3\">\r\n<div class=\"flex max-w-full flex-col flex-grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 whitespace-normal break-words text-start [.text-message+&amp;]:mt-5\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"6c5033ca-8ad3-44d1-be8b-7bcf1b953a21\" data-message-model-slug=\"gpt-4o\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\">\r\n<div class=\"markdown prose w-full break-words dark:prose-invert light\">\r\n<h1 data-start=\"0\" data-end=\"59\"><strong data-start=\"2\" data-end=\"57\">Hudebn&iacute; festival v Litomy&scaron;li přiv&iacute;t&aacute; světov&eacute; hvězdy</strong></h1>\r\n<p data-start=\"61\" data-end=\"379\">Litomy&scaron;l se i letos stane centrem hudebn&iacute;ho děn&iacute;. Tradičn&iacute; <strong data-start=\"120\" data-end=\"140\">hudebn&iacute; festival</strong>, kter&yacute; m&aacute; dlouholetou tradici, opět nab&iacute;dne pestr&yacute; program pln&yacute; v&yacute;znamn&yacute;ch interpretů z cel&eacute;ho světa. Milovn&iacute;ci klasick&eacute; hudby, jazzu i modern&iacute;ch ž&aacute;nrů se mohou tě&scaron;it na <strong data-start=\"311\" data-end=\"346\">nezapomenuteln&eacute; hudebn&iacute; z&aacute;žitky</strong> v kulis&aacute;ch historick&eacute;ho města.</p>\r\n<h2 data-start=\"381\" data-end=\"421\"><strong data-start=\"384\" data-end=\"419\">Hlavn&iacute; hvězdy leto&scaron;n&iacute;ho ročn&iacute;ku</strong></h2>\r\n<p data-start=\"423\" data-end=\"551\">Letos na festival zav&iacute;taj&iacute; <strong data-start=\"450\" data-end=\"477\">v&yacute;znamn&iacute; světov&iacute; umělci</strong>, kteř&iacute; představ&iacute; &scaron;pičkov&aacute; hudebn&iacute; vystoupen&iacute;. Mezi hlavn&iacute; hvězdy patř&iacute;:</p>\r\n<ul data-start=\"553\" data-end=\"958\">\r\n<li data-start=\"553\" data-end=\"674\"><strong data-start=\"555\" data-end=\"589\">Renomovan&yacute; symfonick&yacute; orchestr</strong> z Berl&iacute;na, kter&yacute; zah&aacute;j&iacute; festival slavnostn&iacute;m koncertem s d&iacute;ly Mozarta a Beethovena</li>\r\n<li data-start=\"675\" data-end=\"773\"><strong data-start=\"677\" data-end=\"715\">Italsk&aacute; opern&iacute; pěvkyně Maria Conti</strong>, zn&aacute;m&aacute; sv&yacute;m vystoupen&iacute;m v La Scale a Metropolitn&iacute; opeře</li>\r\n<li data-start=\"774\" data-end=\"863\"><strong data-start=\"776\" data-end=\"812\">Virtu&oacute;zn&iacute; klav&iacute;rista David Huang</strong>, kter&yacute; zahraje slavn&eacute; son&aacute;ty Chopina a Schumanna</li>\r\n<li data-start=\"864\" data-end=\"958\"><strong data-start=\"866\" data-end=\"904\">Jazzov&yacute; soubor New Orleans Quartet</strong>, přin&aacute;&scaron;ej&iacute;c&iacute; autentick&eacute; jazzov&eacute; melodie př&iacute;mo z USA</li>\r\n</ul>\r\n<p data-start=\"960\" data-end=\"1136\">Kromě těchto ikon hudebn&iacute; sc&eacute;ny se na festivalu představ&iacute; i <strong data-start=\"1020\" data-end=\"1061\">řada talentovan&yacute;ch česk&yacute;ch interpretů</strong>, kteř&iacute; sv&yacute;mi v&yacute;kony dokazuj&iacute;, že tuzemsk&aacute; hudebn&iacute; sc&eacute;na m&aacute; co nab&iacute;dnout.</p>\r\n<h2 data-start=\"1138\" data-end=\"1180\"><strong data-start=\"1141\" data-end=\"1178\">Program pln&yacute; hudebn&iacute; rozmanitosti</strong></h2>\r\n<p data-start=\"1182\" data-end=\"1340\">Festival v Litomy&scaron;li si zakl&aacute;d&aacute; na tom, že propojuje <strong data-start=\"1235\" data-end=\"1258\">různ&eacute; hudebn&iacute; ž&aacute;nry</strong> a nab&iacute;z&iacute; n&aacute;v&scaron;těvn&iacute;kům &scaron;irok&eacute; spektrum koncertn&iacute;ch vystoupen&iacute;. Program zahrnuje:</p>\r\n<h3 data-start=\"1342\" data-end=\"1369\"><strong data-start=\"1346\" data-end=\"1367\">1. Klasick&aacute; hudba</strong></h3>\r\n<ul data-start=\"1370\" data-end=\"1531\">\r\n<li data-start=\"1370\" data-end=\"1413\">Symfonick&eacute; koncerty světov&yacute;ch orchestrů</li>\r\n<li data-start=\"1414\" data-end=\"1470\">Opern&iacute; večery s největ&scaron;&iacute;mi hity světov&eacute; opern&iacute; sc&eacute;ny</li>\r\n<li data-start=\"1471\" data-end=\"1531\">S&oacute;listick&aacute; vystoupen&iacute; na klav&iacute;r, housle a dal&scaron;&iacute; n&aacute;stroje</li>\r\n</ul>\r\n<h3 data-start=\"1533\" data-end=\"1558\"><strong data-start=\"1537\" data-end=\"1556\">2. Jazz a swing</strong></h3>\r\n<ul data-start=\"1559\" data-end=\"1656\">\r\n<li data-start=\"1559\" data-end=\"1604\">Večery věnovan&eacute; tradičn&iacute;mu jazzu a swingu</li>\r\n<li data-start=\"1605\" data-end=\"1656\">Speci&aacute;ln&iacute; programy s modern&iacute;mi jazzov&yacute;mi f&uacute;zemi</li>\r\n</ul>\r\n<h3 data-start=\"1658\" data-end=\"1701\"><strong data-start=\"1662\" data-end=\"1699\">3. Experiment&aacute;ln&iacute; a modern&iacute; hudba</strong></h3>\r\n<ul data-start=\"1702\" data-end=\"1784\">\r\n<li data-start=\"1702\" data-end=\"1745\">Elektronick&eacute; variace na klasick&aacute; t&eacute;mata</li>\r\n<li data-start=\"1746\" data-end=\"1784\">Propojen&iacute; hudby s vizu&aacute;ln&iacute;m uměn&iacute;m</li>\r\n</ul>\r\n<p data-start=\"1786\" data-end=\"1924\">Tato &scaron;irok&aacute; &scaron;k&aacute;la ž&aacute;nrů umožňuje, aby si <strong data-start=\"1827\" data-end=\"1872\">každ&yacute; n&aacute;v&scaron;těvn&iacute;k na&scaron;el svůj obl&iacute;ben&yacute; styl</strong> a mohl si už&iacute;t festival přesně podle sv&eacute;ho vkusu.</p>\r\n<h2 data-start=\"1926\" data-end=\"1982\"><strong data-start=\"1929\" data-end=\"1980\">Nezapomenuteln&eacute; koncerty v jedinečn&eacute;m prostřed&iacute;</strong></h2>\r\n<p data-start=\"1984\" data-end=\"2170\">Festival se kon&aacute; na několika m&iacute;stech po cel&eacute;m městě, přičemž hlavn&iacute; ději&scaron;tě tvoř&iacute; <strong data-start=\"2066\" data-end=\"2089\">historick&eacute; prostory</strong>, kter&eacute; dod&aacute;vaj&iacute; koncertům nezaměnitelnou atmosf&eacute;ru. Mezi nejv&yacute;znamněj&scaron;&iacute; patř&iacute;:</p>\r\n<ul data-start=\"2172\" data-end=\"2403\">\r\n<li data-start=\"2172\" data-end=\"2245\"><strong data-start=\"2174\" data-end=\"2203\">Z&aacute;meck&eacute; n&aacute;dvoř&iacute; Litomy&scaron;le</strong> &ndash; ikonick&eacute; m&iacute;sto s jedinečnou akustikou</li>\r\n<li data-start=\"2246\" data-end=\"2325\"><strong data-start=\"2248\" data-end=\"2281\">Kostel Pov&yacute;&scaron;en&iacute; svat&eacute;ho Kř&iacute;že</strong> &ndash; ide&aacute;ln&iacute; pro duchovn&iacute; a komorn&iacute; koncerty</li>\r\n<li data-start=\"2326\" data-end=\"2403\"><strong data-start=\"2328\" data-end=\"2347\">Městsk&eacute; divadlo</strong> &ndash; modern&iacute; prostor pro experiment&aacute;ln&iacute; hudebn&iacute; projekty</li>\r\n</ul>\r\n<p data-start=\"2405\" data-end=\"2511\">Každ&eacute; m&iacute;sto m&aacute; svůj specifick&yacute; charakter a umožňuje, aby hudba zazněla <strong data-start=\"2476\" data-end=\"2508\">v nejlep&scaron;&iacute;m možn&eacute;m proveden&iacute;</strong>.</p>\r\n<h2 data-start=\"2513\" data-end=\"2561\"><strong data-start=\"2516\" data-end=\"2559\">Doprovodn&yacute; program pro v&scaron;echny generace</strong></h2>\r\n<p data-start=\"2563\" data-end=\"2663\">Festival nen&iacute; jen o hudbě, ale tak&eacute; o <strong data-start=\"2601\" data-end=\"2631\">celkov&eacute;m kulturn&iacute;m z&aacute;žitku</strong>. Doprovodn&yacute; program zahrnuje:</p>\r\n<ul data-start=\"2665\" data-end=\"2836\">\r\n<li data-start=\"2665\" data-end=\"2709\"><strong data-start=\"2667\" data-end=\"2688\">Hudebn&iacute; workshopy</strong> pro děti i dospěl&eacute;</li>\r\n<li data-start=\"2710\" data-end=\"2771\"><strong data-start=\"2712\" data-end=\"2732\">Diskuse a besedy</strong> s umělci o jejich tvorbě a inspiraci</li>\r\n<li data-start=\"2772\" data-end=\"2836\"><strong data-start=\"2774\" data-end=\"2805\">Prohl&iacute;dky historick&yacute;ch m&iacute;st</strong> spojen&eacute; s hudebn&iacute;mi uk&aacute;zkami</li>\r\n</ul>\r\n<p data-start=\"2838\" data-end=\"2968\">D&iacute;ky těmto aktivit&aacute;m mohou n&aacute;v&scaron;těvn&iacute;ci nejen <strong data-start=\"2883\" data-end=\"2897\">poslouchat</strong>, ale i aktivně se zapojit do hudebn&iacute;ho světa a l&eacute;pe porozumět uměn&iacute;.</p>\r\n<h2 data-start=\"2970\" data-end=\"3005\"><strong data-start=\"2973\" data-end=\"3003\">Jak se dostat na festival?</strong></h2>\r\n<p data-start=\"3007\" data-end=\"3122\">Litomy&scaron;l je dobře dostupn&aacute; z cel&eacute; Česk&eacute; republiky. <strong data-start=\"3058\" data-end=\"3094\">Doprava na festival je zaji&scaron;těna</strong> pomoc&iacute; několika možnost&iacute;:</p>\r\n<ul data-start=\"3124\" data-end=\"3375\">\r\n<li data-start=\"3124\" data-end=\"3199\"><strong data-start=\"3126\" data-end=\"3149\">Vlakem či autobusem</strong> &ndash; pravideln&eacute; spoje z Prahy, Brna i dal&scaron;&iacute;ch měst</li>\r\n<li data-start=\"3200\" data-end=\"3278\"><strong data-start=\"3202\" data-end=\"3211\">Autem</strong> &ndash; parkovi&scaron;tě jsou připravena v okol&iacute; hlavn&iacute;ch festivalov&yacute;ch m&iacute;st</li>\r\n<li data-start=\"3279\" data-end=\"3375\"><strong data-start=\"3281\" data-end=\"3302\">Městskou dopravou</strong> &ndash; pos&iacute;len&eacute; autobusov&eacute; linky pro pohodln&yacute; přesun mezi koncertn&iacute;mi m&iacute;sty</li>\r\n</ul>\r\n<p data-start=\"3377\" data-end=\"3500\">N&aacute;v&scaron;těvn&iacute;ci maj&iacute; tak&eacute; možnost <strong data-start=\"3407\" data-end=\"3453\">ubytov&aacute;n&iacute; v m&iacute;stn&iacute;ch hotelech a penzionech</strong>, kter&eacute; nab&iacute;z&iacute; speci&aacute;ln&iacute; festivalov&eacute; bal&iacute;čky.</p>\r\n<h2 data-start=\"3502\" data-end=\"3543\"><strong data-start=\"3505\" data-end=\"3541\">Festival, kter&yacute; spojuje generace</strong></h2>\r\n<p data-start=\"3545\" data-end=\"3853\">Hudebn&iacute; festival v Litomy&scaron;li nen&iacute; jen ud&aacute;lost&iacute; pro odborn&iacute;ky a milovn&iacute;ky klasick&eacute; hudby. D&iacute;ky <strong data-start=\"3639\" data-end=\"3668\">pestr&eacute; programov&eacute; nab&iacute;dce</strong> si zde najdou sv&eacute; i mlad&scaron;&iacute; generace a rodiny s dětmi. Přesah festivalu do různ&yacute;ch ž&aacute;nrů a interaktivn&iacute; aktivity z něj dělaj&iacute; <strong data-start=\"3794\" data-end=\"3819\">kulturn&iacute; ud&aacute;lost roku</strong>, kterou si nesm&iacute;te nechat uj&iacute;t.</p>\r\n<p data-start=\"3855\" data-end=\"3961\" data-is-last-node=\"\" data-is-only-node=\"\">Přijďte se <strong data-start=\"3866\" data-end=\"3896\">nechat un&eacute;st kouzlem hudby</strong> a zaž&iacute;t nezapomenutelnou atmosf&eacute;ru v srdci historick&eacute; Litomy&scaron;le!</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"mb-2 flex gap-3 -ml-2\" tabindex=\"0\">\r\n<div class=\"items-center justify-start rounded-xl p-1 flex\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</article>', '2025-03-04 12:08:37', '2025-03-18 11:59:21', 2, 17, 1, 4),
(133, 'V Hradci Králové vznikne nové kulturní centrum', 'Hradec Králové se brzy dočká nového kulturního centra, které nabídne prostor pro hudbu, umění i vzdělávání. Moderní zázemí podpoří místní tvůrce a přinese do města nové kulturní možnosti. Otevření je plánováno na rok 2027.', 'V Hradci Králové vznikne nové kulturní centrum, které nabídne koncertní sál, galerijní prostory, zkušebny pro umělce i vzdělávací místnosti. Město na projekt získalo dotaci z evropských fondů a plánuje jeho otevření v roce 2027. Centrum podpoří místní umělce, oživí kulturní scénu a přiláká návštěvníky z celého regionu.', '<h3 data-start=\"0\" data-end=\"85\">V Hradci Kr&aacute;lov&eacute; vznikne nov&eacute; kulturn&iacute; centrum: Město investuje do živ&eacute; kultury</h3>\r\n<p data-start=\"87\" data-end=\"290\">Hradec Kr&aacute;lov&eacute; se dočk&aacute; nov&eacute;ho kulturn&iacute;ho centra, kter&eacute; m&aacute; ambici st&aacute;t se v&yacute;znamn&yacute;m m&iacute;stem pro uměn&iacute;, hudbu i vzděl&aacute;v&aacute;n&iacute;. Projekt, kter&yacute; město připravuje několik let, se nyn&iacute; dost&aacute;v&aacute; do f&aacute;ze realizace.</p>\r\n<h4 data-start=\"292\" data-end=\"348\"><strong data-start=\"297\" data-end=\"346\">Modern&iacute; prostor pro kulturu a komunitn&iacute; život</strong></h4>\r\n<p data-start=\"350\" data-end=\"540\">Kulturn&iacute; centrum vznikne v rekonstruovan&eacute; budově b&yacute;val&eacute;ho průmyslov&eacute;ho objektu nedaleko centra města. C&iacute;lem je vytvořit modern&iacute; a v&iacute;ce&uacute;čelov&yacute; prostor, kter&yacute; bude sloužit &scaron;irok&eacute; veřejnosti.</p>\r\n<p data-start=\"542\" data-end=\"589\"><strong data-start=\"542\" data-end=\"587\">Co v&scaron;echno nab&iacute;dne nov&eacute; kulturn&iacute; centrum?</strong></p>\r\n<ul data-start=\"590\" data-end=\"886\">\r\n<li data-start=\"590\" data-end=\"635\"><strong data-start=\"592\" data-end=\"609\">Koncertn&iacute; s&aacute;l</strong> s kapacitou až 500 m&iacute;st</li>\r\n<li data-start=\"636\" data-end=\"700\"><strong data-start=\"638\" data-end=\"660\">Galerijn&iacute; prostory</strong> pro v&yacute;stavy a multimedi&aacute;ln&iacute; instalace</li>\r\n<li data-start=\"701\" data-end=\"751\"><strong data-start=\"703\" data-end=\"726\">Zku&scaron;ebny a ateli&eacute;ry</strong> pro umělce a hudebn&iacute;ky</li>\r\n<li data-start=\"752\" data-end=\"819\"><strong data-start=\"754\" data-end=\"793\">Předn&aacute;&scaron;kov&eacute; a workshopov&eacute; m&iacute;stnosti</strong> pro vzděl&aacute;vac&iacute; aktivity</li>\r\n<li data-start=\"820\" data-end=\"886\"><strong data-start=\"822\" data-end=\"853\">Kav&aacute;rnu a odpočinkovou z&oacute;nu</strong> propojenou se zelen&yacute;m n&aacute;dvoř&iacute;m</li>\r\n</ul>\r\n<p data-start=\"888\" data-end=\"1025\">Architektonick&yacute; n&aacute;vrh poč&iacute;t&aacute; s otevřen&yacute;m konceptem, kter&yacute; propoj&iacute; vnitřn&iacute; prostory s venkovn&iacute;mi a umožn&iacute; poř&aacute;d&aacute;n&iacute; akc&iacute; pod &scaron;ir&yacute;m nebem.</p>\r\n<h4 data-start=\"1027\" data-end=\"1078\"><strong data-start=\"1032\" data-end=\"1076\">Podpora m&iacute;stn&iacute; kultury a mlad&yacute;ch talentů</strong></h4>\r\n<p data-start=\"1080\" data-end=\"1286\">Město si od projektu slibuje předev&scaron;&iacute;m podporu m&iacute;stn&iacute;ch umělců, hudebn&iacute;ků a divadeln&iacute;ků. Nov&eacute; centrum m&aacute; sloužit jako prostor pro alternativn&iacute; sc&eacute;nu, kter&aacute; v Hradci Kr&aacute;lov&eacute; doposud neměla dostatek z&aacute;zem&iacute;.</p>\r\n<p data-start=\"1288\" data-end=\"1459\"><em data-start=\"1288\" data-end=\"1375\">M&iacute;stn&iacute; umělci budou m&iacute;t k dispozici modern&iacute; z&aacute;zem&iacute; pro tvorbu i prezentaci sv&yacute;ch děl.</em> Souč&aacute;st&iacute; centra budou tak&eacute; rezidenčn&iacute; programy pro zač&iacute;naj&iacute;c&iacute; hudebn&iacute;ky a tvůrce.</p>\r\n<p data-start=\"1461\" data-end=\"1625\">&bdquo;Chceme vytvořit m&iacute;sto, kter&eacute; bude ž&iacute;t kulturou každ&yacute; den a umožn&iacute; lidem objevovat nov&eacute; formy uměn&iacute; i setk&aacute;vat se s tvůrci,&ldquo; uvedl n&aacute;městek prim&aacute;tora pro kulturu.</p>\r\n<h4 data-start=\"1627\" data-end=\"1663\"><strong data-start=\"1632\" data-end=\"1661\">Financov&aacute;n&iacute; a časov&yacute; pl&aacute;n</strong></h4>\r\n<p data-start=\"1665\" data-end=\"1906\">Celkov&eacute; n&aacute;klady na vznik kulturn&iacute;ho centra se odhaduj&iacute; na <strong data-start=\"1723\" data-end=\"1744\">150 milionů korun</strong>, přičemž město z&iacute;skalo <strong data-start=\"1768\" data-end=\"1797\">dotaci z evropsk&yacute;ch fondů</strong> ve v&yacute;&scaron;i 80 milionů korun. Zbytek financ&iacute; bude pokryt z městsk&eacute;ho rozpočtu a př&iacute;spěvků soukrom&yacute;ch partnerů.</p>\r\n<p data-start=\"1908\" data-end=\"1935\"><strong data-start=\"1908\" data-end=\"1933\">Harmonogram v&yacute;stavby:</strong></p>\r\n<ol data-start=\"1936\" data-end=\"2062\">\r\n<li data-start=\"1936\" data-end=\"1980\"><strong data-start=\"1939\" data-end=\"1947\">2025</strong> &ndash; zah&aacute;jen&iacute; rekonstrukce budovy</li>\r\n<li data-start=\"1981\" data-end=\"2023\"><strong data-start=\"1984\" data-end=\"1992\">2026</strong> &ndash; dokončen&iacute; stavebn&iacute;ch prac&iacute;</li>\r\n<li data-start=\"2024\" data-end=\"2062\"><strong data-start=\"2027\" data-end=\"2035\">2027</strong> &ndash; otevřen&iacute; pro veřejnost</li>\r\n</ol>\r\n<p data-start=\"2064\" data-end=\"2140\">Prvn&iacute; kulturn&iacute; akce by se v nov&eacute;m centru měly uskutečnit již na jaře 2027.</p>\r\n<h4 data-start=\"2142\" data-end=\"2181\"><strong data-start=\"2147\" data-end=\"2179\">Kulturn&iacute; centrum oživ&iacute; město</strong></h4>\r\n<p data-start=\"2183\" data-end=\"2418\">Nov&eacute; kulturn&iacute; centrum by mělo <strong data-start=\"2213\" data-end=\"2292\">přil&aacute;kat nejen obyvatele Hradce Kr&aacute;lov&eacute;, ale i n&aacute;v&scaron;těvn&iacute;ky z cel&eacute;ho regionu</strong>. D&iacute;ky modern&iacute;mu z&aacute;zem&iacute; a pestr&eacute; nab&iacute;dce programů se oček&aacute;v&aacute;, že se stane jedn&iacute;m z hlavn&iacute;ch kulturn&iacute;ch bodů v&yacute;chodn&iacute;ch Čech.</p>\r\n<p data-start=\"2420\" data-end=\"2550\" data-is-last-node=\"\" data-is-only-node=\"\">Hradec Kr&aacute;lov&eacute; tak potvrzuje svou pověst města s bohat&yacute;m kulturn&iacute;m životem a otev&iacute;r&aacute; dveře nov&yacute;m možnostem pro umělce i veřejnost.</p>', '2025-03-04 12:15:05', '2025-03-18 10:08:08', 30, 17, 1, 4),
(134, 'Historické slavnosti v Chrudimi lákají tisíce návštěvníků', 'Chrudim se opět vrátí do časů rytířů a trhovců! Historické slavnosti nabídnou jedinečný zážitek plný šermířských soubojů, dobové hudby a tradičních řemesel. Přijďte si užít nezapomenutelnou atmosféru minulosti!', 'Historické slavnosti v Chrudimi každoročně přitahují tisíce návštěvníků, kteří si mohou užít autentickou atmosféru středověku. Náměstí zaplní rytířské turnaje, historický jarmark, hudební a taneční vystoupení i večerní ohňová show. Akce nejen oživuje historii, ale také podporuje místní kulturu a turismus. Organizátoři již plánují další ročník s novými atrakcemi, včetně středověkého tábora a interaktivních aktivit pro návštěvníky.', '<h3 data-start=\"0\" data-end=\"67\"><strong data-start=\"4\" data-end=\"65\">Historické slavnosti v Chrudimi lákají tisíce návštěvníků</strong></h3>\r\n<p data-start=\"69\" data-end=\"377\">Město Chrudim se opět proměnilo v živoucí historickou scénu, kde se návštěvníci mohou vrátit v čase a zažít atmosféru minulých staletí. <strong data-start=\"205\" data-end=\"229\">Historické slavnosti</strong>, které se konají každý rok, patří k největším kulturním událostem regionu a přitahují nejen místní obyvatele, ale i návštěvníky z celé republiky.</p>\r\n<h4 data-start=\"379\" data-end=\"426\"><strong data-start=\"384\" data-end=\"424\">Středověká atmosféra v ulicích města</strong></h4>\r\n<p data-start=\"428\" data-end=\"695\">Celé historické centrum Chrudimi se během slavností mění v dobovou kulisu, kde <strong data-start=\"507\" data-end=\"557\">ožívají rytíři, kejklíři, trhovci a řemeslníci</strong>. Účastníci v dobových kostýmech předvádějí různé historické scény, souboje a představení, která věrně zachycují atmosféru minulých dob.</p>\r\n<p data-start=\"697\" data-end=\"978\"><em data-start=\"697\" data-end=\"754\">Na náměstí se rozprostírají stánky s tradičními řemesly</em>, kde si návštěvníci mohou vyzkoušet například kovářství, hrnčířství nebo výrobu svíček. Na své si přijdou i milovníci staročeské kuchyně – nechybí pečená masa, medovina či domácí chleby pečené podle historických receptur.</p>\r\n<h4 data-start=\"980\" data-end=\"1011\"><strong data-start=\"985\" data-end=\"1009\">Co návštěvníky čeká?</strong></h4>\r\n<p data-start=\"1013\" data-end=\"1080\">Každý ročník slavností nabízí <strong data-start=\"1043\" data-end=\"1061\">bohatý program</strong>, který zahrnuje:</p>\r\n<ul data-start=\"1081\" data-end=\"1455\">\r\n<li data-start=\"1081\" data-end=\"1147\"><strong data-start=\"1083\" data-end=\"1103\">Rytířské turnaje</strong> – napínavé souboje na koních i pěší klání</li>\r\n<li data-start=\"1148\" data-end=\"1228\"><strong data-start=\"1150\" data-end=\"1172\">Historický jarmark</strong> – ukázky tradičních řemesel a prodej dobových výrobků</li>\r\n<li data-start=\"1229\" data-end=\"1315\"><strong data-start=\"1231\" data-end=\"1263\">Hudební a taneční vystoupení</strong> – středověká hudba, lidové tance i dobové divadlo</li>\r\n<li data-start=\"1316\" data-end=\"1385\"><strong data-start=\"1318\" data-end=\"1344\">Ohňová show a kejklíři</strong> – večerní program plný efektů a kouzel</li>\r\n<li data-start=\"1386\" data-end=\"1455\"><strong data-start=\"1388\" data-end=\"1419\">Komentované prohlídky města</strong> – s průvodci v dobových kostýmech</li>\r\n</ul>\r\n<p data-start=\"1457\" data-end=\"1628\">Velkým lákadlem je <em data-start=\"1476\" data-end=\"1509\">průvod v historických kostýmech</em>, který prochází městem a představuje různé historické postavy, od králů a šlechty až po prosté měšťany a obchodníky.</p>\r\n<h4 data-start=\"1630\" data-end=\"1675\"><strong data-start=\"1635\" data-end=\"1673\">Slavnosti podporují místní kulturu</strong></h4>\r\n<p data-start=\"1677\" data-end=\"1984\">Kromě tradičního programu se na slavnostech pravidelně prezentují také místní umělci, školy a spolky, které přispívají k bohatství kulturního dění v Chrudimi. <strong data-start=\"1836\" data-end=\"1897\">Podpora regionální kultury je jedním z hlavních cílů akce</strong>, a proto se na organizaci podílí nejen město, ale i dobrovolníci a místní instituce.</p>\r\n<p data-start=\"1986\" data-end=\"2236\">„Chceme návštěvníkům přiblížit, jak se kdysi v našem městě žilo, a zároveň podpořit místní řemeslníky a umělce. Každý rok se snažíme přidat nové prvky, aby slavnosti byly atraktivní pro všechny věkové kategorie,“ říká jeden z hlavních organizátorů.</p>\r\n<h4 data-start=\"2238\" data-end=\"2280\"><strong data-start=\"2243\" data-end=\"2278\">Návštěvnost a dopad na turismus</strong></h4>\r\n<p data-start=\"2282\" data-end=\"2491\">Historické slavnosti mají <strong data-start=\"2308\" data-end=\"2353\">významný dopad na cestovní ruch v regionu</strong>. Každoročně do Chrudimi přilákají tisíce turistů, kteří nejen navštěvují festival, ale také objevují další památky a zajímavosti města.</p>\r\n<p data-start=\"2493\" data-end=\"2667\">Podle statistik <strong data-start=\"2509\" data-end=\"2568\">se během slavností zvýší návštěvnost Chrudimi až o 40 %</strong>, což přináší prospěch nejen kulturním institucím, ale i místním podnikům, hotelům a restauracím.</p>\r\n<h4 data-start=\"2669\" data-end=\"2702\"><strong data-start=\"2674\" data-end=\"2700\">Plány na příští ročník</strong></h4>\r\n<p data-start=\"2704\" data-end=\"2914\">Po úspěšném letošním ročníku už organizátoři pracují na přípravách dalších slavností. <em data-start=\"2790\" data-end=\"2866\">Plánuje se rozšíření programu o nové historické scény a interaktivní prvky</em>, které zapojí návštěvníky ještě více do dění.</p>\r\n<p data-start=\"2916\" data-end=\"3142\">Hlavní novinkou příštího ročníku by měl být <strong data-start=\"2960\" data-end=\"2980\">středověký tábor</strong>, kde si lidé budou moci vyzkoušet život v historické vesnici, naučit se střílet z luku, vařit podle dobových receptur nebo se stát součástí rytířského souboje.</p>\r\n<h3 data-start=\"3144\" data-end=\"3159\"><strong data-start=\"3148\" data-end=\"3157\">Závěr</strong></h3>\r\n<p data-start=\"3161\" data-end=\"3500\" data-is-last-node=\"\" data-is-only-node=\"\">Historické slavnosti v Chrudimi jsou jedinečným zážitkem, který propojuje historii, kulturu a zábavu. Díky autentické atmosféře, bohatému programu a zapojení místní komunity patří k nejnavštěvovanějším akcím v regionu. Pokud jste letos slavnosti nestihli, určitě si je nenechte ujít příští rok – čeká vás neopakovatelná cesta do minulosti!</p>', '2025-03-04 12:19:36', '2025-03-18 11:59:23', 157, 17, 1, 4),
(163, 'Muzeum v Jičíně otevřelo unikátní expozici o Valdštejnovi', 'Muzeum v Jičíně otevřelo novou expozici věnovanou Albrechtu z Valdštejna. Návštěvníci se mohou těšit na interaktivní prvky, historické artefakty i pohled do života jednoho z nejvýznamnějších vojevůdců třicetileté války.', 'Regionální muzeum v Jičíně otevřelo novou expozici věnovanou Albrechtu z Valdštejna, která návštěvníkům přibližuje jeho život, vojenskou kariéru a vliv na rozvoj města. Výstava kombinuje historické artefakty s moderními technologiemi, včetně virtuální reality a interaktivních prvků. Nabízí pohled na třicetiletou válku, Valdštejnovy urbanistické plány i jeho tajemstvím opředenou osobnost. Expozice má potenciál přilákat více turistů a posílit kulturní význam Jičína.', '<article class=\"w-full text-token-text-primary focus-visible:outline-2 focus-visible:outline-offset-[-4px]\" dir=\"auto\" data-testid=\"conversation-turn-111\" data-scroll-anchor=\"false\">\r\n<div class=\"text-base my-auto mx-auto py-[18px] px-6\">\r\n<div class=\"mx-auto flex flex-1 text-base gap-4 md:gap-5 lg:gap-6 md:max-w-3xl lg:max-w-[40rem] xl:max-w-[48rem]\">\r\n<div class=\"group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn @xs/thread:px-0 @sm/thread:px-1.5 @md/thread:px-4\">\r\n<div class=\"flex-col gap-1 md:gap-3\">\r\n<div class=\"flex max-w-full flex-col flex-grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 whitespace-normal break-words text-start [.text-message+&amp;]:mt-5\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"8375406e-39dd-4115-bfa5-dade76e29eca\" data-message-model-slug=\"gpt-4o\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\">\r\n<div class=\"markdown prose w-full break-words dark:prose-invert light\">\r\n<p data-start=\"0\" data-end=\"63\"><strong data-start=\"0\" data-end=\"61\">Muzeum v Jič&iacute;ně otevřelo unik&aacute;tn&iacute; expozici o Vald&scaron;tejnovi</strong></p>\r\n<p data-start=\"65\" data-end=\"393\">Jič&iacute;nsk&eacute; muzeum se může pochlubit novou expozic&iacute; věnovanou jedn&eacute; z nejv&yacute;znamněj&scaron;&iacute;ch osobnost&iacute; česk&eacute; historie &ndash; Albrechtu z Vald&scaron;tejna. Tato unik&aacute;tn&iacute; v&yacute;stava nab&iacute;z&iacute; n&aacute;v&scaron;těvn&iacute;kům možnost nahl&eacute;dnout do života a doby tohoto slavn&eacute;ho vojevůdce a politika, kter&yacute; v&yacute;razně ovlivnil v&yacute;voj regionu i cel&eacute; Evropy během třicetilet&eacute; v&aacute;lky.</p>\r\n<h3 data-start=\"395\" data-end=\"443\"><strong data-start=\"399\" data-end=\"441\">Historick&yacute; kontext a v&yacute;znam Vald&scaron;tejna</strong></h3>\r\n<p data-start=\"444\" data-end=\"723\">Albrecht z Vald&scaron;tejna (*1583 &ndash; &dagger;1634) patřil mezi nejvlivněj&scaron;&iacute; osobnosti 17. stolet&iacute;. Jako c&iacute;sařsk&yacute; gener&aacute;l a vojensk&yacute; strat&eacute;g měl z&aacute;sadn&iacute; pod&iacute;l na průběhu třicetilet&eacute; v&aacute;lky. D&iacute;ky sv&yacute;m schopnostem i politick&eacute; obratnosti se stal jedn&iacute;m z nejmocněj&scaron;&iacute;ch mužů habsbursk&eacute; monarchie.</p>\r\n<p data-start=\"725\" data-end=\"1008\">Vald&scaron;tejn si Jič&iacute;n vybral jako sv&eacute; s&iacute;deln&iacute; město a přeměnil ho na centrum sv&eacute; rozs&aacute;hl&eacute; panstv&iacute;. Pl&aacute;noval z něj učinit v&yacute;znamn&eacute; kulturn&iacute; a hospod&aacute;řsk&eacute; středisko, což dokl&aacute;daj&iacute; dochovan&eacute; stavby, např&iacute;klad <strong data-start=\"928\" data-end=\"1005\">vald&scaron;tejnsk&yacute; pal&aacute;c, jezuitsk&aacute; kolej nebo rozs&aacute;hl&yacute; urbanistick&yacute; pl&aacute;n města</strong>.</p>\r\n<h3 data-start=\"1010\" data-end=\"1039\"><strong data-start=\"1014\" data-end=\"1037\">Co expozice nab&iacute;z&iacute;?</strong></h3>\r\n<p data-start=\"1040\" data-end=\"1126\">Nově otevřen&aacute; expozice v jič&iacute;nsk&eacute;m muzeu je rozdělena do několika tematick&yacute;ch sekc&iacute;:</p>\r\n<ul data-start=\"1128\" data-end=\"1740\">\r\n<li data-start=\"1128\" data-end=\"1292\"><strong data-start=\"1130\" data-end=\"1172\">Život a kari&eacute;ra Albrechta z Vald&scaron;tejna</strong> &ndash; Interaktivn&iacute; panely a historick&eacute; artefakty přibližuj&iacute; jeho vojensk&eacute; tažen&iacute;, politick&eacute; intriky i jeho tragick&yacute; osud.</li>\r\n<li data-start=\"1293\" data-end=\"1464\"><strong data-start=\"1295\" data-end=\"1316\">Vald&scaron;tejn a Jič&iacute;n</strong> &ndash; N&aacute;v&scaron;těvn&iacute;ci se dozvěd&iacute; o Vald&scaron;tejnov&yacute;ch ambici&oacute;zn&iacute;ch pl&aacute;nech na přestavbu města a o jeho odkazu, kter&yacute; je dodnes patrn&yacute; v městsk&eacute; architektuře.</li>\r\n<li data-start=\"1465\" data-end=\"1576\"><strong data-start=\"1467\" data-end=\"1488\">Třicetilet&aacute; v&aacute;lka</strong> &ndash; Historick&yacute; kontext t&eacute;to dramatick&eacute; epochy doplňuj&iacute; dobov&eacute; zbraně, mapy a dokumenty.</li>\r\n<li data-start=\"1577\" data-end=\"1740\"><strong data-start=\"1579\" data-end=\"1614\">Vald&scaron;tejnova osobnost a legenda</strong> &ndash; Expozice se věnuje tak&eacute; mystick&yacute;m prvkům Vald&scaron;tejnova života, včetně astrologie a jeho &uacute;dajn&eacute;ho spojen&iacute; s tajn&yacute;mi spolky.</li>\r\n</ul>\r\n<h3 data-start=\"1742\" data-end=\"1797\"><strong data-start=\"1746\" data-end=\"1795\">Modern&iacute; technologie a z&aacute;žitek pro n&aacute;v&scaron;těvn&iacute;ky</strong></h3>\r\n<p data-start=\"1798\" data-end=\"2083\">V&yacute;stava využ&iacute;v&aacute; modern&iacute; technologie, kter&eacute; umožňuj&iacute; n&aacute;v&scaron;těvn&iacute;kům prož&iacute;t historii na vlastn&iacute; kůži. <strong data-start=\"1896\" data-end=\"1917\">Virtu&aacute;ln&iacute; realita</strong> nab&iacute;z&iacute; možnost proj&iacute;t se Vald&scaron;tejnov&yacute;m Jič&iacute;nem v jeho největ&scaron;&iacute; sl&aacute;vě. <strong data-start=\"1988\" data-end=\"2010\">Dotykov&eacute; obrazovky</strong> pak umožňuj&iacute; zkoumat detailn&iacute; repliky historick&yacute;ch dokumentů a zbran&iacute;.</p>\r\n<p data-start=\"2085\" data-end=\"2242\">Děti i dospěl&iacute; si mohou vyzkou&scaron;et historick&eacute; kost&yacute;my nebo se zapojit do interaktivn&iacute;ch her, kter&eacute; simuluj&iacute; strategick&eacute; rozhodov&aacute;n&iacute; během třicetilet&eacute; v&aacute;lky.</p>\r\n<h3 data-start=\"2244\" data-end=\"2280\"><strong data-start=\"2248\" data-end=\"2278\">Ohlasy a v&yacute;znam pro region</strong></h3>\r\n<p data-start=\"2281\" data-end=\"2555\">M&iacute;stn&iacute; i turist&eacute; expozici hodnot&iacute; velmi pozitivně. &bdquo;Jsem nad&scaron;en&yacute;, jak&yacute;m způsobem muzeum dok&aacute;zalo propojit historick&aacute; fakta s modern&iacute;mi technologiemi,&ldquo; ř&iacute;k&aacute; jeden z prvn&iacute;ch n&aacute;v&scaron;těvn&iacute;ků. V&yacute;stava m&aacute; potenci&aacute;l přil&aacute;kat do Jič&iacute;na v&iacute;ce turistů a podpořit tak i m&iacute;stn&iacute; ekonomiku.</p>\r\n<p data-start=\"2557\" data-end=\"2855\">Podle odborn&iacute;ků tato expozice nejen obohacuje kulturn&iacute; dědictv&iacute; regionu, ale tak&eacute; připom&iacute;n&aacute; důležitost Jič&iacute;na v česk&eacute; historii. &bdquo;Albrecht z Vald&scaron;tejna byl fascinuj&iacute;c&iacute; postava a Jič&iacute;n je s n&iacute;m neodmyslitelně spjat. Tato v&yacute;stava n&aacute;m ho přibližuje zcela nov&yacute;m způsobem,&ldquo; dod&aacute;v&aacute; historik Jan Novotn&yacute;.</p>\r\n<h3 data-start=\"2857\" data-end=\"2886\"><strong data-start=\"2861\" data-end=\"2884\">Praktick&eacute; informace</strong></h3>\r\n<ul data-start=\"2887\" data-end=\"3148\">\r\n<li data-start=\"2887\" data-end=\"2938\"><strong data-start=\"2889\" data-end=\"2899\">M&iacute;sto:</strong> Region&aacute;ln&iacute; muzeum a galerie v Jič&iacute;ně</li>\r\n<li data-start=\"2939\" data-end=\"2987\"><strong data-start=\"2941\" data-end=\"2960\">Otev&iacute;rac&iacute; doba:</strong> &uacute;ter&yacute;&ndash;neděle, 9:00&ndash;17:00</li>\r\n<li data-start=\"2988\" data-end=\"3066\"><strong data-start=\"2990\" data-end=\"3002\">Vstupn&eacute;:</strong> dospěl&iacute; 120 Kč, děti a studenti 80 Kč, rodinn&eacute; vstupn&eacute; 250 Kč</li>\r\n<li data-start=\"3067\" data-end=\"3148\"><strong data-start=\"3069\" data-end=\"3092\">Doprovodn&yacute; program:</strong> předn&aacute;&scaron;ky, komentovan&eacute; prohl&iacute;dky, tematick&eacute; workshopy</li>\r\n</ul>\r\n<p data-start=\"3150\" data-end=\"3460\" data-is-last-node=\"\" data-is-only-node=\"\">Nov&aacute; expozice o Albrechtu z Vald&scaron;tejna nab&iacute;z&iacute; <strong data-start=\"3196\" data-end=\"3230\">fascinuj&iacute;c&iacute; pohled do historie</strong>, propojuje modern&iacute; technologie s bohat&yacute;m historick&yacute;m obsahem a <strong data-start=\"3294\" data-end=\"3367\">přibližuje n&aacute;v&scaron;těvn&iacute;kům jedno z nejv&yacute;znamněj&scaron;&iacute;ch obdob&iacute; česk&yacute;ch dějin</strong>. Jič&iacute;n se tak opět potvrzuje jako <strong data-start=\"3402\" data-end=\"3459\">kulturn&iacute; centrum spojen&eacute; s touto legend&aacute;rn&iacute; osobnost&iacute;</strong>.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"absolute\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</article>', '2025-03-11 09:57:01', '2025-03-25 10:14:41', 51, 18, 1, 4),
(164, 'Tipy na víkend: Kam vyrazit ve východních Čechách?', 'Plánujete víkendový výlet, ale nevíte, kam vyrazit? Východní Čechy nabízejí nespočet možností pro dobrodruhy, milovníky historie i rodiny s dětmi. Objevte tipy na zajímavá místa, která stojí za návštěvu!', 'Východní Čechy nabízejí širokou škálu možností pro víkendové výlety. Od turistických tras v Krkonoších a Orlických horách, přes historická města jako Hradec Králové a Litomyšl, až po rodinné atrakce typu ZOO Dvůr Králové nebo Peklo Čertovina. Milovníci relaxace si mohou dopřát lázeňské pobyty v Poděbradech či Velichovkách, zatímco nadšenci adrenalinu ocení lanový park Dolní Morava nebo bungee jumping v Harrachově. Tento region nabízí nespočet možností pro všechny, kteří chtějí aktivně či odpočinkově strávit volné dny.', '<h3 data-start=\"0\" data-end=\"60\"><strong data-start=\"4\" data-end=\"58\">Tipy na v&iacute;kend: Kam vyrazit ve v&yacute;chodn&iacute;ch Čech&aacute;ch?</strong></h3>\r\n<p data-start=\"62\" data-end=\"309\">V&yacute;chodn&iacute; Čechy nab&iacute;zej&iacute; mnoho možnost&iacute;, kam se vydat na v&iacute;kendov&yacute; v&yacute;let. Ať už jste milovn&iacute;ci př&iacute;rody, historie, kultury nebo aktivn&iacute;ho odpočinku, každ&yacute; si zde přijde na sv&eacute;. Přin&aacute;&scaron;&iacute;me v&aacute;m několik tipů na zaj&iacute;mav&aacute; m&iacute;sta, kter&aacute; stoj&iacute; za n&aacute;v&scaron;těvu.</p>\r\n<h3 data-start=\"316\" data-end=\"367\"><strong data-start=\"320\" data-end=\"365\">1. Př&iacute;rodn&iacute; kr&aacute;sy Krkono&scaron; a Orlick&yacute;ch hor</strong></h3>\r\n<p data-start=\"369\" data-end=\"444\">Pokud m&aacute;te r&aacute;di <strong data-start=\"385\" data-end=\"415\">turistiku a čerstv&yacute; vzduch</strong>, hory jsou ide&aacute;ln&iacute; volbou.</p>\r\n<ul data-start=\"446\" data-end=\"865\">\r\n<li data-start=\"446\" data-end=\"642\"><strong data-start=\"448\" data-end=\"460\">Krkono&scaron;e</strong> &ndash; Nejvy&scaron;&scaron;&iacute; česk&eacute; pohoř&iacute; nab&iacute;z&iacute; nepřebern&eacute; množstv&iacute; turistick&yacute;ch tras. Vydejte se např&iacute;klad na <strong data-start=\"555\" data-end=\"565\">Sněžku</strong>, nejvy&scaron;&scaron;&iacute; horu Česka, nebo nav&scaron;tivte <strong data-start=\"603\" data-end=\"617\">Labsk&yacute; důl</strong> s n&aacute;dhern&yacute;mi vodop&aacute;dy.</li>\r\n<li data-start=\"643\" data-end=\"865\"><strong data-start=\"645\" data-end=\"661\">Orlick&eacute; hory</strong> &ndash; Klidněj&scaron;&iacute; alternativa ke Krkono&scaron;&iacute;m. Skvěl&yacute;m c&iacute;lem je např&iacute;klad <strong data-start=\"727\" data-end=\"743\">Velk&aacute; De&scaron;tn&aacute;</strong>, nejvy&scaron;&scaron;&iacute; vrchol Orlick&yacute;ch hor, nebo pevnostn&iacute; syst&eacute;m <strong data-start=\"798\" data-end=\"809\">Hanička</strong>, kter&yacute; připom&iacute;n&aacute; předv&aacute;lečn&eacute; opevněn&iacute; Československa.</li>\r\n</ul>\r\n<h3 data-start=\"872\" data-end=\"924\"><strong data-start=\"876\" data-end=\"922\">2. Historick&eacute; pam&aacute;tky a města pln&aacute; př&iacute;běhů</strong></h3>\r\n<p data-start=\"926\" data-end=\"992\">Pro milovn&iacute;ky historie nab&iacute;zej&iacute; v&yacute;chodn&iacute; Čechy množstv&iacute; pam&aacute;tek.</p>\r\n<ul data-start=\"994\" data-end=\"1535\">\r\n<li data-start=\"994\" data-end=\"1193\"><strong data-start=\"996\" data-end=\"1014\">Hradec Kr&aacute;lov&eacute;</strong> &ndash; Kr&aacute;lovsk&eacute; město s n&aacute;dhernou historickou architekturou. Nav&scaron;tivte <strong data-start=\"1082\" data-end=\"1095\">B&iacute;lou věž</strong>, kter&aacute; nab&iacute;z&iacute; &uacute;chvatn&yacute; v&yacute;hled, nebo obdivujte urbanistick&eacute; skvosty od architekta Josefa Goč&aacute;ra.</li>\r\n<li data-start=\"1194\" data-end=\"1337\"><strong data-start=\"1196\" data-end=\"1208\">Litomy&scaron;l</strong> &ndash; Rodn&eacute; město Bedřicha Smetany a <strong data-start=\"1242\" data-end=\"1260\">UNESCO pam&aacute;tka</strong> v podobě renesančn&iacute;ho <strong data-start=\"1283\" data-end=\"1301\">z&aacute;mku Litomy&scaron;l</strong> s unik&aacute;tn&iacute;m sgrafitov&yacute;m zdoben&iacute;m.</li>\r\n<li data-start=\"1338\" data-end=\"1535\"><strong data-start=\"1340\" data-end=\"1354\">Kutn&aacute; Hora</strong> &ndash; I když se nach&aacute;z&iacute; na hranici v&yacute;chodn&iacute;ch Čech, nemůžeme ji opomenout. Dominantou je <strong data-start=\"1440\" data-end=\"1463\">chr&aacute;m svat&eacute; Barbory</strong>, historick&eacute; <strong data-start=\"1476\" data-end=\"1496\">dolov&aacute;n&iacute; stř&iacute;bra</strong> a fascinuj&iacute;c&iacute; <strong data-start=\"1511\" data-end=\"1532\">Kostnice v Sedlci</strong>.</li>\r\n</ul>\r\n<h3 data-start=\"1542\" data-end=\"1579\"><strong data-start=\"1546\" data-end=\"1577\">3. Z&aacute;žitky pro celou rodinu</strong></h3>\r\n<p data-start=\"1581\" data-end=\"1641\">Hled&aacute;te <strong data-start=\"1589\" data-end=\"1618\">z&aacute;bavu pro děti i dospěl&eacute;</strong>? Zde jsou na&scaron;e tipy:</p>\r\n<ul data-start=\"1643\" data-end=\"2069\">\r\n<li data-start=\"1643\" data-end=\"1783\"><strong data-start=\"1645\" data-end=\"1665\">ZOO Dvůr Kr&aacute;lov&eacute;</strong> &ndash; Největ&scaron;&iacute; safari v Česku, kde můžete vidět <strong data-start=\"1710\" data-end=\"1749\">volně se pohybuj&iacute;c&iacute; africk&aacute; zv&iacute;řata</strong> z pohodl&iacute; auta nebo safaribusu.</li>\r\n<li data-start=\"1784\" data-end=\"1924\"><strong data-start=\"1786\" data-end=\"1805\">Peklo Čertovina</strong> u Hlinska &ndash; Unik&aacute;tn&iacute; z&aacute;bavn&iacute; are&aacute;l, kde se stanete souč&aacute;st&iacute; pekeln&eacute;ho př&iacute;běhu. Ide&aacute;ln&iacute; pro děti i dospěl&eacute; s humorem.</li>\r\n<li data-start=\"1925\" data-end=\"2069\"><strong data-start=\"1927\" data-end=\"1949\">Toulovcovy ma&scaron;tale</strong> &ndash; Př&iacute;rodn&iacute; skaln&iacute; město pln&eacute; &uacute;zk&yacute;ch soutěsek a bizarn&iacute;ch skaln&iacute;ch &uacute;tvarů, ide&aacute;ln&iacute; na proch&aacute;zky i dobrodružn&eacute; v&yacute;pravy.</li>\r\n</ul>\r\n<h3 data-start=\"2076\" data-end=\"2115\"><strong data-start=\"2080\" data-end=\"2113\">4. Relaxace a wellness pobyty</strong></h3>\r\n<p data-start=\"2117\" data-end=\"2205\">Pokud si chcete <strong data-start=\"2133\" data-end=\"2166\">odpočinout a načerpat energii</strong>, zkuste někter&yacute; z l&aacute;zeňsk&yacute;ch pobytů.</p>\r\n<ul data-start=\"2207\" data-end=\"2562\">\r\n<li data-start=\"2207\" data-end=\"2316\"><strong data-start=\"2209\" data-end=\"2222\">Poděbrady</strong> &ndash; Proslul&eacute; miner&aacute;ln&iacute;mi prameny a kr&aacute;snou kolon&aacute;dou. Vyzkou&scaron;ejte l&eacute;čiv&eacute; koupele a procedury.</li>\r\n<li data-start=\"2317\" data-end=\"2439\"><strong data-start=\"2319\" data-end=\"2333\">Velichovky</strong> &ndash; Tradičn&iacute; l&aacute;zně zaměřen&eacute; na l&eacute;čbu pohybov&eacute;ho apar&aacute;tu. Skvěl&eacute; pro odpočinek i lehk&eacute; proch&aacute;zky po okol&iacute;.</li>\r\n<li data-start=\"2440\" data-end=\"2562\"><strong data-start=\"2442\" data-end=\"2467\">Aquacentrum Pardubice</strong> &ndash; Modern&iacute; vodn&iacute; svět s tobog&aacute;ny, wellness a saunami. Ide&aacute;ln&iacute; m&iacute;sto pro rodiny i jednotlivce.</li>\r\n</ul>\r\n<h3 data-start=\"2569\" data-end=\"2602\"><strong data-start=\"2573\" data-end=\"2600\">5. Adrenalinov&eacute; z&aacute;žitky</strong></h3>\r\n<p data-start=\"2604\" data-end=\"2684\">Pokud hled&aacute;te <strong data-start=\"2618\" data-end=\"2637\">něco akčněj&scaron;&iacute;ho</strong>, i pro v&aacute;s maj&iacute; v&yacute;chodn&iacute; Čechy co nab&iacute;dnout.</p>\r\n<ul data-start=\"2686\" data-end=\"3020\">\r\n<li data-start=\"2686\" data-end=\"2807\"><strong data-start=\"2688\" data-end=\"2716\">Lanov&yacute; park Doln&iacute; Morava</strong> &ndash; Nejdel&scaron;&iacute; <strong data-start=\"2728\" data-end=\"2752\">visut&yacute; most na světě</strong>, adrenalinov&eacute; atrakce a n&aacute;dhern&yacute; v&yacute;hled na Jesen&iacute;ky.</li>\r\n<li data-start=\"2808\" data-end=\"2911\"><strong data-start=\"2810\" data-end=\"2838\">Paragliding v Krkono&scaron;&iacute;ch</strong> &ndash; Vyzkou&scaron;ejte si let na pad&aacute;ku a zažijte Krkono&scaron;e z ptač&iacute; perspektivy.</li>\r\n<li data-start=\"2912\" data-end=\"3020\"><strong data-start=\"2914\" data-end=\"2945\">Bungee jumping v Harrachově</strong> &ndash; Skok z harrachovsk&eacute;ho mostu je z&aacute;žitek, na kter&yacute; jen tak nezapomenete.</li>\r\n</ul>\r\n<h3 data-start=\"3027\" data-end=\"3055\"><strong data-start=\"3031\" data-end=\"3053\">Kam tedy vyraz&iacute;te?</strong></h3>\r\n<p data-start=\"3057\" data-end=\"3268\" data-is-last-node=\"\" data-is-only-node=\"\">Ať už se rozhodnete pro <strong data-start=\"3081\" data-end=\"3134\">př&iacute;rodu, historii, rodinn&eacute; z&aacute;žitky nebo adrenalin</strong>, v&yacute;chodn&iacute; Čechy nab&iacute;zej&iacute; nespočet možnost&iacute;. <strong data-start=\"3179\" data-end=\"3268\" data-is-last-node=\"\">Napl&aacute;nujte si v&iacute;kend podle sv&yacute;ch představ a užijte si objevov&aacute;n&iacute; kr&aacute;s tohoto regionu!</strong></p>', '2025-03-11 10:02:46', '2025-03-12 15:42:00', 0, 18, 1, 4);
INSERT INTO `clanky` (`idClanky`, `nadpis`, `upoutavka`, `uryvek`, `obsah`, `created_at`, `updated_at`, `zhlednuti`, `Uzivatele_idUzivatele`, `Kategorie_idKategorie`, `Stav_idStav`) VALUES
(165, 'Mountfield HK míří do play-off, fanoušci se těší na napínavé zápasy', 'Mountfield HK si zajistil místo v play-off a fanoušci se mohou těšit na napínavé souboje o titul. Jaké jsou šance hradeckého týmu a kdo bude klíčovým hráčem v rozhodujících zápasech?', 'Mountfield HK si po úspěšné základní části zajistil postup do play-off a fanoušci se mohou těšit na napínavé boje o titul. Klíčovými hráči budou opory týmu jako Brandon Alderson, Lukáš Cingel a brankář Matěj Machovský. V play-off rozhodne nejen forma jednotlivců, ale i týmová strategie, disciplína a podpora fanoušků. Hradec Králové má šanci dosáhnout historického úspěchu, pokud dokáže udržet vysokou úroveň výkonů a zvládne vypjaté souboje s možnými soupeři, mezi které patří Kometa Brno, Oceláři Třinec nebo Sparta Praha.', '<h2 data-start=\"0\" data-end=\"73\"><strong data-start=\"0\" data-end=\"71\">Mountfield HK m&iacute;ř&iacute; do play-off, fanou&scaron;ci se tě&scaron;&iacute; na nap&iacute;nav&eacute; z&aacute;pasy</strong></h2>\r\n<p data-start=\"75\" data-end=\"414\">Hokejist&eacute; Mountfieldu HK si i letos zajistili &uacute;čast v play-off a jejich fanou&scaron;ci se mohou tě&scaron;it na vzru&scaron;uj&iacute;c&iacute; souboje o mistrovsk&yacute; titul. Po &uacute;spě&scaron;n&eacute; z&aacute;kladn&iacute; č&aacute;sti se hradečt&iacute; lvi chystaj&iacute; na kl&iacute;čov&eacute; boje, kter&eacute; rozhodnou o jejich &scaron;anc&iacute;ch na zisk trofeje. Jak prob&iacute;hala sez&oacute;na, kdo zaz&aacute;řil a jak&eacute; jsou vyhl&iacute;dky t&yacute;mu do vyřazovac&iacute;ch bojů?</p>\r\n<h3 data-start=\"416\" data-end=\"457\">Siln&aacute; z&aacute;kladn&iacute; č&aacute;st a kl&iacute;čov&iacute; hr&aacute;či</h3>\r\n<p data-start=\"458\" data-end=\"707\">Sez&oacute;na pro Mountfield HK nebyla jednoduch&aacute;, ale t&yacute;m pod veden&iacute;m tren&eacute;ra Tom&aacute;&scaron;e Martince si postupně vybudoval stabiln&iacute; pozici v horn&iacute; č&aacute;sti tabulky. D&iacute;ky skvěl&eacute; obraně a produktivn&iacute; ofenzivě se Hradec dlouhodobě držel mezi nejlep&scaron;&iacute;mi t&yacute;my soutěže.</p>\r\n<p data-start=\"709\" data-end=\"744\">Mezi největ&scaron;&iacute; opory t&yacute;mu patřili:</p>\r\n<ul data-start=\"745\" data-end=\"1104\">\r\n<li data-start=\"745\" data-end=\"834\"><strong data-start=\"747\" data-end=\"767\">Brandon Alderson</strong> &ndash; kanadsk&yacute; &uacute;točn&iacute;k, kter&yacute; t&aacute;hl ofenzivu sv&yacute;mi g&oacute;ly i asistencemi</li>\r\n<li data-start=\"835\" data-end=\"917\"><strong data-start=\"837\" data-end=\"853\">Luk&aacute;&scaron; Cingel</strong> &ndash; zku&scaron;en&yacute; forvard, jehož v&yacute;kony byly stabiln&iacute; po celou sez&oacute;nu</li>\r\n<li data-start=\"918\" data-end=\"1008\"><strong data-start=\"920\" data-end=\"933\">Jakub Lev</strong> &ndash; hr&aacute;č s bojovn&yacute;m duchem, kter&yacute; se stal kl&iacute;čov&yacute;m ve vyrovnan&yacute;ch z&aacute;pasech</li>\r\n<li data-start=\"1009\" data-end=\"1104\"><strong data-start=\"1011\" data-end=\"1030\">Matěj Machovsk&yacute;</strong> &ndash; brank&aacute;řsk&aacute; jednička, kter&aacute; držela t&yacute;m ve hře i v kritick&yacute;ch momentech</li>\r\n</ul>\r\n<p data-start=\"1106\" data-end=\"1290\">Kromě těchto opor zaznamenali solidn&iacute; v&yacute;kony tak&eacute; mlad&iacute; talenti, kteř&iacute; si vybojovali m&iacute;sto v sestavě a uk&aacute;zali, že Mountfield HK m&aacute; nejen silnou současnost, ale i slibnou budoucnost.</p>\r\n<h3 data-start=\"1292\" data-end=\"1340\">Nad&scaron;en&iacute; fanou&scaron;ků a oček&aacute;v&aacute;n&iacute; před play-off</h3>\r\n<p data-start=\"1341\" data-end=\"1551\">Hradečt&iacute; fanou&scaron;ci patř&iacute; mezi nejv&aacute;&scaron;nivěj&scaron;&iacute; v extralize a oček&aacute;v&aacute;n&iacute; před vyřazovac&iacute; č&aacute;st&iacute; jsou obrovsk&aacute;. Ar&eacute;na v Hradci Kr&aacute;lov&eacute; bude při dom&aacute;c&iacute;ch z&aacute;pasech zcela zaplněn&aacute; a atmosf&eacute;ra bude doslova elektrizuj&iacute;c&iacute;.</p>\r\n<p data-start=\"1553\" data-end=\"1809\">Play-off je specifick&aacute; soutěž, kde rozhoduj&iacute; nejen individu&aacute;ln&iacute; v&yacute;kony, ale i t&yacute;mov&yacute; duch, taktika a pevn&eacute; nervy. Pr&aacute;vě v těchto aspektech se Mountfield HK bude muset opř&iacute;t o sv&eacute; zku&scaron;en&eacute; hr&aacute;če, kteř&iacute; již maj&iacute; s těmito vypjat&yacute;mi momenty bohat&eacute; zku&scaron;enosti.</p>\r\n<h3 data-start=\"1811\" data-end=\"1855\">Možn&iacute; soupeři a strategie pro play-off</h3>\r\n<p data-start=\"1856\" data-end=\"2016\">V z&aacute;vislosti na konečn&eacute;m um&iacute;stěn&iacute; v z&aacute;kladn&iacute; č&aacute;sti se Hradec Kr&aacute;lov&eacute; utk&aacute; s jedn&iacute;m z t&yacute;mů, kter&eacute; postoup&iacute; z předkola play-off. Možn&yacute;mi soupeři jsou např&iacute;klad:</p>\r\n<ol data-start=\"2017\" data-end=\"2256\">\r\n<li data-start=\"2017\" data-end=\"2074\"><strong data-start=\"2020\" data-end=\"2035\">Kometa Brno</strong> &ndash; tradičn&iacute; soupeř s kvalitn&iacute;m k&aacute;drem</li>\r\n<li data-start=\"2075\" data-end=\"2137\"><strong data-start=\"2078\" data-end=\"2096\">Ocel&aacute;ři Třinec</strong> &ndash; &uacute;řaduj&iacute;c&iacute; &scaron;ampion s velk&yacute;mi ambicemi</li>\r\n<li data-start=\"2138\" data-end=\"2200\"><strong data-start=\"2141\" data-end=\"2163\">B&iacute;l&iacute; Tygři Liberec</strong> &ndash; nebezpečn&yacute; t&yacute;m s rychl&yacute;m hokejem</li>\r\n<li data-start=\"2201\" data-end=\"2256\"><strong data-start=\"2204\" data-end=\"2220\">Sparta Praha</strong> &ndash; jeden z nejsilněj&scaron;&iacute;ch t&yacute;mů ligy</li>\r\n</ol>\r\n<p data-start=\"2258\" data-end=\"2494\">Taktika bude kl&iacute;čov&yacute;m faktorem &uacute;spěchu. Tren&eacute;rsk&yacute; t&yacute;m mus&iacute; připravit strategii na každ&eacute;ho soupeře zvl&aacute;&scaron;ť. Důležit&eacute; bude nejen ubr&aacute;nit nebezpečn&eacute; &uacute;toky protivn&iacute;ků, ale tak&eacute; využ&iacute;vat každou &scaron;anci k rychl&yacute;m proti&uacute;tokům a přesilov&yacute;m hr&aacute;m.</p>\r\n<h3 data-start=\"2496\" data-end=\"2524\">Co rozhodne o &uacute;spěchu?</h3>\r\n<p data-start=\"2525\" data-end=\"2598\">V play-off často rozhoduj&iacute; drobnosti. Mezi kl&iacute;čov&eacute; faktory bude patřit:</p>\r\n<ul data-start=\"2599\" data-end=\"2961\">\r\n<li data-start=\"2599\" data-end=\"2709\"><strong data-start=\"2601\" data-end=\"2621\">Brank&aacute;řsk&aacute; forma</strong> &ndash; pokud Matěj Machovsk&yacute; udrž&iacute; vysokou &uacute;roveň v&yacute;konů, může b&yacute;t velk&yacute;m faktorem &uacute;spěchu</li>\r\n<li data-start=\"2710\" data-end=\"2816\"><strong data-start=\"2712\" data-end=\"2744\">Produktivita kl&iacute;čov&yacute;ch hr&aacute;čů</strong> &ndash; Hradec bude potřebovat, aby jeho elitn&iacute; formace bodovala pravidelně</li>\r\n<li data-start=\"2817\" data-end=\"2886\"><strong data-start=\"2819\" data-end=\"2833\">Discipl&iacute;na</strong> &ndash; zbytečn&aacute; vyloučen&iacute; mohou t&yacute;m st&aacute;t kl&iacute;čov&eacute; z&aacute;pasy</li>\r\n<li data-start=\"2887\" data-end=\"2961\"><strong data-start=\"2889\" data-end=\"2909\">Dom&aacute;c&iacute; prostřed&iacute;</strong> &ndash; podpora fanou&scaron;ků může b&yacute;t rozhoduj&iacute;c&iacute;m faktorem</li>\r\n</ul>\r\n<h3 data-start=\"2963\" data-end=\"2974\">Z&aacute;věr</h3>\r\n<p data-start=\"2975\" data-end=\"3276\" data-is-last-node=\"\" data-is-only-node=\"\">Mountfield HK m&aacute; před sebou velkou v&yacute;zvu. Pokud se t&yacute;mu podař&iacute; nav&aacute;zat na v&yacute;kony ze z&aacute;kladn&iacute; č&aacute;sti a udrž&iacute; koncentraci, může doj&iacute;t velmi daleko. Fanou&scaron;ci věř&iacute;, že letos je ten spr&aacute;vn&yacute; čas na historick&yacute; &uacute;spěch. Prvn&iacute; z&aacute;pasy play-off rozhodnou, zda se Hradec Kr&aacute;lov&eacute; stane skutečn&yacute;m kandid&aacute;tem na titul.</p>', '2025-03-11 10:14:21', '2025-03-18 11:59:37', 1, 18, 4, 4),
(166, 'Hokejové derby Pardubice vs. Hradec přilákalo rekordní návštěvnost', 'Hokejové derby mezi Pardubicemi a Hradcem Králové nabídlo strhující souboj a rekordní návštěvnost. Fanoušci si užili napínavý zápas až do poslední minuty. Jak duel dopadl? Čtěte dál!', 'Hokejové derby mezi Pardubicemi a Hradcem Králové přilákalo rekordní počet diváků a nabídlo napínavou podívanou. Utkání bylo vyrovnané až do posledních minut, kdy Pardubice rozhodly v prodloužení. Atmosféra v hale byla bouřlivá a fanoušci vytvořili nezapomenutelný zážitek. Rivalita mezi kluby tak zůstává jedním z největších taháků východočeského hokeje.', '<article class=\"w-full text-token-text-primary focus-visible:outline-2 focus-visible:outline-offset-[-4px]\" dir=\"auto\" data-testid=\"conversation-turn-135\" data-scroll-anchor=\"true\">\r\n<div class=\"text-base my-auto mx-auto py-[18px] px-6\">\r\n<div class=\"mx-auto flex flex-1 text-base gap-4 md:gap-5 lg:gap-6 md:max-w-3xl lg:max-w-[40rem] xl:max-w-[48rem]\">\r\n<div class=\"group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn @xs/thread:px-0 @sm/thread:px-1.5 @md/thread:px-4\">\r\n<div class=\"flex-col gap-1 md:gap-3\">\r\n<div class=\"flex max-w-full flex-col flex-grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 whitespace-normal break-words text-start [.text-message+&amp;]:mt-5\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"64127d20-f198-482a-a66b-85d85a675f50\" data-message-model-slug=\"gpt-4o\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\">\r\n<div class=\"markdown prose w-full break-words dark:prose-invert light\">\r\n<p data-start=\"0\" data-end=\"72\"><strong data-start=\"0\" data-end=\"70\">Hokejov&eacute; derby Pardubice vs. Hradec přil&aacute;kalo rekordn&iacute; n&aacute;v&scaron;těvnost</strong></p>\r\n<p data-start=\"74\" data-end=\"349\">Hokejov&eacute; derby mezi <strong data-start=\"94\" data-end=\"130\">Dynamo Pardubice a Mountfield HK</strong> opět uk&aacute;zalo, že v&yacute;chodočesk&eacute; souboje patř&iacute; mezi největ&scaron;&iacute; sportovn&iacute; ud&aacute;losti v regionu. Tentokr&aacute;t ale fanou&scaron;ci vytvořili atmosf&eacute;ru, kter&aacute; překonala v&scaron;echna oček&aacute;v&aacute;n&iacute; &ndash; utk&aacute;n&iacute; totiž sledovalo rekordn&iacute; množstv&iacute; div&aacute;ků.</p>\r\n<h3 data-start=\"351\" data-end=\"394\">Fantastick&aacute; atmosf&eacute;ra a vypjat&yacute; z&aacute;pas</h3>\r\n<p data-start=\"395\" data-end=\"692\">Hala praskala ve &scaron;vech a fanděn&iacute; bylo sly&scaron;et je&scaron;tě dlouho po z&aacute;věrečn&eacute;m hvizdu. Oba t&aacute;bory fanou&scaron;ků se postaraly o nezapomenuteln&yacute; z&aacute;žitek, kter&yacute; jen podtrhl důležitost tohoto utk&aacute;n&iacute;. <strong data-start=\"579\" data-end=\"619\">Z&aacute;pas byl od zač&aacute;tku velmi vyrovnan&yacute;</strong>, t&yacute;my předvedly atraktivn&iacute; hokej pln&yacute; tvrd&yacute;ch soubojů a rychl&yacute;ch akc&iacute;.</p>\r\n<p data-start=\"694\" data-end=\"1010\">Prvn&iacute; třetina přinesla aktivn&iacute; hru obou mužstev, ale brank&aacute;ři byli na sv&yacute;ch m&iacute;stech a sk&oacute;re se neměnilo. <strong data-start=\"799\" data-end=\"845\">Druh&aacute; třetina nab&iacute;dla prvn&iacute; g&oacute;lov&eacute; momenty</strong>, když se Pardubice dostaly do veden&iacute; po přesilovkov&eacute; trefě sv&eacute;ho nejlep&scaron;&iacute;ho střelce. Hradec v&scaron;ak brzy odpověděl a před posledn&iacute; č&aacute;st&iacute; z&aacute;pasu bylo sk&oacute;re vyrovnan&eacute;.</p>\r\n<h3 data-start=\"1012\" data-end=\"1059\">Rekordn&iacute; n&aacute;v&scaron;těvnost a fanou&scaron;kovsk&aacute; v&aacute;&scaron;eň</h3>\r\n<p data-start=\"1060\" data-end=\"1343\">Organiz&aacute;toři ozn&aacute;mili, že na z&aacute;pas dorazilo v&iacute;ce než <strong data-start=\"1113\" data-end=\"1132\">10 000 fanou&scaron;ků</strong>, což z tohoto utk&aacute;n&iacute; čin&iacute; <strong data-start=\"1159\" data-end=\"1198\">nejnav&scaron;těvovaněj&scaron;&iacute; derby v historii</strong> v&yacute;chodočesk&eacute; hokejov&eacute; rivality. <strong data-start=\"1231\" data-end=\"1261\">Obrovsk&yacute; z&aacute;jem o vstupenky</strong> byl patrn&yacute; už t&yacute;dny před utk&aacute;n&iacute;m, kdy se l&iacute;stky vyprodaly během několika hodin.</p>\r\n<p data-start=\"1345\" data-end=\"1504\">Podle veden&iacute; obou klubů je takov&yacute; z&aacute;jem důkazem, že rivalita mezi Pardubicemi a Hradcem Kr&aacute;lov&eacute; je st&aacute;le siln&aacute; a že v&yacute;chodočesk&yacute; hokej m&aacute; skvělou budoucnost.</p>\r\n<h3 data-start=\"1506\" data-end=\"1534\">Kl&iacute;čov&eacute; momenty z&aacute;pasu</h3>\r\n<p data-start=\"1535\" data-end=\"1576\">Největ&scaron;&iacute; drama při&scaron;lo ve třet&iacute; třetině:</p>\r\n<ul data-start=\"1577\" data-end=\"1874\">\r\n<li data-start=\"1577\" data-end=\"1650\">Hradec se dostal do veden&iacute; d&iacute;ky <strong data-start=\"1611\" data-end=\"1647\">rychl&eacute; akci prvn&iacute; &uacute;točn&eacute; formace</strong>.</li>\r\n<li data-start=\"1651\" data-end=\"1756\">Pardubice v&scaron;ak srovnaly <strong data-start=\"1677\" data-end=\"1702\">pět minut před koncem</strong>, když se po chybě obrany soupeře dostaly do brejku.</li>\r\n<li data-start=\"1757\" data-end=\"1874\">Rozhoduj&iacute;c&iacute; moment nastal v prodloužen&iacute;, kdy <strong data-start=\"1804\" data-end=\"1871\">Pardubice využily chybu hradeck&eacute; obrany a vstřelily v&iacute;tězn&yacute; g&oacute;l</strong>.</li>\r\n</ul>\r\n<h3 data-start=\"1876\" data-end=\"1904\">Ohlasy hr&aacute;čů a tren&eacute;rů</h3>\r\n<p data-start=\"1905\" data-end=\"2173\">Hr&aacute;či obou t&yacute;mů po z&aacute;pase vyzdvihovali <strong data-start=\"1944\" data-end=\"1976\">skvělou atmosf&eacute;ru a nasazen&iacute;</strong> obou celků. <strong data-start=\"1989\" data-end=\"2009\">Kapit&aacute;n Pardubic</strong> ocenil bojovnost sv&eacute;ho t&yacute;mu a poděkoval fanou&scaron;kům za jejich podporu. <strong data-start=\"2079\" data-end=\"2098\">Hradeck&yacute; tren&eacute;r</strong> naopak litoval nevyužit&yacute;ch &scaron;anc&iacute; a chyb, kter&eacute; st&aacute;ly jeho t&yacute;m v&iacute;tězstv&iacute;.</p>\r\n<h3 data-start=\"2175\" data-end=\"2198\">Co derby uk&aacute;zalo?</h3>\r\n<ol data-start=\"2199\" data-end=\"2474\">\r\n<li data-start=\"2199\" data-end=\"2311\"><strong data-start=\"2202\" data-end=\"2243\">Rivalita mezi kluby je st&aacute;le obrovsk&aacute;</strong> a z&aacute;pasy mezi Pardubicemi a Hradcem jsou jedn&iacute;m z vrcholů sez&oacute;ny.</li>\r\n<li data-start=\"2312\" data-end=\"2386\"><strong data-start=\"2315\" data-end=\"2347\">Z&aacute;jem fanou&scaron;ků o hokej roste</strong>, což potvrzuje rekordn&iacute; n&aacute;v&scaron;těvnost.</li>\r\n<li data-start=\"2387\" data-end=\"2474\"><strong data-start=\"2390\" data-end=\"2422\">Kvalita hry se st&aacute;le zvy&scaron;uje</strong> a oba t&yacute;my maj&iacute; ambice bojovat o nejvy&scaron;&scaron;&iacute; př&iacute;čky.</li>\r\n</ol>\r\n<p data-start=\"2476\" data-end=\"2620\" data-is-last-node=\"\" data-is-only-node=\"\">Př&iacute;&scaron;t&iacute; utk&aacute;n&iacute; těchto rivalů bude rozhodně opět velk&yacute;m l&aacute;kadlem pro v&scaron;echny hokejov&eacute; fanou&scaron;ky a nen&iacute; pochyb o tom, že i tentokr&aacute;t bude vyprod&aacute;no.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"mt-3 w-full empty:hidden\">&nbsp;</div>\r\n</div>\r\n<div class=\"absolute\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</article>', '2025-03-11 10:19:34', '2025-03-11 11:47:34', 0, 18, 4, 4),
(167, 'Běžecký závod v Orlických horách překonal očekávání pořadatelů', 'Běžecký závod v Orlických horách přilákal stovky nadšenců, kteří se utkali s náročným terénem i nepředvídatelným počasím. Kdo si odnesl vítězství a jaké byly letošní podmínky?', 'Běžecký závod v Orlických horách přilákal rekordní počet účastníků, kteří se museli vypořádat s náročnou horskou trasou a proměnlivým počasím. Vítězem hlavní kategorie mužů se stal Jakub Dvořák, mezi ženami dominovala Lucie Veselá. Organizátoři akci hodnotí jako mimořádně úspěšnou a již plánují vylepšení pro příští ročník.', '<h2 data-start=\"0\" data-end=\"68\"><strong data-start=\"0\" data-end=\"66\">Běžeck&yacute; z&aacute;vod v Orlick&yacute;ch hor&aacute;ch překonal oček&aacute;v&aacute;n&iacute; pořadatelů</strong></h2>\r\n<p data-start=\"70\" data-end=\"313\">Orlick&eacute; hory se o v&iacute;kendu staly ději&scaron;těm jednoho z největ&scaron;&iacute;ch běžeck&yacute;ch z&aacute;vodů v regionu. Leto&scaron;n&iacute; ročn&iacute;k přil&aacute;kal rekordn&iacute; počet &uacute;častn&iacute;ků, kteř&iacute; se vydali na n&aacute;ročn&eacute; horsk&eacute; trasy. Pořadatel&eacute; i z&aacute;vodn&iacute;ci hodnot&iacute; akci jako mimoř&aacute;dně &uacute;spě&scaron;nou.</p>\r\n<h3 data-start=\"315\" data-end=\"354\">Rekordn&iacute; &uacute;čast a skvěl&aacute; atmosf&eacute;ra</h3>\r\n<p data-start=\"355\" data-end=\"600\">Organiz&aacute;toři oček&aacute;vali vysokou &uacute;čast, ale skutečn&eacute; č&iacute;slo předčilo v&scaron;echna oček&aacute;v&aacute;n&iacute;. Letos se na start postavilo v&iacute;ce než <em data-start=\"477\" data-end=\"490\">1 500 běžců</em> z cel&eacute; Česk&eacute; republiky i ze zahranič&iacute;. Velk&yacute; z&aacute;jem byl jak o hlavn&iacute; z&aacute;vod na <em data-start=\"568\" data-end=\"575\">50 km</em>, tak i o krat&scaron;&iacute; tratě.</p>\r\n<p data-start=\"602\" data-end=\"771\">&bdquo;Takov&yacute; počet z&aacute;vodn&iacute;ků jsme nečekali. Každ&yacute;m rokem roste z&aacute;jem o horsk&eacute; běhy, ale leto&scaron;n&iacute; ročn&iacute;k byl opravdu v&yacute;jimečn&yacute;,&ldquo; uvedl hlavn&iacute; organiz&aacute;tor z&aacute;vodu Petr Novotn&yacute;.</p>\r\n<h3 data-start=\"773\" data-end=\"812\">N&aacute;ročn&aacute; trať prověřila s&iacute;ly běžců</h3>\r\n<p data-start=\"813\" data-end=\"1015\">Z&aacute;vodn&iacute;ci se museli poprat s proměnliv&yacute;m počas&iacute;m a n&aacute;ročn&yacute;m ter&eacute;nem. Trasa vedla přes <strong data-start=\"899\" data-end=\"924\">vrcholy Orlick&yacute;ch hor</strong>, lesn&iacute; cesty i kamenit&eacute; &uacute;seky, kter&eacute; prověřily fyzickou i psychickou odolnost &uacute;častn&iacute;ků.</p>\r\n<p data-start=\"1017\" data-end=\"1045\">Mezi hlavn&iacute; v&yacute;zvy patřila:</p>\r\n<ul data-start=\"1046\" data-end=\"1241\">\r\n<li data-start=\"1046\" data-end=\"1097\"><strong data-start=\"1048\" data-end=\"1066\">Strm&aacute; stoup&aacute;n&iacute;</strong> v prvn&iacute;ch kilometrech z&aacute;vodu</li>\r\n<li data-start=\"1098\" data-end=\"1170\"><strong data-start=\"1100\" data-end=\"1128\">Technicky n&aacute;ročn&eacute; seběhy</strong>, kter&eacute; vyžadovaly maxim&aacute;ln&iacute; koncentraci</li>\r\n<li data-start=\"1171\" data-end=\"1241\"><strong data-start=\"1173\" data-end=\"1199\">Nepředv&iacute;dateln&eacute; počas&iacute;</strong> &ndash; č&aacute;st z&aacute;vodu se běžela v mlze a chladu</li>\r\n</ul>\r\n<h3 data-start=\"1243\" data-end=\"1274\">V&iacute;tězov&eacute; a osobn&iacute; rekordy</h3>\r\n<p data-start=\"1275\" data-end=\"1453\">V hlavn&iacute; kategorii mužů zv&iacute;tězil <strong data-start=\"1308\" data-end=\"1324\">Jakub Dvoř&aacute;k</strong>, kter&yacute; zdolal trať v čase <em data-start=\"1351\" data-end=\"1372\">4 hodiny a 12 minut</em>. Mezi ženami dominovala <strong data-start=\"1397\" data-end=\"1413\">Lucie Vesel&aacute;</strong>, kter&aacute; překonala sv&eacute; vlastn&iacute; maximum.</p>\r\n<p data-start=\"1455\" data-end=\"1668\">Běžci ocenili nejen skvěle značenou trasu, ale tak&eacute; podporu div&aacute;ků. &bdquo;Byla to jedna z nejhezč&iacute;ch tras, co jsem běžel. Počas&iacute; sice nebylo ide&aacute;ln&iacute;, ale atmosf&eacute;ra byla fantastick&aacute;,&ldquo; pochvaloval si jeden z &uacute;častn&iacute;ků.</p>\r\n<h3 data-start=\"1670\" data-end=\"1698\">Organizace na jedničku</h3>\r\n<p data-start=\"1699\" data-end=\"1970\">Pořadatel&eacute; kladli důraz na <strong data-start=\"1726\" data-end=\"1740\">bezpečnost</strong> i pohodl&iacute; z&aacute;vodn&iacute;ků. Na trase byly rozm&iacute;stěny <strong data-start=\"1787\" data-end=\"1812\">občerstvovac&iacute; stanice</strong> a zdravotn&iacute;ci byli připraveni pomoci v př&iacute;padě &uacute;razu. Velk&yacute;m &uacute;spěchem byla tak&eacute; <strong data-start=\"1893\" data-end=\"1916\">dobrovolnick&aacute; pomoc</strong> &ndash; des&iacute;tky lid&iacute; se pod&iacute;lely na hladk&eacute;m průběhu akce.</p>\r\n<h3 data-start=\"1972\" data-end=\"1997\">Pl&aacute;ny na př&iacute;&scaron;t&iacute; rok</h3>\r\n<p data-start=\"1998\" data-end=\"2161\">S takov&yacute;m &uacute;spěchem leto&scaron;n&iacute;ho ročn&iacute;ku už pořadatel&eacute; přem&yacute;&scaron;lej&iacute; o <strong data-start=\"2062\" data-end=\"2089\">dal&scaron;&iacute;m vylep&scaron;en&iacute; z&aacute;vodu</strong>. &bdquo;Chceme přidat nov&eacute; trasy, možn&aacute; i nočn&iacute; běh,&ldquo; naznačil organiz&aacute;tor.</p>\r\n<p data-start=\"2163\" data-end=\"2358\" data-is-last-node=\"\" data-is-only-node=\"\">Běžeck&yacute; z&aacute;vod v Orlick&yacute;ch hor&aacute;ch tak potvrzuje svou pověst jednoho z nejlep&scaron;&iacute;ch horsk&yacute;ch běhů v Česku. Už teď je jasn&eacute;, že př&iacute;&scaron;t&iacute; rok bude opět pln&yacute; v&yacute;zev a nezapomenuteln&yacute;ch sportovn&iacute;ch z&aacute;žitků.</p>', '2025-03-11 10:24:34', '2025-03-11 11:47:34', 0, 18, 4, 4),
(168, 'Pardubický dostihový spolek hlásí velké změny v organizaci Velké pardubické', 'Velká pardubická čekají zásadní změny, které mají zvýšit bezpečnost a zatraktivnit závod pro diváky. Pořadatelé upraví trať, zpřísní pravidla a zmodernizují organizaci. Jaké novinky přinese letošní ročník?', 'Pardubický dostihový spolek oznámil zásadní změny v organizaci Velké pardubické, které se dotknou tratě, pravidel závodu i diváckého zázemí. Cílem úprav je zvýšit bezpečnost koní a jezdců, zpřísnit veterinární kontroly a modernizovat financování. Pořadatelé také slibují lepší komfort pro diváky a širší mediální pokrytí. Změny vyvolaly smíšené reakce, ale organizátoři ujišťují, že závod zůstane věrný své dlouholeté tradici.', '<h2 data-start=\"0\" data-end=\"81\"><strong data-start=\"0\" data-end=\"79\">Pardubick&yacute; dostihov&yacute; spolek hl&aacute;s&iacute; velk&eacute; změny v organizaci Velk&eacute; pardubick&eacute;</strong></h2>\r\n<p data-start=\"83\" data-end=\"419\">Pardubick&yacute; dostihov&yacute; spolek ozn&aacute;mil z&aacute;sadn&iacute; změny v organizaci slavn&eacute;ho dostihu Velk&aacute; pardubick&aacute;. Tyto &uacute;pravy se dotknou jak samotn&eacute;ho z&aacute;vodu, tak doprovodn&eacute;ho programu, financov&aacute;n&iacute; a př&iacute;stupu k div&aacute;kům. C&iacute;lem nov&yacute;ch opatřen&iacute; je modernizace dostihov&eacute;ho sportu, zv&yacute;&scaron;en&iacute; bezpečnosti kon&iacute; i jezdců a zlep&scaron;en&iacute; celkov&eacute;ho div&aacute;ck&eacute;ho z&aacute;žitku.</p>\r\n<h3 data-start=\"421\" data-end=\"448\"><strong data-start=\"425\" data-end=\"446\">Nov&eacute; &uacute;pravy tratě</strong></h3>\r\n<p data-start=\"450\" data-end=\"515\">Jednou z nejv&yacute;znamněj&scaron;&iacute;ch změn je &uacute;prava trati, kter&aacute; zahrnuje:</p>\r\n<ul data-start=\"517\" data-end=\"720\">\r\n<li data-start=\"517\" data-end=\"584\">Změnu um&iacute;stěn&iacute; několika přek&aacute;žek s c&iacute;lem zv&yacute;&scaron;it bezpečnost kon&iacute;</li>\r\n<li data-start=\"585\" data-end=\"639\">Roz&scaron;&iacute;řen&iacute; někter&yacute;ch &uacute;seků pro snaz&scaron;&iacute; průběh z&aacute;vodu</li>\r\n<li data-start=\"640\" data-end=\"720\">&Uacute;pravu povrchu dr&aacute;hy s využit&iacute;m modern&iacute;ch materi&aacute;lů, kter&eacute; l&eacute;pe tlum&iacute; n&aacute;razy</li>\r\n</ul>\r\n<p data-start=\"722\" data-end=\"850\">Podle pořadatelů je c&iacute;lem těchto opatřen&iacute; sn&iacute;žen&iacute; počtu p&aacute;dů a zraněn&iacute;, kter&aacute; v minul&yacute;ch letech vyvol&aacute;vala značn&eacute; kontroverze.</p>\r\n<h3 data-start=\"852\" data-end=\"894\"><strong data-start=\"856\" data-end=\"892\">Změny v pravidlech a &uacute;časti kon&iacute;</strong></h3>\r\n<p data-start=\"896\" data-end=\"991\">Aby byl z&aacute;vod f&eacute;rověj&scaron;&iacute; a bezpečněj&scaron;&iacute;, dostihov&yacute; spolek přich&aacute;z&iacute; s nov&yacute;mi pravidly pro &uacute;čast:</p>\r\n<ol data-start=\"993\" data-end=\"1421\">\r\n<li data-start=\"993\" data-end=\"1140\"><strong data-start=\"996\" data-end=\"1030\">Př&iacute;sněj&scaron;&iacute; veterin&aacute;rn&iacute; kontroly</strong> &ndash; koně budou před i po z&aacute;vodě důkladněji kontrolov&aacute;ni, aby se minimalizovalo riziko zdravotn&iacute;ch komplikac&iacute;.</li>\r\n<li data-start=\"1141\" data-end=\"1305\"><strong data-start=\"1144\" data-end=\"1169\">Věk a zku&scaron;enosti kon&iacute;</strong> &ndash; do z&aacute;vodu budou moci nastoupit pouze koně, kteř&iacute; spln&iacute; nově stanoven&aacute; krit&eacute;ria t&yacute;kaj&iacute;c&iacute; se věku a předchoz&iacute;ch v&yacute;sledků v dostiz&iacute;ch.</li>\r\n<li data-start=\"1306\" data-end=\"1421\"><strong data-start=\"1309\" data-end=\"1339\">Omezen&iacute; počtu startuj&iacute;c&iacute;ch</strong> &ndash; kvůli bezpečnosti bude sn&iacute;žen počet kon&iacute;, kteř&iacute; se postav&iacute; na startovn&iacute; č&aacute;ru.</li>\r\n</ol>\r\n<h3 data-start=\"1423\" data-end=\"1473\"><strong data-start=\"1427\" data-end=\"1471\">Nov&yacute; př&iacute;stup k financov&aacute;n&iacute; a sponzorstv&iacute;</strong></h3>\r\n<p data-start=\"1475\" data-end=\"1588\">Velk&aacute; pardubick&aacute; se dlouhodobě pot&yacute;kala s ot&aacute;zkami financov&aacute;n&iacute;, a proto se spolek rozhodl zav&eacute;st nov&aacute; opatřen&iacute;:</p>\r\n<ul data-start=\"1590\" data-end=\"1778\">\r\n<li data-start=\"1590\" data-end=\"1632\">Roz&scaron;&iacute;řen&iacute; spolupr&aacute;ce s nov&yacute;mi sponzory</li>\r\n<li data-start=\"1633\" data-end=\"1695\">Zaveden&iacute; speci&aacute;ln&iacute;ch VIP vstupenek s exkluzivn&iacute;mi v&yacute;hodami</li>\r\n<li data-start=\"1696\" data-end=\"1778\">Možnost př&iacute;m&eacute; podpory prostřednictv&iacute;m d&aacute;rcovsk&yacute;ch programů pro dostihov&eacute; st&aacute;je</li>\r\n</ul>\r\n<p data-start=\"1780\" data-end=\"1912\">Podle organiz&aacute;torů je kl&iacute;čov&eacute; zajistit stabiln&iacute; financov&aacute;n&iacute;, kter&eacute; umožn&iacute; nejen zachov&aacute;n&iacute; tradice z&aacute;vodu, ale i jeho dal&scaron;&iacute; rozvoj.</p>\r\n<h3 data-start=\"1914\" data-end=\"1952\"><strong data-start=\"1918\" data-end=\"1950\">Modernizace div&aacute;ck&eacute;ho z&aacute;zem&iacute;</strong></h3>\r\n<p data-start=\"1954\" data-end=\"2027\">Dal&scaron;&iacute; z&aacute;sadn&iacute; změny se dotknou i komfortu div&aacute;ků. Organiz&aacute;toři pl&aacute;nuj&iacute;:</p>\r\n<ul data-start=\"2029\" data-end=\"2188\">\r\n<li data-start=\"2029\" data-end=\"2060\">Vět&scaron;&iacute; a pohodlněj&scaron;&iacute; tribuny</li>\r\n<li data-start=\"2061\" data-end=\"2113\">Lep&scaron;&iacute; dostupnost občerstven&iacute; a soci&aacute;ln&iacute;ho z&aacute;zem&iacute;</li>\r\n<li data-start=\"2114\" data-end=\"2188\">Digit&aacute;ln&iacute; tabule zobrazuj&iacute;c&iacute; průběh z&aacute;vodu a statistiky v re&aacute;ln&eacute;m čase</li>\r\n</ul>\r\n<p data-start=\"2190\" data-end=\"2310\">Z&aacute;roveň se pracuje na roz&scaron;&iacute;řen&iacute; online přenosů a zlep&scaron;en&iacute; televizn&iacute;ho pokryt&iacute;, aby z&aacute;vod oslovil je&scaron;tě &scaron;ir&scaron;&iacute; publikum.</p>\r\n<h3 data-start=\"2312\" data-end=\"2351\"><strong data-start=\"2316\" data-end=\"2349\">Reakce veřejnosti a odborn&iacute;ků</strong></h3>\r\n<p data-start=\"2353\" data-end=\"2682\">Nov&aacute; opatřen&iacute; vyvolala sm&iacute;&scaron;en&eacute; reakce. Zat&iacute;mco někteř&iacute; odborn&iacute;ci a aktivist&eacute; pro pr&aacute;va zv&iacute;řat oceňuj&iacute; snahu o vět&scaron;&iacute; bezpečnost kon&iacute;, jin&iacute; se ob&aacute;vaj&iacute;, že někter&eacute; změny by mohly naru&scaron;it tradičn&iacute; charakter z&aacute;vodu. Na druh&eacute; straně fanou&scaron;ci v&iacute;taj&iacute; modernizaci a oček&aacute;vaj&iacute;, že nov&aacute; pravidla povedou k atraktivněj&scaron;&iacute;mu průběhu dostihu.</p>\r\n<h3 data-start=\"2684\" data-end=\"2721\"><strong data-start=\"2688\" data-end=\"2719\">Budoucnost Velk&eacute; pardubick&eacute;</strong></h3>\r\n<p data-start=\"2723\" data-end=\"2988\">I přes ve&scaron;ker&eacute; změny organiz&aacute;toři uji&scaron;ťuj&iacute;, že Velk&aacute; pardubick&aacute; zůstane věrn&aacute; sv&yacute;m historick&yacute;m kořenům. Tradice tohoto prestižn&iacute;ho z&aacute;vodu sah&aacute; až do roku 1874 a pořadatel&eacute; jsou si vědomi jej&iacute;ho v&yacute;znamu nejen pro česk&yacute; dostihov&yacute; sport, ale i pro &scaron;irokou veřejnost.</p>\r\n<p data-start=\"2990\" data-end=\"3269\" data-is-last-node=\"\" data-is-only-node=\"\">V n&aacute;sleduj&iacute;c&iacute;ch měs&iacute;c&iacute;ch bude kl&iacute;čov&eacute; sledovat, jak se novinky osvědč&iacute; a zda skutečně přinesou pozitivn&iacute; dopad na bezpečnost a atraktivitu z&aacute;vodu. Fanou&scaron;ci se každop&aacute;dně mohou tě&scaron;it na nap&iacute;navou pod&iacute;vanou, kter&aacute; bude z&aacute;roveň o něco moderněj&scaron;&iacute; a bezpečněj&scaron;&iacute; než v minul&yacute;ch letech.</p>', '2025-03-11 10:28:59', '2025-03-11 11:47:34', 0, 18, 4, 4),
(169, 'Mladí fotbalisté z východních Čech září v reprezentaci', 'Mladí fotbalisté z východních Čech si získávají pozornost nejen v české reprezentaci, ale i v zahraničních klubech. Díky systematické přípravě a talentu se prosazují na mezinárodní scéně a otevírají si cestu k profesionální kariéře. Jaké faktory stojí za jejich úspěchem?', 'Mladí fotbalisté z východních Čech se stále více prosazují v mládežnických reprezentacích a zahraničních klubech. Díky kvalitní práci regionálních akademií a moderním tréninkovým metodám získávají cenné zkušenosti, které jim otevírají dveře do profesionálního fotbalu. Někteří už mají za sebou stáže v prestižních evropských klubech a první smlouvy v zahraničí, což potvrzuje rostoucí význam východních Čech jako centra fotbalových talentů.', '<h2 data-start=\"0\" data-end=\"60\"><strong data-start=\"0\" data-end=\"58\">Mlad&iacute; fotbalist&eacute; z v&yacute;chodn&iacute;ch Čech z&aacute;ř&iacute; v reprezentaci</strong></h2>\r\n<p data-start=\"62\" data-end=\"354\">Fotbalov&aacute; sc&eacute;na v Česku zaž&iacute;v&aacute; v posledn&iacute;ch letech n&aacute;růst talentovan&yacute;ch mlad&yacute;ch hr&aacute;čů a v&yacute;chodn&iacute; Čechy se st&aacute;vaj&iacute; jednou z hlavn&iacute;ch l&iacute;hn&iacute; budouc&iacute;ch hvězd. Mnoho mlad&yacute;ch fotbalistů z tohoto regionu se dostalo do ml&aacute;dežnick&yacute;ch reprezentac&iacute; a zač&iacute;naj&iacute; si budovat jm&eacute;no i na mezin&aacute;rodn&iacute; &uacute;rovni.</p>\r\n<h3 data-start=\"356\" data-end=\"388\">Siln&aacute; ml&aacute;dežnick&aacute; z&aacute;kladna</h3>\r\n<p data-start=\"390\" data-end=\"650\">V&yacute;chodn&iacute; Čechy maj&iacute; dlouhou tradici v&yacute;chovy kvalitn&iacute;ch fotbalistů. Kluby jako <strong data-start=\"468\" data-end=\"520\">FC Hradec Kr&aacute;lov&eacute;, FK Pardubice nebo MFK Chrudim</strong> dlouhodobě pracuj&iacute; s ml&aacute;dež&iacute; a zaměřuj&iacute; se na rozvoj technick&yacute;ch dovednost&iacute;, taktick&eacute; vyspělosti i fyzick&eacute; připravenosti hr&aacute;čů.</p>\r\n<p data-start=\"652\" data-end=\"681\"><strong data-start=\"652\" data-end=\"679\">Hlavn&iacute; faktory &uacute;spěchu:</strong></p>\r\n<ul data-start=\"682\" data-end=\"1042\">\r\n<li data-start=\"682\" data-end=\"817\"><em data-start=\"684\" data-end=\"715\">Kvalitn&iacute; ml&aacute;dežnick&eacute; akademie</em> &ndash; Hradec Kr&aacute;lov&eacute; a Pardubice investuj&iacute; do v&yacute;chovy talentů a spolupracuj&iacute; s profesion&aacute;ln&iacute;mi tren&eacute;ry.</li>\r\n<li data-start=\"818\" data-end=\"940\"><em data-start=\"820\" data-end=\"847\">Modern&iacute; tr&eacute;ninkov&eacute; metody</em> &ndash; Mlad&iacute; hr&aacute;či využ&iacute;vaj&iacute; individu&aacute;ln&iacute; i t&yacute;mov&eacute; tr&eacute;ninky zaměřen&eacute; na rozvoj hern&iacute;ho my&scaron;len&iacute;.</li>\r\n<li data-start=\"941\" data-end=\"1042\"><em data-start=\"943\" data-end=\"977\">Siln&aacute; podpora region&aacute;ln&iacute;ch klubů</em> &ndash; M&iacute;stn&iacute; t&yacute;my d&aacute;vaj&iacute; &scaron;anci mlad&yacute;m talentům v dospěl&eacute;m fotbale.</li>\r\n</ul>\r\n<h3 data-start=\"1044\" data-end=\"1071\">Reprezentačn&iacute; &uacute;spěchy</h3>\r\n<p data-start=\"1073\" data-end=\"1442\">Hned několik hr&aacute;čů z v&yacute;chodn&iacute;ch Čech se prosadilo v ml&aacute;dežnick&yacute;ch reprezentac&iacute;ch <strong data-start=\"1154\" data-end=\"1172\">U15, U17 a U19</strong>. Mezi nejv&yacute;razněj&scaron;&iacute; jm&eacute;na patř&iacute; <strong data-start=\"1205\" data-end=\"1222\">Luk&aacute;&scaron; Novotn&yacute;</strong>, talentovan&yacute; &uacute;točn&iacute;k z Hradce Kr&aacute;lov&eacute;, kter&yacute; se v reprezentačn&iacute;m dresu pravidelně trefuje do s&iacute;tě soupeřů. Dal&scaron;&iacute;m př&iacute;kladem je <strong data-start=\"1350\" data-end=\"1367\">Michal Dvoř&aacute;k</strong>, z&aacute;ložn&iacute;k z Pardubic, kter&yacute; zaujal skvělou technikou a přehledem ve hře.</p>\r\n<p data-start=\"1444\" data-end=\"1656\"><strong data-start=\"1444\" data-end=\"1496\">Tren&eacute;r reprezentačn&iacute;ho v&yacute;běru U19 k tomu dod&aacute;v&aacute;:</strong><br data-start=\"1496\" data-end=\"1499\"><em data-start=\"1499\" data-end=\"1654\">\"Vid&iacute;me velk&yacute; potenci&aacute;l ve hr&aacute;č&iacute;ch z v&yacute;chodn&iacute;ch Čech. Maj&iacute; nejen technick&eacute; schopnosti, ale tak&eacute; spr&aacute;vn&yacute; př&iacute;stup k tr&eacute;ninku a chuť se neust&aacute;le zlep&scaron;ovat.\"</em></p>\r\n<h3 data-start=\"1658\" data-end=\"1686\">Mezin&aacute;rodn&iacute; zku&scaron;enosti</h3>\r\n<p data-start=\"1688\" data-end=\"2010\">Mlad&iacute; hr&aacute;či z v&yacute;chodn&iacute;ch Čech se postupně prosazuj&iacute; i v zahranič&iacute;. Někteř&iacute; dostali př&iacute;ležitost absolvovat st&aacute;že v akademi&iacute;ch prestižn&iacute;ch evropsk&yacute;ch klubů. Např&iacute;klad <strong data-start=\"1853\" data-end=\"1868\">Jan Svoboda</strong>, obr&aacute;nce původem z Chrudimi, si vyzkou&scaron;el tr&eacute;ninkov&yacute; kemp v německ&eacute;m <strong data-start=\"1938\" data-end=\"1959\">Borussii Dortmund</strong> a jeho v&yacute;kon si z&iacute;skal pozornost tamn&iacute;ch skautů.</p>\r\n<p data-start=\"2012\" data-end=\"2203\">Dal&scaron;&iacute; talenti už dokonce podepsali smlouvy v zahranič&iacute;. <strong data-start=\"2068\" data-end=\"2084\">Tom&aacute;&scaron; Kučera</strong>, brank&aacute;ř z Hradce Kr&aacute;lov&eacute;, se ned&aacute;vno připojil k italsk&eacute;mu klubu <strong data-start=\"2150\" data-end=\"2162\">AC Milan</strong>, kde bude působit v ml&aacute;dežnick&eacute;m t&yacute;mu.</p>\r\n<h3 data-start=\"2205\" data-end=\"2235\">Co ček&aacute; mlad&eacute; hr&aacute;če d&aacute;l?</h3>\r\n<p data-start=\"2237\" data-end=\"2427\">&Uacute;spěchy v reprezentaci a zahraničn&iacute; angažm&aacute; jsou jen zač&aacute;tkem kari&eacute;ry. Mnoz&iacute; z těchto hr&aacute;čů se brzy dostanou do <strong data-start=\"2349\" data-end=\"2382\">A-t&yacute;mů sv&yacute;ch mateřsk&yacute;ch klubů</strong> a budou bojovat o m&iacute;sto mezi profesion&aacute;ly.</p>\r\n<p data-start=\"2429\" data-end=\"2458\"><strong data-start=\"2429\" data-end=\"2456\">V&yacute;zvy, kter&eacute; je čekaj&iacute;:</strong></p>\r\n<ol data-start=\"2459\" data-end=\"2742\">\r\n<li data-start=\"2459\" data-end=\"2562\"><em data-start=\"2462\" data-end=\"2503\">Zvl&aacute;dnut&iacute; přechodu do dospěl&eacute;ho fotbalu</em> &ndash; Fyzick&aacute; n&aacute;ročnost a rychlost hry jsou na vy&scaron;&scaron;&iacute; &uacute;rovni.</li>\r\n<li data-start=\"2563\" data-end=\"2651\"><em data-start=\"2566\" data-end=\"2595\">Udržen&iacute; psychick&eacute; odolnosti</em> &ndash; Mlad&iacute; hr&aacute;či se mus&iacute; vyrovnat s tlakem a oček&aacute;v&aacute;n&iacute;m.</li>\r\n<li data-start=\"2652\" data-end=\"2742\"><em data-start=\"2655\" data-end=\"2689\">Rozvoj individu&aacute;ln&iacute;ch dovednost&iacute;</em> &ndash; I v reprezentaci je kladen důraz na osobn&iacute; růst.</li>\r\n</ol>\r\n<h3 data-start=\"2744\" data-end=\"2790\">Budoucnost fotbalu ve v&yacute;chodn&iacute;ch Čech&aacute;ch</h3>\r\n<p data-start=\"2792\" data-end=\"3034\">D&iacute;ky systematick&eacute; pr&aacute;ci s ml&aacute;dež&iacute; a podpoře talentovan&yacute;ch hr&aacute;čů se v&yacute;chodn&iacute; Čechy st&aacute;vaj&iacute; <strong data-start=\"2882\" data-end=\"2928\">jedn&iacute;m z kl&iacute;čov&yacute;ch regionů česk&eacute;ho fotbalu</strong>. S nadch&aacute;zej&iacute;c&iacute; generac&iacute; talentovan&yacute;ch hr&aacute;čů m&aacute; česk&yacute; fotbal naději na je&scaron;tě vět&scaron;&iacute; mezin&aacute;rodn&iacute; &uacute;spěchy.</p>\r\n<p data-start=\"3036\" data-end=\"3225\" data-is-last-node=\"\" data-is-only-node=\"\">Fanou&scaron;ci mohou sledovat v&yacute;kony sv&yacute;ch naděj&iacute; nejen v dom&aacute;c&iacute; lize, ale tak&eacute; při reprezentačn&iacute;ch z&aacute;pasech, kde budou mlad&iacute; fotbalist&eacute; z v&yacute;chodn&iacute;ch Čech bojovat za barvy česk&eacute;ho n&aacute;rodn&iacute;ho t&yacute;mu.</p>', '2025-03-11 10:34:39', '2025-03-18 12:02:37', 1, 18, 4, 4),
(170, 'Dálnice D35 u Vysokého Mýta se dočká rozšíření, práce začnou letos na podzim', 'Dálnice D35 u Vysokého Mýta se brzy dočká rozšíření, které zlepší plynulost a bezpečnost dopravy. Stavební práce odstartují na podzim a přinesou modernizaci celé trasy včetně mostů a protihlukových stěn. Řidiči by se však měli připravit na dočasná dopravní omezení.', 'Dálnice D35 u Vysokého Mýta projde rozšířením, které zvýší plynulost provozu a bezpečnost. Projekt zahrnuje přidání nových pruhů, modernizaci mostů a zlepšení nájezdů i protihlukových opatření. Stavební práce začnou letos na podzim a potrvají do roku 2027, přičemž řidiči musí počítat s dočasnými omezeními. Po dokončení se očekává výrazné zlepšení dopravní situace v celém regionu.', '<h2 data-start=\"0\" data-end=\"82\"><strong data-start=\"0\" data-end=\"80\">D&aacute;lnice D35 u Vysok&eacute;ho M&yacute;ta se dočk&aacute; roz&scaron;&iacute;řen&iacute;, pr&aacute;ce začnou letos na podzim</strong></h2>\r\n<p data-start=\"84\" data-end=\"428\">D&aacute;lnice D35, kter&aacute; je kl&iacute;čovou dopravn&iacute; tepnou spojuj&iacute;c&iacute; v&yacute;chodn&iacute; a středn&iacute; Čechy, projde v n&aacute;sleduj&iacute;c&iacute;ch měs&iacute;c&iacute;ch z&aacute;sadn&iacute; proměnou. Pl&aacute;novan&eacute; roz&scaron;&iacute;řen&iacute; &uacute;seku u Vysok&eacute;ho M&yacute;ta m&aacute; přin&eacute;st plynulej&scaron;&iacute; dopravu, vy&scaron;&scaron;&iacute; bezpečnost a moderněj&scaron;&iacute; infrastrukturu. Stavebn&iacute; pr&aacute;ce by měly zač&iacute;t již na podzim tohoto roku a budou prob&iacute;hat v několika f&aacute;z&iacute;ch.</p>\r\n<h3 data-start=\"430\" data-end=\"463\"><strong data-start=\"434\" data-end=\"461\">Hlavn&iacute; důvody roz&scaron;&iacute;řen&iacute;</strong></h3>\r\n<p data-start=\"464\" data-end=\"659\">D&aacute;lnice D35 dlouhodobě patř&iacute; k vyt&iacute;žen&yacute;m dopravn&iacute;m tras&aacute;m, přičemž &uacute;sek kolem Vysok&eacute;ho M&yacute;ta často čel&iacute; hust&eacute;mu provozu a kolon&aacute;m. Hlavn&iacute; faktory, kter&eacute; vedly k rozhodnut&iacute; o roz&scaron;&iacute;řen&iacute;, zahrnuj&iacute;:</p>\r\n<ul data-start=\"660\" data-end=\"1002\">\r\n<li data-start=\"660\" data-end=\"775\"><em data-start=\"662\" data-end=\"686\">N&aacute;růst dopravn&iacute; z&aacute;těže</em> &ndash; Počet automobilů i n&aacute;kladn&iacute; dopravy na D35 neust&aacute;le roste, což vede k čast&yacute;m z&aacute;cp&aacute;m.</li>\r\n<li data-start=\"776\" data-end=\"874\"><em data-start=\"778\" data-end=\"801\">Bezpečnostn&iacute; hledisko</em> &ndash; Z&uacute;žen&eacute; j&iacute;zdn&iacute; pruhy a vysok&aacute; intenzita dopravy zvy&scaron;uj&iacute; riziko nehod.</li>\r\n<li data-start=\"875\" data-end=\"1002\"><em data-start=\"877\" data-end=\"900\">Strategick&eacute; propojen&iacute;</em> &ndash; D35 tvoř&iacute; kl&iacute;čovou alternativu k d&aacute;lnici D1, a proto je nutn&eacute; zajistit jej&iacute; dostatečnou kapacitu.</li>\r\n</ul>\r\n<h3 data-start=\"1004\" data-end=\"1036\"><strong data-start=\"1008\" data-end=\"1034\">Jak&eacute; změny n&aacute;s čekaj&iacute;?</strong></h3>\r\n<p data-start=\"1037\" data-end=\"1155\">Projekt roz&scaron;&iacute;řen&iacute; D35 zahrnuje nejen přid&aacute;n&iacute; nov&yacute;ch pruhů, ale i dal&scaron;&iacute; &uacute;pravy vedouc&iacute; ke zv&yacute;&scaron;en&iacute; plynulosti provozu:</p>\r\n<ul data-start=\"1156\" data-end=\"1588\">\r\n<li data-start=\"1156\" data-end=\"1265\"><strong data-start=\"1158\" data-end=\"1199\">Roz&scaron;&iacute;řen&iacute; o jeden pruh v každ&eacute;m směru</strong> &ndash; Celkově se tak roz&scaron;&iacute;ř&iacute; z dvouproud&eacute; na tř&iacute;proudou komunikaci.</li>\r\n<li data-start=\"1266\" data-end=\"1374\"><strong data-start=\"1268\" data-end=\"1303\">Modernizace mostn&iacute;ch konstrukc&iacute;</strong> &ndash; Někter&eacute; mosty na trase budou upraveny nebo zcela nahrazeny nov&yacute;mi.</li>\r\n<li data-start=\"1375\" data-end=\"1487\"><strong data-start=\"1377\" data-end=\"1423\">Zlep&scaron;en&iacute; odpoč&iacute;vadel a připojovac&iacute;ch pruhů</strong> &ndash; Nov&eacute; n&aacute;jezdy a sjezdy umožn&iacute; snadněj&scaron;&iacute; napojen&iacute; na d&aacute;lnici.</li>\r\n<li data-start=\"1488\" data-end=\"1588\"><strong data-start=\"1490\" data-end=\"1515\">Protihlukov&aacute; opatřen&iacute;</strong> &ndash; V okol&iacute; obydlen&yacute;ch oblast&iacute; budou vybudov&aacute;ny nov&eacute; protihlukov&eacute; stěny.</li>\r\n</ul>\r\n<h3 data-start=\"1590\" data-end=\"1634\"><strong data-start=\"1594\" data-end=\"1632\">Průběh v&yacute;stavby a dopravn&iacute; omezen&iacute;</strong></h3>\r\n<p data-start=\"1635\" data-end=\"1692\">Stavebn&iacute; pr&aacute;ce budou prob&iacute;hat ve dvou hlavn&iacute;ch etap&aacute;ch:</p>\r\n<ol data-start=\"1693\" data-end=\"2056\">\r\n<li data-start=\"1693\" data-end=\"1894\">\r\n<p data-start=\"1696\" data-end=\"1740\"><em data-start=\"1696\" data-end=\"1738\">Př&iacute;pravn&aacute; f&aacute;ze (podzim 2025 &ndash; jaro 2026)</em></p>\r\n<ul data-start=\"1744\" data-end=\"1894\">\r\n<li data-start=\"1744\" data-end=\"1809\">Odstraněn&iacute; č&aacute;sti st&aacute;vaj&iacute;c&iacute;ho povrchu a př&iacute;pravn&eacute; zemn&iacute; pr&aacute;ce.</li>\r\n<li data-start=\"1813\" data-end=\"1894\">Budov&aacute;n&iacute; provizorn&iacute;ch obj&iacute;zdn&yacute;ch tras pro minimalizaci dopravn&iacute;ch komplikac&iacute;.</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1896\" data-end=\"2056\">\r\n<p data-start=\"1899\" data-end=\"1949\"><em data-start=\"1899\" data-end=\"1947\">Hlavn&iacute; stavebn&iacute; f&aacute;ze (jaro 2026 &ndash; podzim 2027)</em></p>\r\n<ul data-start=\"1953\" data-end=\"2056\">\r\n<li data-start=\"1953\" data-end=\"2011\">Roz&scaron;&iacute;řen&iacute; st&aacute;vaj&iacute;c&iacute; vozovky a vybudov&aacute;n&iacute; nov&yacute;ch pruhů.</li>\r\n<li data-start=\"2015\" data-end=\"2056\">Modernizace křižovatek a odpoč&iacute;vadel.</li>\r\n</ul>\r\n</li>\r\n</ol>\r\n<p data-start=\"2058\" data-end=\"2280\">Během v&yacute;stavby budou řidiči muset poč&iacute;tat s dočasn&yacute;mi omezen&iacute;mi, sn&iacute;žen&iacute;m rychlosti a př&iacute;padn&yacute;mi uzav&iacute;rkami někter&yacute;ch &uacute;seků. Dopravn&iacute; experti v&scaron;ak uji&scaron;ťuj&iacute;, že pr&aacute;ce budou prob&iacute;hat tak, aby byl provoz co nejm&eacute;ně naru&scaron;en.</p>\r\n<h3 data-start=\"2282\" data-end=\"2319\"><strong data-start=\"2286\" data-end=\"2317\">Př&iacute;nosy pro řidiče i region</strong></h3>\r\n<p data-start=\"2320\" data-end=\"2443\">Po dokončen&iacute; modernizace přinese roz&scaron;&iacute;řen&iacute; d&aacute;lnice D35 řadu v&yacute;hod nejen pro řidiče, ale i pro m&iacute;stn&iacute; obyvatele a podniky:</p>\r\n<ul data-start=\"2444\" data-end=\"2714\">\r\n<li data-start=\"2444\" data-end=\"2510\"><strong data-start=\"2446\" data-end=\"2467\">Plynulej&scaron;&iacute; provoz</strong> &ndash; Sn&iacute;žen&iacute; kolon a krat&scaron;&iacute; doba cestov&aacute;n&iacute;.</li>\r\n<li data-start=\"2511\" data-end=\"2608\"><strong data-start=\"2513\" data-end=\"2533\">Vy&scaron;&scaron;&iacute; bezpečnost</strong> &ndash; Modernizovan&eacute; dopravn&iacute; prvky a &scaron;ir&scaron;&iacute; pruhy pomohou předch&aacute;zet nehod&aacute;m.</li>\r\n<li data-start=\"2609\" data-end=\"2714\"><strong data-start=\"2611\" data-end=\"2633\">Hospod&aacute;řsk&yacute; př&iacute;nos</strong> &ndash; Lep&scaron;&iacute; dopravn&iacute; dostupnost podpoř&iacute; m&iacute;stn&iacute; ekonomiku a přil&aacute;k&aacute; nov&eacute; investory.</li>\r\n</ul>\r\n<p data-start=\"2716\" data-end=\"2967\" data-is-last-node=\"\" data-is-only-node=\"\">Roz&scaron;&iacute;řen&iacute; D35 je dlouho oček&aacute;van&yacute;m krokem, kter&yacute; přinese v&yacute;razn&eacute; zlep&scaron;en&iacute; dopravn&iacute; situace nejen v regionu Vysok&eacute;ho M&yacute;ta, ale i v &scaron;ir&scaron;&iacute;m okol&iacute;. Pokud v&scaron;e půjde podle pl&aacute;nu, řidiči se mohou tě&scaron;it na komfortněj&scaron;&iacute; a bezpečněj&scaron;&iacute; cestov&aacute;n&iacute; již v roce 2027.</p>', '2025-03-11 10:40:35', '2025-03-18 10:08:05', 2, 19, 3, 4);
INSERT INTO `clanky` (`idClanky`, `nadpis`, `upoutavka`, `uryvek`, `obsah`, `created_at`, `updated_at`, `zhlednuti`, `Uzivatele_idUzivatele`, `Kategorie_idKategorie`, `Stav_idStav`) VALUES
(171, 'Královéhradecký kraj podpoří modernizaci nemocnic částkou 500 milionů korun', 'Královéhradecký kraj chystá rozsáhlou modernizaci nemocnic, do které investuje 500 milionů korun. Cílem je zlepšit zdravotní péči, modernizovat vybavení a zvýšit komfort pacientů i personálu. Rekonstrukce začne již letos a dotkne se několika nemocnic v regionu.', 'Královéhradecký kraj investuje 500 milionů korun do modernizace nemocnic, aby zlepšil zdravotní péči, obnovil přístrojové vybavení a zvýšil komfort pacientů i zdravotníků. Rekonstrukce se dotkne několika nemocnic v regionu, včetně Hradce Králové, Náchoda a Jičína. Projekt bude financován z krajského rozpočtu, evropských fondů a příspěvků měst a obcí. Práce začnou na podzim a dokončení se plánuje do roku 2027.', '<h2 data-start=\"0\" data-end=\"81\"><strong data-start=\"0\" data-end=\"79\">Kr&aacute;lov&eacute;hradeck&yacute; kraj podpoř&iacute; modernizaci nemocnic č&aacute;stkou 500 milionů korun</strong></h2>\r\n<p data-start=\"83\" data-end=\"343\">Kr&aacute;lov&eacute;hradeck&yacute; kraj ozn&aacute;mil rozs&aacute;hl&yacute; pl&aacute;n na modernizaci sv&yacute;ch nemocnic, kter&yacute; bude podpořen investic&iacute; ve v&yacute;&scaron;i 500 milionů korun. C&iacute;lem t&eacute;to iniciativy je zlep&scaron;en&iacute; zdravotn&iacute; p&eacute;če, modernizace vybaven&iacute; a zv&yacute;&scaron;en&iacute; komfortu pro pacienty i zdravotnick&yacute; person&aacute;l.</p>\r\n<h3 data-start=\"345\" data-end=\"380\"><strong data-start=\"349\" data-end=\"378\">Rozsah a c&iacute;le modernizace</strong></h3>\r\n<p data-start=\"382\" data-end=\"437\">Modernizace se bude t&yacute;kat několika kl&iacute;čov&yacute;ch oblast&iacute;:</p>\r\n<ul data-start=\"439\" data-end=\"991\">\r\n<li data-start=\"439\" data-end=\"549\"><strong data-start=\"441\" data-end=\"474\">Obnova př&iacute;strojov&eacute;ho vybaven&iacute;</strong> &ndash; nemocnice z&iacute;skaj&iacute; nejmoderněj&scaron;&iacute; diagnostick&eacute; a terapeutick&eacute; př&iacute;stroje.</li>\r\n<li data-start=\"550\" data-end=\"695\"><strong data-start=\"552\" data-end=\"574\">Rekonstrukce budov</strong> &ndash; v někter&yacute;ch zař&iacute;zen&iacute;ch proběhnou rozs&aacute;hl&eacute; stavebn&iacute; &uacute;pravy, kter&eacute; zv&yacute;&scaron;&iacute; kapacitu lůžek a zlep&scaron;&iacute; hygienick&eacute; standardy.</li>\r\n<li data-start=\"696\" data-end=\"860\"><strong data-start=\"698\" data-end=\"732\">Zv&yacute;&scaron;en&iacute; energetick&eacute; efektivity</strong> &ndash; souč&aacute;st&iacute; modernizace bude zateplen&iacute; budov, v&yacute;měna oken a instalace ekologick&yacute;ch technologi&iacute; pro sn&iacute;žen&iacute; provozn&iacute;ch n&aacute;kladů.</li>\r\n<li data-start=\"861\" data-end=\"991\"><strong data-start=\"863\" data-end=\"896\">Zlep&scaron;en&iacute; pracovn&iacute;ho prostřed&iacute;</strong> &ndash; modern&iacute; vybaven&iacute; pro zdravotn&iacute;ky, nov&eacute; operačn&iacute; s&aacute;ly a komfortněj&scaron;&iacute; oddělen&iacute; pro pacienty.</li>\r\n</ul>\r\n<h3 data-start=\"993\" data-end=\"1039\"><strong data-start=\"997\" data-end=\"1037\">Kter&eacute; nemocnice budou modernizov&aacute;ny?</strong></h3>\r\n<p data-start=\"1041\" data-end=\"1089\">Podpora se bude t&yacute;kat zejm&eacute;na těchto nemocnic:</p>\r\n<ol data-start=\"1091\" data-end=\"1645\">\r\n<li data-start=\"1091\" data-end=\"1207\"><strong data-start=\"1094\" data-end=\"1131\">Fakultn&iacute; nemocnice Hradec Kr&aacute;lov&eacute;</strong> &ndash; pl&aacute;nuje se modernizace chirurgick&yacute;ch oddělen&iacute; a roz&scaron;&iacute;řen&iacute; kapacity JIP.</li>\r\n<li data-start=\"1208\" data-end=\"1310\"><strong data-start=\"1211\" data-end=\"1231\">Nemocnice N&aacute;chod</strong> &ndash; zde dojde k rekonstrukci intern&iacute;ho pavilonu a vylep&scaron;en&iacute; urgentn&iacute;ho př&iacute;jmu.</li>\r\n<li data-start=\"1311\" data-end=\"1425\"><strong data-start=\"1314\" data-end=\"1342\">Oblastn&iacute; nemocnice Jič&iacute;n</strong> &ndash; z&iacute;sk&aacute; nov&eacute; diagnostick&eacute; př&iacute;stroje a roz&scaron;&iacute;řen&eacute; prostory pro rehabilitačn&iacute; p&eacute;či.</li>\r\n<li data-start=\"1426\" data-end=\"1522\"><strong data-start=\"1429\" data-end=\"1462\">Nemocnice Rychnov nad Kněžnou</strong> &ndash; roz&scaron;&iacute;řen&iacute; oddělen&iacute; ARO a modernizace dětsk&eacute;ho oddělen&iacute;.</li>\r\n<li data-start=\"1523\" data-end=\"1645\"><strong data-start=\"1526\" data-end=\"1557\">Men&scaron;&iacute; zdravotnick&aacute; zař&iacute;zen&iacute;</strong> &ndash; č&aacute;st prostředků bude vyčleněna na modernizaci ambulanc&iacute; a poliklinik v cel&eacute;m kraji.</li>\r\n</ol>\r\n<h3 data-start=\"1647\" data-end=\"1677\"><strong data-start=\"1651\" data-end=\"1675\">Financov&aacute;n&iacute; projektu</strong></h3>\r\n<p data-start=\"1679\" data-end=\"1740\">Celkov&aacute; č&aacute;stka 500 milionů korun poch&aacute;z&iacute; z několika zdrojů:</p>\r\n<ul data-start=\"1742\" data-end=\"2037\">\r\n<li data-start=\"1742\" data-end=\"1835\"><strong data-start=\"1744\" data-end=\"1764\">Krajsk&yacute; rozpočet</strong> &ndash; Kr&aacute;lov&eacute;hradeck&yacute; kraj poskytne č&aacute;st financ&iacute; z vlastn&iacute;ch prostředků.</li>\r\n<li data-start=\"1836\" data-end=\"1925\"><strong data-start=\"1838\" data-end=\"1867\">Dotace z evropsk&yacute;ch fondů</strong> &ndash; projekt využije možnosti spolufinancov&aacute;n&iacute; z fondů EU.</li>\r\n<li data-start=\"1926\" data-end=\"2037\"><strong data-start=\"1928\" data-end=\"1953\">Př&iacute;spěvky měst a obc&iacute;</strong> &ndash; někter&aacute; města se zapoj&iacute; do financov&aacute;n&iacute; modernizace nemocnic ve sv&yacute;ch regionech.</li>\r\n</ul>\r\n<h3 data-start=\"2039\" data-end=\"2078\"><strong data-start=\"2043\" data-end=\"2076\">Reakce odborn&iacute;ků a veřejnosti</strong></h3>\r\n<p data-start=\"2080\" data-end=\"2353\">Zdravotn&iacute;ci i pacienti modernizaci v&iacute;taj&iacute;. Podle prim&aacute;ře hradeck&eacute; nemocnice je obnova vybaven&iacute; kl&iacute;čov&aacute; pro zaji&scaron;těn&iacute; &scaron;pičkov&eacute; zdravotn&iacute; p&eacute;če. Obyvatel&eacute; kraje oceňuj&iacute; investici do zdravotnictv&iacute;, i když někteř&iacute; vyjadřuj&iacute; obavy ohledně př&iacute;padn&yacute;ch dopadů na krajsk&yacute; rozpočet.</p>\r\n<h3 data-start=\"2355\" data-end=\"2387\"><strong data-start=\"2359\" data-end=\"2385\">Kdy modernizace začne?</strong></h3>\r\n<p data-start=\"2389\" data-end=\"2594\">Prvn&iacute; etapy modernizace by měly zač&iacute;t na podzim tohoto roku. Rekonstrukce budov budou prob&iacute;hat postupně tak, aby nebyla ohrožena běžn&aacute; zdravotn&iacute; p&eacute;če. Cel&yacute; projekt by měl b&yacute;t dokončen do konce roku 2027.</p>\r\n<h3 data-start=\"2596\" data-end=\"2655\"><strong data-start=\"2600\" data-end=\"2653\">Budoucnost zdravotnictv&iacute; v Kr&aacute;lov&eacute;hradeck&eacute;m kraji</strong></h3>\r\n<p data-start=\"2657\" data-end=\"2870\" data-is-last-node=\"\" data-is-only-node=\"\">D&iacute;ky t&eacute;to investici se oček&aacute;v&aacute; v&yacute;razn&eacute; zlep&scaron;en&iacute; &uacute;rovně zdravotn&iacute; p&eacute;če v cel&eacute;m regionu. Modernizace nemocnic pomůže nejen pacientům, ale tak&eacute; přil&aacute;k&aacute; nov&eacute; odborn&iacute;ky a zv&yacute;&scaron;&iacute; prestiž m&iacute;stn&iacute;ch zdravotnick&yacute;ch zař&iacute;zen&iacute;.</p>', '2025-03-11 10:45:35', '2025-03-25 10:15:13', 2, 19, 3, 4),
(172, 'Trutnovské náměstí projde rekonstrukcí, město plánuje nové zelené plochy', 'Trutnovské náměstí čeká rozsáhlá proměna, která přinese více zeleně a modernější veřejný prostor. Město klade důraz na ekologická opatření i pohodlí obyvatel. Jaké změny se plánují a kdy začne rekonstrukce?', 'Trutnovské náměstí čeká rozsáhlá rekonstrukce, která přinese více zeleně, moderní městský mobiliář a lepší pěší zóny. Projekt klade důraz na ekologická opatření, jako je zavlažování dešťovou vodou a propustné dlažby. Stavební práce začnou na podzim 2025 a dokončení se plánuje na konec roku 2026. Obyvatelé rekonstrukci vítají, i když se obávají dopravních omezení a vlivu na místní obchody. Město slibuje opatření ke zmírnění dopadů a podporu podnikatelů.', '<h2 data-start=\"0\" data-end=\"78\"><strong data-start=\"0\" data-end=\"76\">Trutnovsk&eacute; n&aacute;měst&iacute; projde rekonstrukc&iacute;, město pl&aacute;nuje nov&eacute; zelen&eacute; plochy</strong></h2>\r\n<p data-start=\"80\" data-end=\"311\"><em data-start=\"80\" data-end=\"309\">Trutnov se chyst&aacute; na v&yacute;znamnou proměnu sv&eacute;ho centr&aacute;ln&iacute;ho n&aacute;měst&iacute;. Radnice ozn&aacute;mila ambici&oacute;zn&iacute; pl&aacute;n na jeho rekonstrukci, kter&aacute; přinese moderněj&scaron;&iacute; vzhled, zlep&scaron;en&iacute; infrastruktury a nov&eacute; zelen&eacute; plochy pro obyvatele i n&aacute;v&scaron;těvn&iacute;ky.</em></p>\r\n<h3 data-start=\"313\" data-end=\"338\">Nov&aacute; podoba n&aacute;měst&iacute;</h3>\r\n<p data-start=\"339\" data-end=\"530\">Městsk&eacute; zastupitelstvo schv&aacute;lilo projekt, kter&yacute; m&aacute; za c&iacute;l <strong data-start=\"397\" data-end=\"439\">zv&yacute;&scaron;it atraktivitu historick&eacute;ho centra</strong> a z&aacute;roveň poskytnout v&iacute;ce prostoru pro tr&aacute;ven&iacute; voln&eacute;ho času. Souč&aacute;st&iacute; rekonstrukce bude:</p>\r\n<ul data-start=\"531\" data-end=\"738\">\r\n<li data-start=\"531\" data-end=\"563\">V&yacute;sadba nov&yacute;ch stromů a keřů</li>\r\n<li data-start=\"564\" data-end=\"614\">Roz&scaron;&iacute;řen&iacute; travnat&yacute;ch ploch a odpočinkov&yacute;ch z&oacute;n</li>\r\n<li data-start=\"615\" data-end=\"685\">Instalace modern&iacute;ho městsk&eacute;ho mobili&aacute;ře, jako jsou lavičky a p&iacute;tka</li>\r\n<li data-start=\"686\" data-end=\"738\">Oprava dlažby a lep&scaron;&iacute; propojen&iacute; s pě&scaron;&iacute;mi trasami</li>\r\n</ul>\r\n<p data-start=\"740\" data-end=\"930\">Podle architekta projektu <strong data-start=\"766\" data-end=\"786\">Tom&aacute;&scaron;e Novotn&eacute;ho</strong> je c&iacute;lem vytvořit <strong data-start=\"805\" data-end=\"831\">př&iacute;větivěj&scaron;&iacute; prostřed&iacute;</strong>, kter&eacute; bude sloužit nejen jako dopravn&iacute; uzel, ale tak&eacute; jako <strong data-start=\"892\" data-end=\"908\">klidov&aacute; z&oacute;na</strong> pro setk&aacute;v&aacute;n&iacute; lid&iacute;.</p>\r\n<h3 data-start=\"932\" data-end=\"970\">Zelen&eacute; plochy jako kl&iacute;čov&yacute; prvek</h3>\r\n<p data-start=\"971\" data-end=\"1159\">Jedn&iacute;m z hlavn&iacute;ch bodů rekonstrukce je důraz na <strong data-start=\"1019\" data-end=\"1035\">zelen&eacute; prvky</strong> a udržiteln&yacute; rozvoj městsk&eacute;ho prostoru. Trutnov chce j&iacute;t cestou <strong data-start=\"1100\" data-end=\"1143\">ekologicky &scaron;etrn&eacute;ho městsk&eacute;ho pl&aacute;nov&aacute;n&iacute;</strong>, což znamen&aacute;:</p>\r\n<ul data-start=\"1160\" data-end=\"1348\">\r\n<li data-start=\"1160\" data-end=\"1205\">Použit&iacute; de&scaron;ťov&eacute; vody k zavlažov&aacute;n&iacute; zeleně</li>\r\n<li data-start=\"1206\" data-end=\"1261\">Instalaci propustn&eacute; dlažby pro lep&scaron;&iacute; vsakov&aacute;n&iacute; vody</li>\r\n<li data-start=\"1262\" data-end=\"1348\">V&yacute;sadbu stromů, kter&eacute; budou sloužit jako přirozen&yacute; st&iacute;n v hork&yacute;ch letn&iacute;ch měs&iacute;c&iacute;ch</li>\r\n</ul>\r\n<p data-start=\"1350\" data-end=\"1481\">Podle m&iacute;stostarosty <strong data-start=\"1370\" data-end=\"1386\">Jana Dvoř&aacute;ka</strong> je prioritou &bdquo;zajistit <strong data-start=\"1410\" data-end=\"1430\">lep&scaron;&iacute; mikroklima</strong>, aby bylo centrum města př&iacute;jemn&eacute; i během veder&ldquo;.</p>\r\n<h3 data-start=\"1483\" data-end=\"1515\">Dopad na dopravu a obchody</h3>\r\n<p data-start=\"1516\" data-end=\"1754\">Rekonstrukce si vyž&aacute;d&aacute; dočasn&aacute; dopravn&iacute; omezen&iacute;. Město ale slibuje, že <strong data-start=\"1587\" data-end=\"1640\">př&iacute;stup k obchodům a restaurac&iacute;m zůstane zachov&aacute;n</strong>. Majitel&eacute; provozoven se ob&aacute;vali poklesu n&aacute;v&scaron;těvnosti, ale radnice pl&aacute;nuje s&eacute;rii podpůrn&yacute;ch opatřen&iacute;, jako jsou:</p>\r\n<ul data-start=\"1755\" data-end=\"1892\">\r\n<li data-start=\"1755\" data-end=\"1798\">Dočasn&aacute; parkovac&iacute; m&iacute;sta v bl&iacute;zk&eacute;m okol&iacute;</li>\r\n<li data-start=\"1799\" data-end=\"1840\">Zlep&scaron;en&iacute; navigace pro pě&scaron;&iacute; i cyklisty</li>\r\n<li data-start=\"1841\" data-end=\"1892\">Možnost využit&iacute; městsk&eacute; dopravy zdarma v centru</li>\r\n</ul>\r\n<p data-start=\"1894\" data-end=\"2008\">Podle obchodn&iacute;ků <strong data-start=\"1911\" data-end=\"1961\">je kl&iacute;čov&eacute;, aby pr&aacute;ce prob&iacute;haly co nejrychleji</strong> a neomezily podnik&aacute;n&iacute; v předv&aacute;nočn&iacute;m obdob&iacute;.</p>\r\n<h3 data-start=\"2010\" data-end=\"2041\">Harmonogram a financov&aacute;n&iacute;</h3>\r\n<p data-start=\"2042\" data-end=\"2081\">Projekt je rozdělen do několika f&aacute;z&iacute;:</p>\r\n<ol data-start=\"2082\" data-end=\"2250\">\r\n<li data-start=\"2082\" data-end=\"2130\"><strong data-start=\"2085\" data-end=\"2100\">Podzim 2025</strong> &ndash; zah&aacute;jen&iacute; stavebn&iacute;ch prac&iacute;</li>\r\n<li data-start=\"2131\" data-end=\"2198\"><strong data-start=\"2134\" data-end=\"2147\">Jaro 2026</strong> &ndash; dokončen&iacute; prvn&iacute; etapy a otevřen&iacute; č&aacute;sti n&aacute;měst&iacute;</li>\r\n<li data-start=\"2199\" data-end=\"2250\"><strong data-start=\"2202\" data-end=\"2217\">Podzim 2026</strong> &ndash; kompletn&iacute; dokončen&iacute; projektu</li>\r\n</ol>\r\n<p data-start=\"2252\" data-end=\"2424\">N&aacute;klady na rekonstrukci se odhaduj&iacute; na <strong data-start=\"2291\" data-end=\"2312\">120 milionů korun</strong>, přičemž <strong data-start=\"2322\" data-end=\"2341\">č&aacute;st prostředků</strong> by měla poch&aacute;zet z <strong data-start=\"2361\" data-end=\"2381\">evropsk&yacute;ch fondů</strong> a dotac&iacute; Ministerstva pro m&iacute;stn&iacute; rozvoj.</p>\r\n<h3 data-start=\"2426\" data-end=\"2449\">Reakce veřejnosti</h3>\r\n<p data-start=\"2450\" data-end=\"2644\">M&iacute;stn&iacute; obyvatel&eacute; projekt v&iacute;taj&iacute;, ale maj&iacute; i sv&eacute; obavy. &bdquo;L&iacute;b&iacute; se mi, že se přid&aacute; v&iacute;ce zeleně, ale boj&iacute;m se, jak dlouho budou trvat stavebn&iacute; pr&aacute;ce,&ldquo; ř&iacute;k&aacute; <strong data-start=\"2602\" data-end=\"2619\">pan&iacute; Nov&aacute;kov&aacute;</strong>, kter&aacute; v centru bydl&iacute;.</p>\r\n<p data-start=\"2646\" data-end=\"2844\">Naopak <strong data-start=\"2653\" data-end=\"2672\">mlad&scaron;&iacute; generace</strong> si slibuje, že rekonstrukce přinese modern&iacute; prvky a lep&scaron;&iacute; využit&iacute; prostoru. &bdquo;Konečně bude v centru v&iacute;ce m&iacute;st k posezen&iacute; a odpočinku,&ldquo; komentuje student <strong data-start=\"2825\" data-end=\"2841\">Petr Havelka</strong>.</p>\r\n<h3 data-start=\"2846\" data-end=\"2857\">Z&aacute;věr</h3>\r\n<p data-start=\"2858\" data-end=\"3217\" data-is-last-node=\"\" data-is-only-node=\"\">Rekonstrukce trutnovsk&eacute;ho n&aacute;měst&iacute; je <strong data-start=\"2895\" data-end=\"2945\">velk&yacute;m krokem k modernizaci městsk&eacute;ho prostoru</strong>. Projekt přinese <strong data-start=\"2963\" data-end=\"3024\">v&iacute;ce zeleně, lep&scaron;&iacute; infrastrukturu a př&iacute;jemněj&scaron;&iacute; prostřed&iacute;</strong> pro obyvatele i turisty. Pokud v&scaron;e půjde podle pl&aacute;nu, do dvou let se Trutnov může pochlubit <strong data-start=\"3117\" data-end=\"3147\">nov&yacute;m, atraktivn&iacute;m centrem</strong>, kter&eacute; bude sloužit jako <strong data-start=\"3173\" data-end=\"3216\">př&iacute;jemn&eacute; m&iacute;sto pro setk&aacute;v&aacute;n&iacute; a relaxaci</strong>.</p>', '2025-03-11 10:50:10', '2025-03-12 15:43:34', 0, 19, 3, 4),
(173, 'Nový logistický park u Pardubic slibuje stovky pracovních míst', 'U Pardubic vznikne nový logistický park, který přinese stovky pracovních míst a podpoří rozvoj regionu. Díky moderním technologiím a ekologickým opatřením nabídne udržitelnou infrastrukturu pro firmy i zaměstnance. Jaké změny projekt přinese a kdy začne výstavba?', 'Nový logistický park u Pardubic nabídne moderní skladovací a distribuční prostory s cílem podpořit ekonomiku regionu. Díky strategické poloze u dálnice D35 přiláká investory a vytvoří až 500 nových pracovních míst. Projekt klade důraz na ekologická opatření, jako jsou solární panely a zelené střechy, a přispěje ke zlepšení dopravní infrastruktury i zaměstnanosti v kraji.', '<h2 data-start=\"0\" data-end=\"68\"><strong data-start=\"0\" data-end=\"66\">Nov&yacute; logistick&yacute; park u Pardubic slibuje stovky pracovn&iacute;ch m&iacute;st</strong></h2>\r\n<p data-start=\"70\" data-end=\"376\">V&yacute;stavba nov&eacute;ho logistick&eacute;ho parku v bl&iacute;zkosti Pardubic se st&aacute;v&aacute; realitou. Projekt, kter&yacute; si klade za c&iacute;l podpořit ekonomiku regionu, nab&iacute;dne modern&iacute; skladovac&iacute; a distribučn&iacute; prostory pro firmy z různ&yacute;ch odvětv&iacute;. Kromě zlep&scaron;en&iacute; infrastruktury přinese tak&eacute; nov&eacute; pracovn&iacute; př&iacute;ležitosti pro m&iacute;stn&iacute; obyvatele.</p>\r\n<h3 data-start=\"378\" data-end=\"420\">Strategick&aacute; poloha a v&yacute;znam projektu</h3>\r\n<p data-start=\"422\" data-end=\"758\">Logistick&yacute; park bude um&iacute;stěn pobl&iacute;ž d&aacute;lnice D35, což zajist&iacute; snadn&yacute; př&iacute;stup k hlavn&iacute;m dopravn&iacute;m tahům. D&iacute;ky t&eacute;to poloze se oček&aacute;v&aacute;, že do oblasti přil&aacute;k&aacute; nejen česk&eacute;, ale i zahraničn&iacute; investory. Pardubick&yacute; kraj patř&iacute; k regionům s rostouc&iacute;m průmyslov&yacute;m potenci&aacute;lem a nov&yacute; park by měl pos&iacute;lit jeho roli v oblasti logistiky a distribuce.</p>\r\n<p data-start=\"760\" data-end=\"1084\"><em data-start=\"760\" data-end=\"897\">Podle představitelů města a kraje jde o strategick&yacute; projekt, kter&yacute; pomůže vytvořit nov&aacute; pracovn&iacute; m&iacute;sta a z&aacute;roveň zlep&scaron;&iacute; infrastrukturu.</em> Z&aacute;stupci stavebn&iacute; firmy zdůrazňuj&iacute;, že cel&yacute; projekt je pl&aacute;nov&aacute;n s ohledem na ekologick&eacute; aspekty, včetně použit&iacute; modern&iacute;ch technologi&iacute; pro sn&iacute;žen&iacute; emis&iacute; a efektivn&iacute; nakl&aacute;d&aacute;n&iacute; s energi&iacute;.</p>\r\n<h3 data-start=\"1086\" data-end=\"1131\">Nov&aacute; pracovn&iacute; m&iacute;sta a ekonomick&yacute; př&iacute;nos</h3>\r\n<p data-start=\"1133\" data-end=\"1318\">V&yacute;stavba are&aacute;lu by měla b&yacute;t dokončena během př&iacute;&scaron;t&iacute;ch dvou let, přičemž prvn&iacute; firmy by se mohly zač&iacute;t stěhovat již v průběhu př&iacute;&scaron;t&iacute;ho roku. Oček&aacute;v&aacute; se, že nov&yacute; logistick&yacute; park vytvoř&iacute;:</p>\r\n<ul data-start=\"1320\" data-end=\"1611\">\r\n<li data-start=\"1320\" data-end=\"1378\"><strong data-start=\"1322\" data-end=\"1355\">Až 500 nov&yacute;ch pracovn&iacute;ch m&iacute;st</strong> pro m&iacute;stn&iacute; obyvatele</li>\r\n<li data-start=\"1379\" data-end=\"1490\"><strong data-start=\"1381\" data-end=\"1419\">Podporu mal&yacute;ch a středn&iacute;ch podniků</strong>, kter&eacute; budou moci spolupracovat s velk&yacute;mi distribučn&iacute;mi společnostmi</li>\r\n<li data-start=\"1491\" data-end=\"1611\"><strong data-start=\"1493\" data-end=\"1544\">Nov&eacute; obchodn&iacute; př&iacute;ležitosti pro region&aacute;ln&iacute; firmy</strong>, např&iacute;klad v oblasti dopravy, servisu nebo &uacute;držby infrastruktury</li>\r\n</ul>\r\n<p data-start=\"1613\" data-end=\"1873\">Podle odborn&iacute;ků z oblasti ekonomiky podobn&eacute; projekty v&yacute;razně přisp&iacute;vaj&iacute; k růstu regionů. <em data-start=\"1702\" data-end=\"1821\">&bdquo;Logistick&aacute; centra hraj&iacute; kl&iacute;čovou roli ve zvy&scaron;ov&aacute;n&iacute; zaměstnanosti a z&aacute;roveň podporuj&iacute; rozvoj dodavatelsk&yacute;ch řetězců,&ldquo;</em> ř&iacute;k&aacute; ekonom Jan Nov&aacute;k z univerzity v Pardubic&iacute;ch.</p>\r\n<h3 data-start=\"1875\" data-end=\"1915\">Udržitelnost a modern&iacute; technologie</h3>\r\n<p data-start=\"1917\" data-end=\"2005\">Jedn&iacute;m z hlavn&iacute;ch c&iacute;lů projektu je sn&iacute;žen&iacute; ekologick&eacute; stopy. Proto bude are&aacute;l vybaven:</p>\r\n<ul data-start=\"2007\" data-end=\"2256\">\r\n<li data-start=\"2007\" data-end=\"2073\"><strong data-start=\"2009\" data-end=\"2029\">Sol&aacute;rn&iacute;mi panely</strong> pro č&aacute;stečn&eacute; pokryt&iacute; energetick&yacute;ch potřeb</li>\r\n<li data-start=\"2074\" data-end=\"2147\"><strong data-start=\"2076\" data-end=\"2125\">Efektivn&iacute;m odvodněn&iacute;m a využit&iacute;m de&scaron;ťov&eacute; vody</strong> pro provoz a &uacute;držbu</li>\r\n<li data-start=\"2148\" data-end=\"2256\"><strong data-start=\"2150\" data-end=\"2183\">Zelen&yacute;mi střechami a plochami</strong>, kter&eacute; přispěj&iacute; ke snižov&aacute;n&iacute; pra&scaron;nosti a zlep&scaron;en&iacute; mikroklimatu v okol&iacute;</li>\r\n</ul>\r\n<p data-start=\"2258\" data-end=\"2397\">Tento př&iacute;stup odpov&iacute;d&aacute; modern&iacute;m trendům v oblasti logistiky, kde se st&aacute;le v&iacute;ce firem snaž&iacute; minimalizovat svůj dopad na životn&iacute; prostřed&iacute;.</p>\r\n<h3 data-start=\"2399\" data-end=\"2437\">Pl&aacute;n v&yacute;stavby a budouc&iacute; vyhl&iacute;dky</h3>\r\n<p data-start=\"2439\" data-end=\"2696\">Prvn&iacute; f&aacute;ze projektu zahrnuje vybudov&aacute;n&iacute; hlavn&iacute;ch skladov&yacute;ch hal, administrativn&iacute;ch budov a dopravn&iacute; infrastruktury. V dal&scaron;&iacute;ch etap&aacute;ch se pl&aacute;nuje roz&scaron;&iacute;řen&iacute; are&aacute;lu a možn&aacute; i připojen&iacute; železničn&iacute; vlečky, kter&aacute; by mohla d&aacute;le zlep&scaron;it logistick&eacute; možnosti parku.</p>\r\n<p data-start=\"2698\" data-end=\"2997\">Pardubick&yacute; kraj si od projektu slibuje nejen ekonomick&yacute; př&iacute;nos, ale tak&eacute; zlep&scaron;en&iacute; dopravn&iacute; situace. <em data-start=\"2798\" data-end=\"2958\">&bdquo;D&iacute;ky strategick&eacute;mu um&iacute;stěn&iacute; parku můžeme sn&iacute;žit z&aacute;těž kamionov&eacute; dopravy v centru města, což přispěje ke zlep&scaron;en&iacute; kvality ovzdu&scaron;&iacute; a bezpečnosti na silnic&iacute;ch,&ldquo;</em> uvedl n&aacute;městek hejtmana pro dopravu.</p>\r\n<h3 data-start=\"2999\" data-end=\"3010\">Z&aacute;věr</h3>\r\n<p data-start=\"3012\" data-end=\"3325\" data-is-last-node=\"\" data-is-only-node=\"\">Nov&yacute; logistick&yacute; park u Pardubic je ambici&oacute;zn&iacute;m projektem, kter&yacute; m&aacute; potenci&aacute;l přin&eacute;st v&yacute;znamn&eacute; změny nejen v oblasti zaměstnanosti, ale i v celkov&eacute;m ekonomick&eacute;m rozvoji regionu. Modern&iacute; př&iacute;stup k v&yacute;stavbě a důraz na ekologii ukazuj&iacute;, že logistika budoucnosti se zaměřuje nejen na efektivitu, ale i na udržitelnost.</p>', '2025-03-11 10:55:18', '2025-03-16 15:21:03', 3, 19, 2, 4),
(174, 'Rodinné firmy ve východních Čechách bojují s nedostatkem kvalifikovaných pracovníků', 'Rodinné firmy ve východních Čechách čelí vážnému problému – chybí jim kvalifikovaní pracovníci. Řemeslné a technické obory se potýkají s nezájmem mladé generace, což nutí podniky hledat nové cesty, jak situaci řešit. Jaké strategie volí a jaké mají vyhlídky do budoucna?', 'Rodinné firmy ve východních Čechách se potýkají s nedostatkem kvalifikovaných pracovníků, zejména v technických a řemeslných profesích. Hlavní příčinou je stárnutí pracovní síly, odliv zaměstnanců do zahraničí a nízký zájem mladé generace o odborné vzdělání. Firmy se snaží situaci řešit vyššími mzdami, spoluprací se školami, automatizací výroby a náborem zahraničních pracovníků. Přesto zůstává otázkou, zda se jim podaří dlouhodobě udržet konkurenceschopnost a zachovat rodinnou tradici.', '<h2 data-start=\"0\" data-end=\"89\">Rodinn&eacute; firmy ve v&yacute;chodn&iacute;ch Čech&aacute;ch bojuj&iacute; s nedostatkem kvalifikovan&yacute;ch pracovn&iacute;ků</h2>\r\n<p data-start=\"91\" data-end=\"360\">Rodinn&eacute; podniky tvoř&iacute; p&aacute;teř česk&eacute; ekonomiky, a to plat&iacute; i pro v&yacute;chodn&iacute; Čechy. V posledn&iacute;ch letech v&scaron;ak čel&iacute; z&aacute;sadn&iacute;mu probl&eacute;mu &ndash; nedostatku kvalifikovan&yacute;ch pracovn&iacute;ků. Tento trend se projevuje v řadě odvětv&iacute;, od stroj&iacute;renstv&iacute; přes stavebnictv&iacute; až po tradičn&iacute; řemesla.</p>\r\n<h4 data-start=\"362\" data-end=\"402\"><strong data-start=\"367\" data-end=\"400\">Kritick&yacute; nedostatek odborn&iacute;ků</strong></h4>\r\n<p data-start=\"404\" data-end=\"580\">Podle podnikatelů z regionu je st&aacute;le těž&scaron;&iacute; naj&iacute;t zku&scaron;en&eacute; zaměstnance, kteř&iacute; by ovl&aacute;dali specifick&eacute; dovednosti potřebn&eacute; pro v&yacute;robu a služby. Mezi nejohroženěj&scaron;&iacute; profese patř&iacute;:</p>\r\n<ul data-start=\"582\" data-end=\"1176\">\r\n<li data-start=\"582\" data-end=\"734\"><strong data-start=\"584\" data-end=\"607\">Z&aacute;mečn&iacute;ci a sv&aacute;řeči</strong> &ndash; Řemesln&eacute; dovednosti jsou st&aacute;le m&eacute;ně atraktivn&iacute; pro mladou generaci, což způsobuje pokles počtu kvalifikovan&yacute;ch pracovn&iacute;ků.</li>\r\n<li data-start=\"735\" data-end=\"875\"><strong data-start=\"737\" data-end=\"758\">Truhl&aacute;ři a tesaři</strong> &ndash; Dřevozpracuj&iacute;c&iacute; průmysl, dlouhodobě siln&yacute; v Kr&aacute;lov&eacute;hradeck&eacute;m i Pardubick&eacute;m kraji, se pot&yacute;k&aacute; s &uacute;bytkem odborn&iacute;ků.</li>\r\n<li data-start=\"876\" data-end=\"1028\"><strong data-start=\"878\" data-end=\"901\">Technici a inžen&yacute;ři</strong> &ndash; Růst průmyslu a modernizace v&yacute;roby vyžaduj&iacute; vy&scaron;&scaron;&iacute; počet kvalifikovan&yacute;ch pracovn&iacute;ků v oblasti automatizace a stroj&iacute;renstv&iacute;.</li>\r\n<li data-start=\"1029\" data-end=\"1176\"><strong data-start=\"1031\" data-end=\"1049\">IT specialist&eacute;</strong> &ndash; Digitalizace nut&iacute; rodinn&eacute; firmy investovat do technologi&iacute;, ale sehnat schopn&eacute; program&aacute;tory a IT administr&aacute;tory je obt&iacute;žn&eacute;.</li>\r\n</ul>\r\n<h4 data-start=\"1178\" data-end=\"1218\"><strong data-start=\"1183\" data-end=\"1216\">Př&iacute;činy nedostatku pracovn&iacute;ků</strong></h4>\r\n<p data-start=\"1220\" data-end=\"1265\">Podle analytiků je hlavn&iacute;ch důvodů několik:</p>\r\n<ol data-start=\"1267\" data-end=\"1770\">\r\n<li data-start=\"1267\" data-end=\"1375\"><strong data-start=\"1270\" data-end=\"1296\">St&aacute;rnut&iacute; pracovn&iacute; s&iacute;ly</strong> &ndash; Star&scaron;&iacute; generace odch&aacute;z&iacute; do důchodu a mlad&iacute; nemaj&iacute; o někter&eacute; profese z&aacute;jem.</li>\r\n<li data-start=\"1376\" data-end=\"1505\"><strong data-start=\"1379\" data-end=\"1412\">Nedostatečn&eacute; odborn&eacute; vzděl&aacute;n&iacute;</strong> &ndash; Mnoho učili&scaron;ť a odborn&yacute;ch &scaron;kol se pot&yacute;k&aacute; s n&iacute;zk&yacute;m počtem studentů v technick&yacute;ch oborech.</li>\r\n<li data-start=\"1506\" data-end=\"1625\"><strong data-start=\"1509\" data-end=\"1542\">Odliv pracovn&iacute;ků do zahranič&iacute;</strong> &ndash; Lep&scaron;&iacute; finančn&iacute; podm&iacute;nky v Německu a Rakousku l&aacute;kaj&iacute; česk&eacute; odborn&iacute;ky k odchodu.</li>\r\n<li data-start=\"1626\" data-end=\"1770\"><strong data-start=\"1629\" data-end=\"1666\">Rostouc&iacute; konkurence velk&yacute;ch firem</strong> &ndash; Nadn&aacute;rodn&iacute; společnosti nab&iacute;zej&iacute; vy&scaron;&scaron;&iacute; mzdy a lep&scaron;&iacute; benefity, což rodinn&eacute; podniky těžko dorovn&aacute;vaj&iacute;.</li>\r\n</ol>\r\n<h4 data-start=\"1772\" data-end=\"1801\"><strong data-start=\"1777\" data-end=\"1799\">Jak firmy reaguj&iacute;?</strong></h4>\r\n<p data-start=\"1803\" data-end=\"1932\">Aby rodinn&eacute; podniky situaci zvl&aacute;dly, hledaj&iacute; nov&eacute; způsoby, jak přil&aacute;kat a udržet zaměstnance. Mezi nejčastěj&scaron;&iacute; strategie patř&iacute;:</p>\r\n<ul data-start=\"1934\" data-end=\"2504\">\r\n<li data-start=\"1934\" data-end=\"2062\"><strong data-start=\"1936\" data-end=\"1963\">Zv&yacute;&scaron;en&iacute; mezd a benefitů</strong> &ndash; Někter&eacute; firmy se snaž&iacute; konkurovat vy&scaron;&scaron;&iacute;mi platy, del&scaron;&iacute; dovolenou či flexibiln&iacute; pracovn&iacute; dobou.</li>\r\n<li data-start=\"2063\" data-end=\"2198\"><strong data-start=\"2065\" data-end=\"2090\">Spolupr&aacute;ce se &scaron;kolami</strong> &ndash; Podpora odborn&eacute;ho vzděl&aacute;v&aacute;n&iacute; a nab&iacute;dka praxe pro studenty může pomoci vychovat nov&eacute; generace odborn&iacute;ků.</li>\r\n<li data-start=\"2199\" data-end=\"2370\"><strong data-start=\"2201\" data-end=\"2232\">Automatizace a digitalizace</strong> &ndash; Investice do modern&iacute;ch technologi&iacute; snižuj&iacute; potřebu lidsk&eacute; pr&aacute;ce, což někter&yacute;m podnikům umožňuje přež&iacute;t i s men&scaron;&iacute;m počtem zaměstnanců.</li>\r\n<li data-start=\"2371\" data-end=\"2504\"><strong data-start=\"2373\" data-end=\"2406\">N&aacute;bor pracovn&iacute;ků ze zahranič&iacute;</strong> &ndash; Ukrajinci, Slov&aacute;ci a dal&scaron;&iacute; cizinci pom&aacute;haj&iacute; vykr&yacute;t největ&scaron;&iacute; nedostatky v někter&yacute;ch profes&iacute;ch.</li>\r\n</ul>\r\n<h4 data-start=\"2506\" data-end=\"2565\"><strong data-start=\"2511\" data-end=\"2563\">Budoucnost rodinn&yacute;ch firem ve v&yacute;chodn&iacute;ch Čech&aacute;ch</strong></h4>\r\n<p data-start=\"2567\" data-end=\"2883\">Přestože situace nen&iacute; snadn&aacute;, rodinn&eacute; podniky se snaž&iacute; naj&iacute;t cesty, jak se s probl&eacute;mem vypoř&aacute;dat. Kl&iacute;čem k &uacute;spěchu bude přizpůsoben&iacute; se nov&yacute;m trendům, investice do mlad&yacute;ch talentů a modernizace provozu. Pokud se nepodař&iacute; naj&iacute;t ře&scaron;en&iacute;, hroz&iacute;, že někter&eacute; tradičn&iacute; firmy zaniknou nebo budou muset změnit sv&eacute; zaměřen&iacute;.</p>\r\n<p data-start=\"2885\" data-end=\"3024\" data-is-last-node=\"\" data-is-only-node=\"\">Rodinn&eacute; podnik&aacute;n&iacute; je v&scaron;ak v regionu hluboce zakořeněn&eacute; a mnoh&eacute; firmy věř&iacute;, že s odhodl&aacute;n&iacute;m a inovacemi se jim podař&iacute; překonat i tuto v&yacute;zvu.</p>', '2025-03-11 11:00:00', '2025-03-18 10:18:05', 1, 19, 2, 4),
(175, 'Ceny nemovitostí v Hradci Králové rostou, zájem o bydlení nepolevuje', 'Ceny nemovitostí v Hradci Králové nadále rostou a zájem o bydlení neklesá. Nedostatek nových bytů a rostoucí náklady na výstavbu tlačí ceny vzhůru, což ovlivňuje jak kupující, tak nájemníky. Jaké faktory stojí za tímto trendem a co očekávají odborníci do budoucna?', 'Ceny nemovitostí v Hradci Králové stále rostou, a to i přes očekávání zpomalení trhu. Hlavními důvody jsou vysoká poptávka, nedostatečná nabídka a rostoucí náklady na výstavbu. Největší zájem je o menší byty a rodinné domy na okraji města, zatímco starší a větší byty se prodávají pomaleji. Kvůli drahým hypotékám roste i počet lidí, kteří volí nájemní bydlení, což zvyšuje ceny nájmů. Odborníci předpokládají, že růst cen bude pokračovat, pokud se výrazně nezvýší nabídka nových bytů nebo se nesníží úrokové sazby.', '<article class=\"w-full text-token-text-primary focus-visible:outline-2 focus-visible:outline-offset-[-4px]\" dir=\"auto\" data-testid=\"conversation-turn-207\" data-scroll-anchor=\"true\">\r\n<div class=\"text-base my-auto mx-auto py-[18px] px-6\">\r\n<div class=\"mx-auto flex flex-1 text-base gap-4 md:gap-5 lg:gap-6 md:max-w-3xl lg:max-w-[40rem] xl:max-w-[48rem]\">\r\n<div class=\"group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn @xs/thread:px-0 @sm/thread:px-1.5 @md/thread:px-4\">\r\n<div class=\"flex-col gap-1 md:gap-3\">\r\n<div class=\"flex max-w-full flex-col flex-grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 whitespace-normal break-words text-start [.text-message+&amp;]:mt-5\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"6c414e9c-fe5e-438e-9c27-adc663151f70\" data-message-model-slug=\"gpt-4o\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\">\r\n<div class=\"markdown prose w-full break-words dark:prose-invert light\">\r\n<h2 data-start=\"0\" data-end=\"74\">Ceny nemovitost&iacute; v Hradci Kr&aacute;lov&eacute; rostou, z&aacute;jem o bydlen&iacute; nepolevuje</h2>\r\n<p data-start=\"76\" data-end=\"371\">Trh s nemovitostmi v Hradci Kr&aacute;lov&eacute; proch&aacute;z&iacute; v&yacute;razn&yacute;m růstem cen. Přestože se oček&aacute;valo zpomalen&iacute; popt&aacute;vky kvůli vysok&yacute;m &uacute;rokov&yacute;m sazb&aacute;m a rostouc&iacute;m n&aacute;kladům na bydlen&iacute;, realita ukazuje prav&yacute; opak. Bytov&eacute; jednotky i rodinn&eacute; domy jsou nad&aacute;le ve velk&eacute;m z&aacute;jmu a ceny se tak drž&iacute; na vysok&eacute; &uacute;rovni.</p>\r\n<h2 data-start=\"373\" data-end=\"410\"><strong data-start=\"376\" data-end=\"408\">Růst cen navzdory oček&aacute;v&aacute;n&iacute;m</strong></h2>\r\n<p data-start=\"412\" data-end=\"568\">Podle realitn&iacute;ch makl&eacute;řů a analytiků do&scaron;lo v posledn&iacute;ch měs&iacute;c&iacute;ch k dal&scaron;&iacute;mu zdražen&iacute; nemovitost&iacute; v Hradci Kr&aacute;lov&eacute;. Mezi hlavn&iacute; faktory tohoto trendu patř&iacute;:</p>\r\n<ul data-start=\"570\" data-end=\"899\">\r\n<li data-start=\"570\" data-end=\"672\"><strong data-start=\"572\" data-end=\"596\">Nedostatečn&aacute; nab&iacute;dka</strong> &ndash; Nov&eacute; developersk&eacute; projekty se stav&iacute; pomalu a nedok&aacute;žou pokr&yacute;t popt&aacute;vku.</li>\r\n<li data-start=\"673\" data-end=\"779\"><strong data-start=\"675\" data-end=\"702\">Rostouc&iacute; počet obyvatel</strong> &ndash; Město je atraktivn&iacute; pro mlad&eacute; rodiny i investory, což tlač&iacute; ceny nahoru.</li>\r\n<li data-start=\"780\" data-end=\"899\"><strong data-start=\"782\" data-end=\"812\">Inflace a stavebn&iacute; n&aacute;klady</strong> &ndash; Růst cen stavebn&iacute;ch materi&aacute;lů a prac&iacute; se prom&iacute;t&aacute; do cen novostaveb i rekonstrukc&iacute;.</li>\r\n</ul>\r\n<h3 data-start=\"901\" data-end=\"951\"><strong data-start=\"905\" data-end=\"949\">Jak&eacute; typy nemovitost&iacute; jsou nejž&aacute;daněj&scaron;&iacute;?</strong></h3>\r\n<p data-start=\"953\" data-end=\"1178\">V Hradci Kr&aacute;lov&eacute; je dlouhodobě vysok&yacute; z&aacute;jem předev&scaron;&iacute;m o <strong data-start=\"1009\" data-end=\"1023\">men&scaron;&iacute; byty</strong>, kter&eacute; jsou vhodn&eacute; jak pro mlad&eacute; p&aacute;ry, tak pro investory, kteř&iacute; je kupuj&iacute; na pron&aacute;jem. Ceny těchto jednotek se v posledn&iacute;m roce zv&yacute;&scaron;ily o v&iacute;ce než 10 %.</p>\r\n<p data-start=\"1180\" data-end=\"1206\">Největ&scaron;&iacute; popt&aacute;vka je po:</p>\r\n<ul data-start=\"1207\" data-end=\"1467\">\r\n<li data-start=\"1207\" data-end=\"1292\"><strong data-start=\"1209\" data-end=\"1224\">1+kk a 2+kk</strong> &ndash; Mal&eacute; byty jsou cenově dostupněj&scaron;&iacute; a rychle se obsad&iacute; n&aacute;jemn&iacute;ky.</li>\r\n<li data-start=\"1293\" data-end=\"1376\"><strong data-start=\"1295\" data-end=\"1327\">Rodinn&eacute; domy na okraji města</strong> &ndash; Lid&eacute; hledaj&iacute; klidněj&scaron;&iacute; bydlen&iacute; mimo centrum.</li>\r\n<li data-start=\"1377\" data-end=\"1467\"><strong data-start=\"1379\" data-end=\"1393\">Novostavby</strong> &ndash; Modern&iacute; byty s n&iacute;zkou energetickou n&aacute;ročnost&iacute; jsou st&aacute;le obl&iacute;beněj&scaron;&iacute;.</li>\r\n</ul>\r\n<p data-start=\"1469\" data-end=\"1609\">Naopak star&scaron;&iacute; byty v původn&iacute;m stavu nebo velk&eacute; byty nad 100 m&sup2; se prod&aacute;vaj&iacute; pomaleji, protože jejich rekonstrukce vyžaduje vysok&eacute; n&aacute;klady.</p>\r\n<h2 data-start=\"1611\" data-end=\"1649\"><strong data-start=\"1614\" data-end=\"1647\">Dopad na kupuj&iacute;c&iacute; a n&aacute;jemn&iacute;ky</strong></h2>\r\n<p data-start=\"1651\" data-end=\"1845\">Růst cen nemovitost&iacute; znamen&aacute;, že mnoho z&aacute;jemců o vlastn&iacute; bydlen&iacute; m&aacute; probl&eacute;m dos&aacute;hnout na hypot&eacute;ku. Banky sice pomalu zač&iacute;naj&iacute; uvolňovat podm&iacute;nky, ale &uacute;rokov&eacute; sazby jsou st&aacute;le relativně vysok&eacute;.</p>\r\n<p data-start=\"1847\" data-end=\"1988\">Mnoz&iacute; tak vol&iacute; <strong data-start=\"1862\" data-end=\"1881\">n&aacute;jemn&iacute; bydlen&iacute;</strong>, kter&eacute; se ale tak&eacute; prodražuje. N&aacute;jemn&eacute; se v posledn&iacute;m roce zv&yacute;&scaron;ilo v průměru o 15 %, a to zejm&eacute;na kvůli:</p>\r\n<ul data-start=\"1989\" data-end=\"2163\">\r\n<li data-start=\"1989\" data-end=\"2041\"><strong data-start=\"1991\" data-end=\"2039\">Vět&scaron;&iacute;mu z&aacute;jmu o n&aacute;jmy kvůli drah&yacute;m hypot&eacute;k&aacute;m</strong></li>\r\n<li data-start=\"2042\" data-end=\"2116\"><strong data-start=\"2044\" data-end=\"2114\">Přistěhovalcům a studentům, kteř&iacute; v Hradci hledaj&iacute; dočasn&eacute; bydlen&iacute;</strong></li>\r\n<li data-start=\"2117\" data-end=\"2163\"><strong data-start=\"2119\" data-end=\"2161\">Men&scaron;&iacute; nab&iacute;dce voln&yacute;ch bytů na pron&aacute;jem</strong></li>\r\n</ul>\r\n<h3 data-start=\"2165\" data-end=\"2193\"><strong data-start=\"2169\" data-end=\"2191\">Budouc&iacute; v&yacute;voj trhu</strong></h3>\r\n<p data-start=\"2195\" data-end=\"2389\">Odborn&iacute;ci oček&aacute;vaj&iacute;, že ceny nemovitost&iacute; v Hradci Kr&aacute;lov&eacute; budou i nad&aacute;le růst, i když pomalej&scaron;&iacute;m tempem. V&yacute;razněj&scaron;&iacute; pokles se neoček&aacute;v&aacute;, protože popt&aacute;vka zůst&aacute;v&aacute; siln&aacute; a nab&iacute;dka st&aacute;le nestač&iacute;.</p>\r\n<p data-start=\"2391\" data-end=\"2453\">Podle makl&eacute;řů by mohlo doj&iacute;t ke <strong data-start=\"2423\" data-end=\"2443\">stabilizaci trhu</strong>, pokud:</p>\r\n<ol data-start=\"2454\" data-end=\"2721\">\r\n<li data-start=\"2454\" data-end=\"2538\"><strong data-start=\"2457\" data-end=\"2497\">Vznikne v&iacute;ce developersk&yacute;ch projektů</strong> zaměřen&yacute;ch na cenově dostupn&eacute; bydlen&iacute;.</li>\r\n<li data-start=\"2539\" data-end=\"2617\"><strong data-start=\"2542\" data-end=\"2578\">Dojde ke sn&iacute;žen&iacute; &uacute;rokov&yacute;ch sazeb</strong>, což by zlep&scaron;ilo dostupnost hypot&eacute;k.</li>\r\n<li data-start=\"2618\" data-end=\"2721\"><strong data-start=\"2621\" data-end=\"2659\">Město podpoř&iacute; v&yacute;stavbu nov&yacute;ch bytů</strong> např&iacute;klad prostřednictv&iacute;m zjednodu&scaron;en&iacute; stavebn&iacute;ch povolen&iacute;.</li>\r\n</ol>\r\n<h2 data-start=\"2723\" data-end=\"2737\"><strong data-start=\"2726\" data-end=\"2735\">Z&aacute;věr</strong></h2>\r\n<p data-start=\"2739\" data-end=\"3023\" data-is-last-node=\"\" data-is-only-node=\"\">Ceny nemovitost&iacute; v Hradci Kr&aacute;lov&eacute; rostou a situace se zat&iacute;m nezd&aacute; b&yacute;t př&iacute;zniv&aacute; pro kupuj&iacute;c&iacute;. Nedostatečn&aacute; nab&iacute;dka a vysok&aacute; popt&aacute;vka udržuj&iacute; ceny na vysok&eacute; &uacute;rovni, což se projevuje i na trhu s n&aacute;jmy. Z&aacute;jemci o bydlen&iacute; tak mus&iacute; pečlivě zvažovat sv&eacute; možnosti a poč&iacute;tat s vy&scaron;&scaron;&iacute;mi n&aacute;klady.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</article>', '2025-03-11 11:08:06', '2025-03-18 11:59:18', 1, 19, 2, 4),
(176, 'Biatlonisté z východních Čech zazářili na mistrovství republiky', 'Biatlonisté z východních Čech zaznamenali na mistrovství republiky výjimečné úspěchy a přivezli si cenné medaile. Jejich výkony potvrdily sílu regionální biatlonové scény a naznačily slibnou budoucnost mladých talentů. Podívejte se, kdo zazářil na trati i na střelnici.', 'Biatlonisté z východních Čech zazářili na mistrovství republiky, kde získali několik medailových umístění. Největším překvapením bylo vítězství Jana Dvořáka ve sprintu i stíhacím závodě, zatímco týmová štafeta mužů dominovala celému závodu. Výsledky potvrzují silnou tradici biatlonu v regionu, kde se plánují další investice do zázemí a přípravy mladých talentů.', '<article class=\"w-full text-token-text-primary focus-visible:outline-2 focus-visible:outline-offset-[-4px]\" dir=\"auto\" data-testid=\"conversation-turn-215\" data-scroll-anchor=\"true\">\r\n<div class=\"text-base my-auto mx-auto py-[18px] px-6\">\r\n<div class=\"mx-auto flex flex-1 text-base gap-4 md:gap-5 lg:gap-6 md:max-w-3xl lg:max-w-[40rem] xl:max-w-[48rem]\">\r\n<div class=\"group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn @xs/thread:px-0 @sm/thread:px-1.5 @md/thread:px-4\">\r\n<div class=\"flex-col gap-1 md:gap-3\">\r\n<div class=\"flex max-w-full flex-col flex-grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 whitespace-normal break-words text-start [.text-message+&amp;]:mt-5\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"fa499f56-e67c-4bb4-9326-fa5197dbd97f\" data-message-model-slug=\"gpt-4o\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\">\r\n<div class=\"markdown prose w-full break-words dark:prose-invert light\">\r\n<h2 data-start=\"0\" data-end=\"69\">Biatlonist&eacute; z v&yacute;chodn&iacute;ch Čech zaz&aacute;řili na mistrovstv&iacute; republiky</h2>\r\n<p data-start=\"71\" data-end=\"413\">Biatlonov&aacute; sez&oacute;na vrchol&iacute; a <strong data-start=\"99\" data-end=\"130\">mistrovstv&iacute; Česk&eacute; republiky</strong> přineslo skvěl&eacute; v&yacute;sledky pro sportovce z v&yacute;chodn&iacute;ch Čech. Z&aacute;vody, kter&eacute; se konaly v <strong data-start=\"215\" data-end=\"240\">Nov&eacute;m Městě na Moravě</strong>, přil&aacute;kaly nejen nejlep&scaron;&iacute; česk&eacute; biatlonisty, ale i nad&scaron;en&eacute; fanou&scaron;ky. V&yacute;prava z Kr&aacute;lov&eacute;hradeck&eacute;ho a Pardubick&eacute;ho kraje uk&aacute;zala svou s&iacute;lu a z&iacute;skala několik cenn&yacute;ch medail&iacute;.</p>\r\n<h4 data-start=\"415\" data-end=\"463\">Skvěl&eacute; v&yacute;sledky v individu&aacute;ln&iacute;ch z&aacute;vodech</h4>\r\n<p data-start=\"464\" data-end=\"794\">Jedn&iacute;m z největ&scaron;&iacute;ch překvapen&iacute; bylo <strong data-start=\"500\" data-end=\"542\">v&iacute;tězstv&iacute; mlad&eacute;ho talentu Jana Dvoř&aacute;ka</strong>, kter&yacute; v kategorii juniorů ovl&aacute;dl sprint a n&aacute;sledně si připsal i triumf ve st&iacute;hac&iacute;m z&aacute;vodě. <em data-start=\"635\" data-end=\"721\">&bdquo;Byl to můj nejlep&scaron;&iacute; z&aacute;vod v sez&oacute;ně, střelba mi sedla a na trati jsem měl dost sil,&ldquo;</em> komentoval svůj &uacute;spěch Dvoř&aacute;k, kter&yacute; patř&iacute; k naděj&iacute;m česk&eacute;ho biatlonu.</p>\r\n<p data-start=\"796\" data-end=\"830\">Dal&scaron;&iacute; medailov&eacute; pozice obsadili:</p>\r\n<ul data-start=\"831\" data-end=\"989\">\r\n<li data-start=\"831\" data-end=\"878\"><strong data-start=\"833\" data-end=\"850\">Pavla Novotn&aacute;</strong> &ndash; stř&iacute;brn&aacute; ve sprintu žen</li>\r\n<li data-start=\"879\" data-end=\"937\"><strong data-start=\"881\" data-end=\"895\">Tom&aacute;&scaron; Kř&iacute;ž</strong> &ndash; bronzov&yacute; ve vytrvalostn&iacute;m z&aacute;vodě mužů</li>\r\n<li data-start=\"938\" data-end=\"989\"><strong data-start=\"940\" data-end=\"959\">T&yacute;m z Letohradu</strong> &ndash; v&iacute;tězstv&iacute; ve &scaron;tafetě mužů</li>\r\n</ul>\r\n<p data-start=\"991\" data-end=\"1154\">V z&aacute;vodě žen se bl&yacute;skla <strong data-start=\"1015\" data-end=\"1032\">Veronika Mal&aacute;</strong>, kter&aacute; sice na střelnici několikr&aacute;t chybovala, ale d&iacute;ky rychl&eacute;mu běhu si dojela pro <strong data-start=\"1117\" data-end=\"1151\">třet&iacute; m&iacute;sto ve st&iacute;hac&iacute;m z&aacute;vodě</strong>.</p>\r\n<h4 data-start=\"1156\" data-end=\"1185\">Dominance ve &scaron;tafet&aacute;ch</h4>\r\n<p data-start=\"1186\" data-end=\"1535\">T&yacute;mov&eacute; z&aacute;vody potvrdily, že <strong data-start=\"1214\" data-end=\"1282\">biatlonov&eacute; kluby z v&yacute;chodn&iacute;ch Čech patř&iacute; k nejlep&scaron;&iacute;m v republice</strong>. Mužsk&aacute; &scaron;tafeta složen&aacute; z reprezentantů Letohradu a Jablonce nad Nisou dominovala cel&eacute;mu z&aacute;vodu a zv&iacute;tězila s pohodln&yacute;m n&aacute;skokem. <em data-start=\"1413\" data-end=\"1490\">&bdquo;Kluci jeli v&yacute;borně, podrželi jsme si střelbu a na trati jsme byli rychl&iacute;,&ldquo;</em> hodnotil z&aacute;vod fini&scaron;man t&yacute;mu Martin Vlček.</p>\r\n<p data-start=\"1537\" data-end=\"1655\">Mezi ženami bojovala o v&iacute;tězstv&iacute; &scaron;tafeta z <strong data-start=\"1580\" data-end=\"1607\">Kr&aacute;lov&eacute;hradeck&eacute;ho kraje</strong>, kter&aacute; si nakonec dojela pro <strong data-start=\"1637\" data-end=\"1652\">druh&eacute; m&iacute;sto</strong>.</p>\r\n<h4 data-start=\"1657\" data-end=\"1707\">Z&aacute;zem&iacute; a budoucnost v&yacute;chodočesk&eacute;ho biatlonu</h4>\r\n<p data-start=\"1708\" data-end=\"2018\">V&yacute;chodn&iacute; Čechy jsou <strong data-start=\"1728\" data-end=\"1764\">tradičn&iacute; ba&scaron;tou česk&eacute;ho biatlonu</strong>. Kluby z Letohradu, Jablonce nad Nisou nebo Vrchlab&iacute; vychovaly řadu reprezentantů a mlad&eacute; talenty podporuj&iacute; i nyn&iacute;. <em data-start=\"1881\" data-end=\"1978\">&bdquo;Na&scaron;e ml&aacute;dež m&aacute; skvěl&eacute; podm&iacute;nky pro tr&eacute;nink, a v&yacute;sledky na mistrovstv&iacute; republiky to potvrzuj&iacute;,&ldquo;</em> uvedl tren&eacute;r Jiř&iacute; Kučera z Letohradu.</p>\r\n<p data-start=\"2020\" data-end=\"2250\">Podpora biatlonu v regionu se neomezuje jen na sportovce. <strong data-start=\"2078\" data-end=\"2137\">Pl&aacute;nuj&iacute; se investice do modernizace tr&eacute;ninkov&yacute;ch are&aacute;lů</strong> a zvět&scaron;en&iacute; kapacity střelnic. C&iacute;lem je <strong data-start=\"2177\" data-end=\"2247\">udržet kvalitn&iacute; př&iacute;pravu a přiv&eacute;st do biatlonu dal&scaron;&iacute; mlad&eacute; talenty</strong>.</p>\r\n<h4 data-start=\"2252\" data-end=\"2290\">Oček&aacute;v&aacute;n&iacute; směrem k dal&scaron;&iacute; sez&oacute;ně</h4>\r\n<p data-start=\"2291\" data-end=\"2540\">Po &uacute;spě&scaron;n&eacute;m mistrovstv&iacute; republiky se v&yacute;chodoče&scaron;t&iacute; biatlonist&eacute; budou soustředit na <strong data-start=\"2373\" data-end=\"2412\">letn&iacute; př&iacute;pravu a mezin&aacute;rodn&iacute; z&aacute;vody</strong>. Někteř&iacute; z nich maj&iacute; &scaron;anci bojovat o nominaci na <strong data-start=\"2462\" data-end=\"2479\">světov&yacute; poh&aacute;r</strong>, jin&iacute; se zaměř&iacute; na <strong data-start=\"2499\" data-end=\"2537\">Evropsk&yacute; poh&aacute;r a juniorsk&eacute; soutěže</strong>.</p>\r\n<p data-start=\"2542\" data-end=\"2713\" data-is-last-node=\"\" data-is-only-node=\"\">Biatlon ve v&yacute;chodn&iacute;ch Čech&aacute;ch tak rozhodně <strong data-start=\"2585\" data-end=\"2602\">m&aacute; budoucnost</strong>, a pokud se talentovan&yacute;m sportovcům podař&iacute; udržet formu, mohou v př&iacute;&scaron;t&iacute;ch letech z&aacute;řit i na mezin&aacute;rodn&iacute; sc&eacute;ně.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</article>', '2025-03-11 11:13:46', '2025-03-19 12:36:52', 6, 19, 4, 4);
INSERT INTO `clanky` (`idClanky`, `nadpis`, `upoutavka`, `uryvek`, `obsah`, `created_at`, `updated_at`, `zhlednuti`, `Uzivatele_idUzivatele`, `Kategorie_idKategorie`, `Stav_idStav`) VALUES
(177, 'Hradecký půlmaraton přilákal rekordní počet běžců', 'Hradecký půlmaraton letos překonal všechna očekávání a přilákal rekordní počet běžců. Trasa vedla historickým centrem i malebnou přírodou, zatímco diváci podél tratě vytvořili nezapomenutelnou atmosféru. Podívejte se, jak závod probíhal a kdo se stal letošním vítězem.', 'Hradecký půlmaraton zaznamenal rekordní účast, když se na start postavilo přes 2 500 běžců. Závod vedl historickým centrem města i okolní přírodou a nabídl skvělou atmosféru díky fandícím divákům. Vítězem mezi muži se stal Jakub Novák, mezi ženami dominovala Petra Kučerová. Organizátoři chválí úspěch letošního ročníku a plánují další vylepšení pro příští rok.', '<h2 data-start=\"0\" data-end=\"55\"><strong data-start=\"0\" data-end=\"53\">Hradeck&yacute; půlmaraton přil&aacute;kal rekordn&iacute; počet běžců</strong></h2>\r\n<p data-start=\"57\" data-end=\"368\">Hradec Kr&aacute;lov&eacute; zažil o v&iacute;kendu v&yacute;jimečnou sportovn&iacute; ud&aacute;lost. Tradičn&iacute; Hradeck&yacute; půlmaraton se letos tě&scaron;il neb&yacute;val&eacute;mu z&aacute;jmu jak ze strany z&aacute;vodn&iacute;ků, tak i div&aacute;ků. Rekordn&iacute; &uacute;čast uk&aacute;zala, že běh&aacute;n&iacute; je v regionu st&aacute;le popul&aacute;rněj&scaron;&iacute; a přitahuje nejen amat&eacute;rsk&eacute; sportovce, ale i profesion&aacute;ln&iacute; běžce z cel&eacute; republiky.</p>\r\n<h3 data-start=\"370\" data-end=\"413\"><strong data-start=\"374\" data-end=\"411\">Rekordn&iacute; &uacute;čast a skvěl&aacute; atmosf&eacute;ra</strong></h3>\r\n<p data-start=\"415\" data-end=\"718\">Leto&scaron;n&iacute; ročn&iacute;k půlmaratonu překonal v&scaron;echny předchoz&iacute; statistiky. Organiz&aacute;toři hl&aacute;sili v&iacute;ce než <em data-start=\"511\" data-end=\"537\">2 500 přihl&aacute;&scaron;en&yacute;ch běžců</em>, což je o několik stovek v&iacute;ce než v loňsk&eacute;m roce. Kromě půlmaratonu byla souč&aacute;st&iacute; programu i desetikilometrov&aacute; trať a &scaron;tafetov&yacute; běh, kter&eacute; přil&aacute;kaly mnoho rodin a firemn&iacute;ch t&yacute;mů.</p>\r\n<p data-start=\"720\" data-end=\"962\">Atmosf&eacute;ra na trati byla <em data-start=\"744\" data-end=\"757\">fantastick&aacute;</em>, pod&eacute;l cel&eacute; trasy fandily davy div&aacute;ků a hudebn&iacute; skupiny povzbuzovaly běžce k lep&scaron;&iacute;m v&yacute;konům. D&iacute;ky ide&aacute;ln&iacute;mu počas&iacute; a skvěl&eacute; organizaci se podařilo vytvořit nezapomenuteln&yacute; z&aacute;žitek pro v&scaron;echny &uacute;častn&iacute;ky.</p>\r\n<h3 data-start=\"964\" data-end=\"1018\"><strong data-start=\"968\" data-end=\"1016\">Trasa vedouc&iacute; historick&yacute;m centrem a př&iacute;rodou</strong></h3>\r\n<p data-start=\"1020\" data-end=\"1302\">Hradeck&yacute; půlmaraton je unik&aacute;tn&iacute; svou trasou. Běžci startovali na <strong data-start=\"1085\" data-end=\"1103\">Velk&eacute;m n&aacute;měst&iacute;</strong>, odkud se vydali historick&yacute;mi uličkami města a pokračovali pod&eacute;l řeky Labe do malebn&yacute;ch městsk&yacute;ch lesů. Tento kontrast mezi architekturou a př&iacute;rodou je jedn&iacute;m z důvodů, proč je z&aacute;vod tak obl&iacute;ben&yacute;.</p>\r\n<p data-start=\"1304\" data-end=\"1539\">Na trase byly rozm&iacute;stěny <strong data-start=\"1329\" data-end=\"1354\">občerstvovac&iacute; stanice</strong>, kde si &uacute;častn&iacute;ci mohli doplnit energii a hydrataci. Letos organiz&aacute;toři dbali na ekologickou str&aacute;nku z&aacute;vodu a nab&iacute;dli <strong data-start=\"1473\" data-end=\"1508\">biologicky rozložiteln&eacute; kel&iacute;mky</strong> a minim&aacute;ln&iacute; produkci odpadu.</p>\r\n<h3 data-start=\"1541\" data-end=\"1591\"><strong data-start=\"1545\" data-end=\"1589\">V&iacute;tězov&eacute; a v&yacute;kony, kter&eacute; stoj&iacute; za zm&iacute;nku</strong></h3>\r\n<p data-start=\"1593\" data-end=\"1857\">V mužsk&eacute; kategorii si pro v&iacute;tězstv&iacute; doběhl <strong data-start=\"1636\" data-end=\"1651\">Jakub Nov&aacute;k</strong>, kter&yacute; zvl&aacute;dl trať ve skvěl&eacute;m čase <em data-start=\"1687\" data-end=\"1696\">1:08:45</em>. Mezi ženami dominovala <strong data-start=\"1721\" data-end=\"1739\">Petra Kučerov&aacute;</strong>, kter&aacute; dokončila z&aacute;vod v čase <em data-start=\"1770\" data-end=\"1779\">1:19:30</em>. Oba běžci si kromě trofeje odnesli i finančn&iacute; odměnu a uzn&aacute;n&iacute; od fanou&scaron;ků.</p>\r\n<p data-start=\"1859\" data-end=\"2044\">Za zm&iacute;nku stoj&iacute; i v&yacute;kony veter&aacute;nů, kteř&iacute; se nezalekli mlad&scaron;&iacute; konkurence. Nejstar&scaron;&iacute;m &uacute;častn&iacute;kem byl <strong data-start=\"1958\" data-end=\"1981\">72let&yacute; Josef Dvoř&aacute;k</strong>, kter&yacute; doběhl půlmaraton v obdivuhodn&eacute;m čase pod dvě hodiny.</p>\r\n<h3 data-start=\"2046\" data-end=\"2088\"><strong data-start=\"2050\" data-end=\"2086\">Ohlasy běžců a pl&aacute;ny do budoucna</strong></h3>\r\n<p data-start=\"2090\" data-end=\"2296\">&Uacute;častn&iacute;ci z&aacute;vodu si pochvalovali <strong data-start=\"2123\" data-end=\"2145\">skvělou organizaci</strong>, <strong data-start=\"2147\" data-end=\"2170\">bezpečnost na trati</strong> a <strong data-start=\"2173\" data-end=\"2195\">v&yacute;bornou atmosf&eacute;ru</strong>. Mnoz&iacute; běžci si už nyn&iacute; slibuj&iacute; &uacute;čast i př&iacute;&scaron;t&iacute; rok a oček&aacute;v&aacute; se, že z&aacute;jem o z&aacute;vod bude st&aacute;le růst.</p>\r\n<p data-start=\"2298\" data-end=\"2478\">Organiz&aacute;toři pl&aacute;nuj&iacute; do př&iacute;&scaron;t&iacute;ho ročn&iacute;ku několik vylep&scaron;en&iacute;, včetně roz&scaron;&iacute;řen&iacute; <strong data-start=\"2375\" data-end=\"2395\">startovn&iacute;ho pole</strong>, <strong data-start=\"2397\" data-end=\"2428\">lep&scaron;&iacute;ho syst&eacute;mu občerstven&iacute;</strong> a <strong data-start=\"2431\" data-end=\"2475\">dal&scaron;&iacute;ch kategori&iacute; pro zač&aacute;tečn&iacute;ky a děti</strong>.</p>\r\n<h3 data-start=\"2480\" data-end=\"2506\"><strong data-start=\"2484\" data-end=\"2504\">Běh jako fenom&eacute;n</strong></h3>\r\n<p data-start=\"2508\" data-end=\"2756\">Rostouc&iacute; popularita běžeck&yacute;ch z&aacute;vodů ukazuje, že <strong data-start=\"2557\" data-end=\"2601\">běh&aacute;n&iacute; už nen&iacute; jen individu&aacute;ln&iacute;m sportem</strong>, ale i <strong data-start=\"2609\" data-end=\"2634\">společenskou ud&aacute;lost&iacute;</strong>. Hradeck&yacute; půlmaraton spojuje lidi v&scaron;ech věkov&yacute;ch kategori&iacute; a &uacute;rovn&iacute; v&yacute;konnosti, což potvrzuje i leto&scaron;n&iacute; rekordn&iacute; &uacute;čast.</p>\r\n<p data-start=\"2758\" data-end=\"2941\" data-is-last-node=\"\" data-is-only-node=\"\">Běh&aacute;n&iacute; nen&iacute; jen o v&iacute;tězstv&iacute;, ale hlavně o <strong data-start=\"2800\" data-end=\"2820\">radosti z pohybu</strong> a <strong data-start=\"2823\" data-end=\"2855\">překon&aacute;v&aacute;n&iacute; vlastn&iacute;ch limitů</strong>. Hradeck&yacute; půlmaraton je toho důkazem a tě&scaron;&iacute; se na dal&scaron;&iacute; nad&scaron;en&eacute; běžce v př&iacute;&scaron;t&iacute;m roce.</p>', '2025-03-11 11:19:18', '2025-03-23 17:17:09', 259, 19, 4, 4),
(178, 'Fotbalový klub z Pardubic slaví postup do první ligy', 'Pardubický fotbal zažívá historický úspěch. Místní klub si vybojoval postup do první ligy a fanoušci slaví velký triumf. Co vedlo k tomuto úspěchu a jaké výzvy tým čekají v nejvyšší soutěži?', 'Pardubický fotbalový klub slaví historický postup do první ligy po skvělé sezóně plné úspěchů. Hráči předvedli bojovný výkon, podpořený silnou defenzivou a produktivním útokem. Postup přinesl velké oslavy ve městě a klub nyní čeká výzva udržet se mezi elitou českého fotbalu.', '<h2 data-start=\"0\" data-end=\"58\"><strong data-start=\"0\" data-end=\"56\">Fotbalov&yacute; klub z Pardubic slav&iacute; postup do prvn&iacute; ligy</strong></h2>\r\n<h3 data-start=\"60\" data-end=\"105\">Historick&yacute; &uacute;spěch pro pardubick&yacute; fotbal</h3>\r\n<p data-start=\"107\" data-end=\"457\">Pardubick&yacute; fotbalov&yacute; klub dos&aacute;hl jednoho z největ&scaron;&iacute;ch miln&iacute;ků ve sv&eacute; historii &ndash; postup do <strong data-start=\"197\" data-end=\"211\">prvn&iacute; ligy</strong>. Tento &uacute;spěch je v&yacute;sledkem tvrd&eacute; pr&aacute;ce hr&aacute;čů, tren&eacute;rů i veden&iacute; klubu, kteř&iacute; v posledn&iacute;ch sez&oacute;n&aacute;ch usilovně bojovali o co nejlep&scaron;&iacute; v&yacute;sledky. Fanou&scaron;ci se mohou tě&scaron;it na prestižn&iacute; z&aacute;pasy s nejlep&scaron;&iacute;mi česk&yacute;mi t&yacute;my a novou &eacute;ru pardubick&eacute;ho fotbalu.</p>\r\n<h3 data-start=\"459\" data-end=\"497\">Kl&iacute;čov&aacute; sez&oacute;na a cesta k &uacute;spěchu</h3>\r\n<p data-start=\"499\" data-end=\"673\">Sez&oacute;na byla pln&aacute; nap&iacute;nav&yacute;ch momentů, těžk&yacute;ch z&aacute;pasů a kl&iacute;čov&yacute;ch okamžiků, kter&eacute; rozhodly o historick&eacute;m postupu. Mezi hlavn&iacute; faktory, kter&eacute; přispěly k tomuto &uacute;spěchu, patř&iacute;:</p>\r\n<ul data-start=\"675\" data-end=\"1041\">\r\n<li data-start=\"675\" data-end=\"755\"><strong data-start=\"677\" data-end=\"701\">Skvěl&aacute; t&yacute;mov&aacute; souhra</strong> &ndash; hr&aacute;či předv&aacute;děli disciplinovan&yacute; a bojovn&yacute; fotbal.</li>\r\n<li data-start=\"756\" data-end=\"856\"><strong data-start=\"758\" data-end=\"777\">Siln&aacute; defenziva</strong> &ndash; obrana dok&aacute;zala eliminovat &uacute;toky soupeřů a t&yacute;m inkasoval jen minimum g&oacute;lů.</li>\r\n<li data-start=\"857\" data-end=\"954\"><strong data-start=\"859\" data-end=\"879\">Produktivn&iacute; &uacute;tok</strong> &ndash; kl&iacute;čov&iacute; střelci přispěli důležit&yacute;mi brankami v rozhoduj&iacute;c&iacute;ch z&aacute;pasech.</li>\r\n<li data-start=\"955\" data-end=\"1041\"><strong data-start=\"957\" data-end=\"977\">Podpora fanou&scaron;ků</strong> &ndash; dom&aacute;c&iacute; z&aacute;pasy byly d&iacute;ky skvěl&eacute; atmosf&eacute;ře obrovskou v&yacute;hodou.</li>\r\n</ul>\r\n<h3 data-start=\"1043\" data-end=\"1071\">Ohlasy hr&aacute;čů a tren&eacute;ra</h3>\r\n<p data-start=\"1073\" data-end=\"1296\">K postupu se vyj&aacute;dřili i hlavn&iacute; akt&eacute;ři. <em data-start=\"1113\" data-end=\"1127\">Kapit&aacute;n t&yacute;mu</em> uvedl: <em data-start=\"1135\" data-end=\"1294\">&bdquo;Je to splněn&yacute; sen, dlouho jsme na tento moment čekali a konečně jsme ho dos&aacute;hli. T&yacute;m &scaron;lapal jako hodinky a věř&iacute;m, že v prvn&iacute; lize budeme konkurenceschopn&iacute;.&ldquo;</em></p>\r\n<p data-start=\"1298\" data-end=\"1502\">Hlavn&iacute; tren&eacute;r pochv&aacute;lil t&yacute;movou pr&aacute;ci a vyzdvihl <strong data-start=\"1347\" data-end=\"1360\">bojovnost</strong> a <strong data-start=\"1363\" data-end=\"1382\">odhodl&aacute;n&iacute; hr&aacute;čů</strong>. <em data-start=\"1384\" data-end=\"1472\">&bdquo;Hr&aacute;či odvedli neuvěřitelnou pr&aacute;ci. Byl to n&aacute;ročn&yacute; rok, ale tvrd&aacute; dřina se vyplatila,&ldquo;</em> řekl na tiskov&eacute; konferenci.</p>\r\n<h3 data-start=\"1504\" data-end=\"1524\">Oslavy postupu</h3>\r\n<p data-start=\"1526\" data-end=\"1811\">Postup do prvn&iacute; ligy si ž&aacute;d&aacute; <strong data-start=\"1555\" data-end=\"1571\">velk&eacute; oslavy</strong>, a ty v Pardubic&iacute;ch rozhodně nechyběly. Po posledn&iacute;m z&aacute;pase sez&oacute;ny zaplavili fanou&scaron;ci stadion i ulice města, kde se slavilo až do rann&iacute;ch hodin. Klub uspoř&aacute;dal ofici&aacute;ln&iacute; akci na hlavn&iacute;m n&aacute;měst&iacute;, kde hr&aacute;či poděkovali fanou&scaron;kům za podporu.</p>\r\n<h3 data-start=\"1813\" data-end=\"1850\">Co ček&aacute; Pardubice v prvn&iacute; lize?</h3>\r\n<p data-start=\"1852\" data-end=\"2030\">&Uacute;spěch s sebou přin&aacute;&scaron;&iacute; i <strong data-start=\"1877\" data-end=\"1891\">nov&eacute; v&yacute;zvy</strong>. Prvn&iacute; liga je n&aacute;ročn&aacute; soutěž a klub bude muset pos&iacute;lit k&aacute;dr, aby byl konkurenceschopn&yacute;. Mezi hlavn&iacute; c&iacute;le pro nadch&aacute;zej&iacute;c&iacute; sez&oacute;nu patř&iacute;:</p>\r\n<ol data-start=\"2032\" data-end=\"2315\">\r\n<li data-start=\"2032\" data-end=\"2111\"><strong data-start=\"2035\" data-end=\"2053\">Udržen&iacute; v lize</strong> &ndash; prioritou bude vyhnout se sestupu a stabilizovat t&yacute;m.</li>\r\n<li data-start=\"2112\" data-end=\"2214\"><strong data-start=\"2115\" data-end=\"2142\">Z&iacute;sk&aacute;n&iacute; zku&scaron;en&yacute;ch posil</strong> &ndash; veden&iacute; klubu už pracuje na přestupech hr&aacute;čů s ligov&yacute;mi zku&scaron;enostmi.</li>\r\n<li data-start=\"2215\" data-end=\"2315\"><strong data-start=\"2218\" data-end=\"2236\">Rozvoj ml&aacute;deže</strong> &ndash; akademie klubu je kvalitn&iacute; a c&iacute;lem je zapojit mlad&eacute; hr&aacute;če do prvn&iacute;ho t&yacute;mu.</li>\r\n</ol>\r\n<h3 data-start=\"2317\" data-end=\"2352\">Nov&aacute; &eacute;ra pardubick&eacute;ho fotbalu</h3>\r\n<p data-start=\"2354\" data-end=\"2649\" data-is-last-node=\"\" data-is-only-node=\"\">Postup do <strong data-start=\"2364\" data-end=\"2378\">prvn&iacute; ligy</strong> je historick&yacute;m miln&iacute;kem pro cel&yacute; klub i město. Fanou&scaron;ci se mohou tě&scaron;it na atraktivn&iacute; z&aacute;pasy a město Pardubice bude m&iacute;t &scaron;anci uk&aacute;zat se na <strong data-start=\"2517\" data-end=\"2546\">nejvy&scaron;&scaron;&iacute; fotbalov&eacute; &uacute;rovni</strong>. Nezb&yacute;v&aacute; než popř&aacute;t klubu hodně &scaron;těst&iacute; v nov&eacute; sez&oacute;ně a věřit, že jeho cesta v prvn&iacute; lize bude &uacute;spě&scaron;n&aacute;.</p>', '2025-03-11 11:23:44', '2025-03-16 15:20:54', 3, 19, 4, 4),
(179, 'Divadelní festival v Hradci Králové přinese premiéry i oblíbené zahraniční hosty', 'Hradec Králové se opět stane centrem divadelního dění. Nadcházející festival nabídne premiéry, zahraniční hosty i netradiční inscenace, které slibují nezapomenutelné zážitky. Milovníci divadla se mohou těšit na bohatý program plný kreativity a inovací.', 'Divadelní festival v Hradci Králové nabídne pestrý program s premiérami, zahraničními hosty a netradičními inscenacemi. Návštěvníci se mohou těšit na činohru, pohybové divadlo i experimentální představení, stejně jako na doprovodné akce, workshopy a diskuse s tvůrci. Festival potvrzuje význam Hradce Králové jako kulturního centra a přináší nevšední umělecké zážitky pro všechny generace.', '<h2 data-start=\"0\" data-end=\"77\"><strong data-start=\"0\" data-end=\"75\">Divadeln&iacute; festival v Hradci Kr&aacute;lov&eacute; přinese premi&eacute;ry i zahraničn&iacute; hosty</strong></h2>\r\n<p data-start=\"79\" data-end=\"385\">Hradec Kr&aacute;lov&eacute; se opět stane centrem divadeln&iacute;ho děn&iacute;. Leto&scaron;n&iacute; ročn&iacute;k tradičn&iacute;ho divadeln&iacute;ho festivalu slibuje nejen premi&eacute;ry česk&yacute;ch inscenac&iacute;, ale i &uacute;čast zahraničn&iacute;ch souborů. Organiz&aacute;toři si dali za c&iacute;l nab&iacute;dnout div&aacute;kům pestr&yacute; program, kter&yacute; propoj&iacute; modern&iacute; divadeln&iacute; formy s klasick&yacute;mi inscenacemi.</p>\r\n<h3 data-start=\"387\" data-end=\"421\"><strong data-start=\"391\" data-end=\"419\">Pestr&yacute; program a novinky</strong></h3>\r\n<p data-start=\"422\" data-end=\"755\">Festival nab&iacute;dne &scaron;irokou &scaron;k&aacute;lu ž&aacute;nrů od činohry přes pohybov&eacute; divadlo až po experiment&aacute;ln&iacute; inscenace. <strong data-start=\"524\" data-end=\"635\">Letos se div&aacute;ci mohou tě&scaron;it na několik premi&eacute;r, mezi nimiž nebudou chybět ani odv&aacute;žn&aacute; autorsk&aacute; představen&iacute;.</strong> V&yacute;raznou novinkou bude vět&scaron;&iacute; propojen&iacute; divadla s dal&scaron;&iacute;mi uměleck&yacute;mi formami, jako je hudba, film nebo v&yacute;tvarn&eacute; uměn&iacute;.</p>\r\n<p data-start=\"757\" data-end=\"794\">Mezi hlavn&iacute; tah&aacute;ky festivalu patř&iacute;:</p>\r\n<ul data-start=\"795\" data-end=\"1180\">\r\n<li data-start=\"795\" data-end=\"894\"><strong data-start=\"797\" data-end=\"843\">Premi&eacute;ra hry renomovan&eacute;ho česk&eacute;ho režis&eacute;ra</strong>, kter&aacute; se zaměř&iacute; na aktu&aacute;ln&iacute; společensk&aacute; t&eacute;mata.</li>\r\n<li data-start=\"895\" data-end=\"991\"><strong data-start=\"897\" data-end=\"917\">Zahraničn&iacute; host&eacute;</strong> z Německa, Polska a Francie, kteř&iacute; přivezou inovativn&iacute; divadeln&iacute; formy.</li>\r\n<li data-start=\"992\" data-end=\"1065\"><strong data-start=\"994\" data-end=\"1018\">Pouličn&iacute; představen&iacute;</strong>, kter&aacute; vt&aacute;hnou do děje i kolemjdouc&iacute; div&aacute;ky.</li>\r\n<li data-start=\"1066\" data-end=\"1180\"><strong data-start=\"1068\" data-end=\"1087\">Doprovodn&eacute; akce</strong>, mezi kter&eacute; patř&iacute; workshopy, diskuse s tvůrci nebo prom&iacute;t&aacute;n&iacute; z&aacute;znamů kultovn&iacute;ch inscenac&iacute;.</li>\r\n</ul>\r\n<h3 data-start=\"1182\" data-end=\"1233\"><strong data-start=\"1186\" data-end=\"1231\">Zahraničn&iacute; soubory přivezou novou energii</strong></h3>\r\n<p data-start=\"1234\" data-end=\"1592\">Velk&yacute;m l&aacute;kadlem budou <strong data-start=\"1256\" data-end=\"1296\">hostuj&iacute;c&iacute; divadeln&iacute; soubory z Evropy</strong>, kter&eacute; představ&iacute; různ&eacute; př&iacute;stupy k herectv&iacute; a sc&eacute;nografii. Div&aacute;ci budou moci porovnat <strong data-start=\"1382\" data-end=\"1419\">tradičn&iacute; a modern&iacute; divadeln&iacute; styl</strong> a inspirovat se jin&yacute;mi kulturami. Např&iacute;klad francouzsk&aacute; skupina zn&aacute;m&aacute; sv&yacute;m avantgardn&iacute;m př&iacute;stupem přiveze vizu&aacute;lně působivou inscenaci, kter&aacute; pracuje se světlem a st&iacute;nem.</p>\r\n<h3 data-start=\"1594\" data-end=\"1624\"><strong data-start=\"1598\" data-end=\"1622\">Festival pro každ&eacute;ho</strong></h3>\r\n<p data-start=\"1625\" data-end=\"1986\">Festival nebude zaměřen pouze na profesion&aacute;ln&iacute; divadeln&iacute;ky a odborn&iacute;ky, ale nab&iacute;dne i program pro &scaron;irokou veřejnost. <strong data-start=\"1742\" data-end=\"1803\">Rodiny s dětmi se mohou tě&scaron;it na interaktivn&iacute; představen&iacute;</strong>, kter&aacute; kombinuj&iacute; divadlo s loutkohrou a hudbou. <strong data-start=\"1852\" data-end=\"1928\">Studenti a mlad&iacute; tvůrci zase z&iacute;skaj&iacute; př&iacute;ležitost zapojit se do workshopů</strong>, kde si vyzkou&scaron;&iacute; pr&aacute;ci herců, režis&eacute;rů nebo sc&eacute;nografů.</p>\r\n<h3 data-start=\"1988\" data-end=\"2034\"><strong data-start=\"1992\" data-end=\"2032\">Hradec Kr&aacute;lov&eacute; jako kulturn&iacute; centrum</strong></h3>\r\n<p data-start=\"2035\" data-end=\"2280\">Festival každoročně přitahuje tis&iacute;ce n&aacute;v&scaron;těvn&iacute;ků a potvrzuje tak <strong data-start=\"2100\" data-end=\"2159\">pozici Hradce Kr&aacute;lov&eacute; jako důležit&eacute;ho kulturn&iacute;ho centra</strong>. Organiz&aacute;toři věř&iacute;, že leto&scaron;n&iacute; ročn&iacute;k nab&iacute;dne nejen z&aacute;bavu, ale i prostor pro reflexi a diskusi o aktu&aacute;ln&iacute;ch t&eacute;matech.</p>\r\n<h3 data-start=\"2282\" data-end=\"2297\"><strong data-start=\"2286\" data-end=\"2295\">Z&aacute;věr</strong></h3>\r\n<p data-start=\"2298\" data-end=\"2628\" data-is-last-node=\"\" data-is-only-node=\"\">Divadeln&iacute; festival v Hradci Kr&aacute;lov&eacute; slibuje nev&scaron;edn&iacute; z&aacute;žitky, inspiraci a kvalitn&iacute; uměleck&eacute; v&yacute;kony. Ať už jste milovn&iacute;ci klasick&eacute;ho divadla, nebo hled&aacute;te modern&iacute; experiment&aacute;ln&iacute; formy, <strong data-start=\"2482\" data-end=\"2519\">festival nab&iacute;dne něco pro každ&eacute;ho</strong>. Pokud chcete b&yacute;t souč&aacute;st&iacute; jedinečn&eacute; atmosf&eacute;ry, <strong data-start=\"2568\" data-end=\"2627\">nev&aacute;hejte a přijďte se pod&iacute;vat na někter&eacute; z představen&iacute;</strong>.</p>', '2025-03-11 11:29:09', '2025-03-25 09:58:01', 5, 19, 1, 4),
(180, 'Pardubická galerie otevírá výstavu věnovanou české moderně', 'Pardubická galerie představuje unikátní výstavu zaměřenou na českou modernu, kde návštěvníci uvidí díla významných umělců 20. století. Expozice nabídne nejen obrazy a sochy, ale také doprovodný program s přednáškami a komentovanými prohlídkami.', 'Pardubická galerie otevírá výstavu zaměřenou na českou modernu, která představí díla významných umělců 20. století, včetně kubismu, surrealismu a abstrakce. Návštěvníci se mohou těšit na obrazy Emila Filly, Toyen či Františka Kupky a doprovodný program zahrnující komentované prohlídky, přednášky a workshopy. Výstava nabídne hlubší pohled na vývoj moderního umění v českém prostředí a jeho propojení s evropskou scénou.', '<article class=\"w-full text-token-text-primary focus-visible:outline-2 focus-visible:outline-offset-[-4px]\" dir=\"auto\" data-testid=\"conversation-turn-249\" data-scroll-anchor=\"true\">\r\n<div class=\"text-base my-auto mx-auto py-[18px] px-6\">\r\n<div class=\"mx-auto flex flex-1 text-base gap-4 md:gap-5 lg:gap-6 md:max-w-3xl lg:max-w-[40rem] xl:max-w-[48rem]\">\r\n<div class=\"group/conversation-turn relative flex w-full min-w-0 flex-col agent-turn @xs/thread:px-0 @sm/thread:px-1.5 @md/thread:px-4\">\r\n<div class=\"flex-col gap-1 md:gap-3\">\r\n<div class=\"flex max-w-full flex-col flex-grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 whitespace-normal break-words text-start [.text-message+&amp;]:mt-5\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"7450a0d9-5d88-4cc3-ad8f-569578c329a5\" data-message-model-slug=\"gpt-4o\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[3px]\">\r\n<div class=\"markdown prose w-full break-words dark:prose-invert light\">\r\n<h2 data-start=\"0\" data-end=\"64\"><strong>Pardubick&aacute; galerie otev&iacute;r&aacute; v&yacute;stavu věnovanou česk&eacute; moderně</strong></h2>\r\n<p data-start=\"66\" data-end=\"364\">Pardubick&aacute; galerie přin&aacute;&scaron;&iacute; jedinečn&yacute; pohled na českou modernu prostřednictv&iacute;m nov&eacute; v&yacute;stavy, kter&aacute; představ&iacute; d&iacute;la v&yacute;znamn&yacute;ch umělců 20. stolet&iacute;. N&aacute;v&scaron;těvn&iacute;ci se mohou tě&scaron;it na obrazy, sochy i grafiky reflektuj&iacute;c&iacute; dynamick&eacute; změny v uměleck&yacute;ch směrech a vlivech, jež formovaly modern&iacute; českou kulturu.</p>\r\n<h3 data-start=\"366\" data-end=\"390\">Co v&yacute;stava nab&iacute;z&iacute;?</h3>\r\n<p data-start=\"391\" data-end=\"707\">V&yacute;stava <em data-start=\"399\" data-end=\"422\">Česk&aacute; moderna v uměn&iacute;</em> představ&iacute; nejen slavn&aacute; jm&eacute;na česk&eacute; v&yacute;tvarn&eacute; sc&eacute;ny, ale i m&eacute;ně zn&aacute;m&eacute; autory, kteř&iacute; sv&yacute;m př&iacute;stupem obohatili v&yacute;voj modern&iacute;ho uměn&iacute;. Expozice se zaměřuje na <strong data-start=\"577\" data-end=\"631\">kubismus, surrealismus, abstrakci i expresionismus</strong>, přičemž důraz klade na specifick&yacute; v&yacute;voj těchto směrů v česk&eacute;m prostřed&iacute;.</p>\r\n<p data-start=\"709\" data-end=\"752\">Mezi nejv&yacute;znamněj&scaron;&iacute; vystaven&aacute; d&iacute;la patř&iacute;:</p>\r\n<ul data-start=\"753\" data-end=\"918\">\r\n<li data-start=\"753\" data-end=\"790\"><strong data-start=\"755\" data-end=\"788\">Kubistick&eacute; obrazy Emila Filly</strong></li>\r\n<li data-start=\"791\" data-end=\"829\"><strong data-start=\"793\" data-end=\"827\">Surrealistick&eacute; kompozice Toyen</strong></li>\r\n<li data-start=\"830\" data-end=\"871\"><strong data-start=\"832\" data-end=\"869\">Abstraktn&iacute; tvorba Franti&scaron;ka Kupky</strong></li>\r\n<li data-start=\"872\" data-end=\"918\"><strong data-start=\"874\" data-end=\"916\">Expresionistick&aacute; d&iacute;la Bohumila Kubi&scaron;ty</strong></li>\r\n</ul>\r\n<p data-start=\"920\" data-end=\"1067\">V&yacute;stava se tak&eacute; věnuje vlivu <strong data-start=\"949\" data-end=\"990\">evropsk&eacute;ho modernismu na česk&eacute; umělce</strong>, kteř&iacute; čerpali inspiraci z pař&iacute;žsk&eacute;, berl&iacute;nsk&eacute; či v&iacute;deňsk&eacute; uměleck&eacute; sc&eacute;ny.</p>\r\n<h3 data-start=\"1069\" data-end=\"1114\">Interaktivn&iacute; prvky a doprovodn&yacute; program</h3>\r\n<p data-start=\"1115\" data-end=\"1225\">Kromě samotn&eacute; expozice nab&iacute;dne galerie i <strong data-start=\"1156\" data-end=\"1181\">interaktivn&iacute; programy</strong> pro n&aacute;v&scaron;těvn&iacute;ky v&scaron;ech věkov&yacute;ch kategori&iacute;:</p>\r\n<ul data-start=\"1226\" data-end=\"1548\">\r\n<li data-start=\"1226\" data-end=\"1307\"><strong data-start=\"1228\" data-end=\"1264\">Komentovan&eacute; prohl&iacute;dky s kur&aacute;tory</strong>, kteř&iacute; přibl&iacute;ž&iacute; kontext vystaven&yacute;ch děl.</li>\r\n<li data-start=\"1308\" data-end=\"1379\"><strong data-start=\"1310\" data-end=\"1339\">Předn&aacute;&scaron;ky o česk&eacute; moderně</strong> a jej&iacute;m propojen&iacute; s evropsk&yacute;m uměn&iacute;m.</li>\r\n<li data-start=\"1380\" data-end=\"1464\"><strong data-start=\"1382\" data-end=\"1395\">Workshopy</strong>, kde si n&aacute;v&scaron;těvn&iacute;ci budou moci vyzkou&scaron;et techniky modern&iacute;ho uměn&iacute;.</li>\r\n<li data-start=\"1465\" data-end=\"1548\"><strong data-start=\"1467\" data-end=\"1499\">Speci&aacute;ln&iacute; programy pro &scaron;koly</strong>, zaměřen&eacute; na edukaci o česk&eacute; v&yacute;tvarn&eacute; tradici.</li>\r\n</ul>\r\n<h3 data-start=\"1550\" data-end=\"1584\">Proč nav&scaron;t&iacute;vit tuto v&yacute;stavu?</h3>\r\n<p data-start=\"1585\" data-end=\"1838\">V&yacute;stava nen&iacute; jen přehledem česk&eacute; moderny, ale i hlub&scaron;&iacute;m vhledem do <strong data-start=\"1652\" data-end=\"1693\">kulturn&iacute; a historick&eacute; identity n&aacute;roda</strong>. Ukazuje, jak se če&scaron;t&iacute; umělci vyrovn&aacute;vali s dobov&yacute;mi v&yacute;zvami, jak reflektovali společensk&eacute; změny a jak jejich tvorba ovlivnila dal&scaron;&iacute; generace.</p>\r\n<p data-start=\"1840\" data-end=\"2056\" data-is-last-node=\"\" data-is-only-node=\"\">V&yacute;stava <em data-start=\"1848\" data-end=\"1871\">Česk&aacute; moderna v uměn&iacute;</em> bude otevřena od <strong data-start=\"1889\" data-end=\"1909\">března do června</strong> v hlavn&iacute;ch prostor&aacute;ch Pardubick&eacute; galerie. Nenechte si uj&iacute;t jedinečnou př&iacute;ležitost poznat jedno z nejzaj&iacute;mavěj&scaron;&iacute;ch obdob&iacute; česk&eacute;ho v&yacute;tvarn&eacute;ho uměn&iacute;.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</article>', '2025-03-11 11:33:37', '2025-03-18 10:07:53', 3, 19, 1, 4),
(182, 'Letní kino v Chrudimi nabídne filmové hity pod širým nebem', 'Letní kino v Chrudimi láká na bohatý filmový program pod širým nebem. Diváci si užijí nejen nejnovější filmové hity, ale i kultovní klasiky a festivalové snímky. Nechte se unést kouzlem letních večerů s filmem.', 'Letní kino v Chrudimi přináší pestrý program plný filmových hitů, kultovních klasik i oceňovaných festivalových snímků. Návštěvníci se mohou těšit na tematické večery, bohaté občerstvení a pohodlné zázemí. Promítání pod širým nebem nabídne jedinečnou atmosféru a nezapomenutelné filmové zážitky po celé léto.', '<p data-start=\"0\" data-end=\"74\"><strong data-start=\"0\" data-end=\"72\">Letn&iacute; kino v Chrudimi nab&iacute;dne filmov&eacute; hity i klasiku pod &scaron;ir&yacute;m nebem</strong></p>\r\n<p data-start=\"76\" data-end=\"387\">L&eacute;to v Chrudimi bude opět ve znamen&iacute; filmov&yacute;ch večerů pod &scaron;ir&yacute;m nebem. M&iacute;stn&iacute; letn&iacute; kino připravilo bohat&yacute; program, kter&yacute; potě&scaron;&iacute; milovn&iacute;ky nejnověj&scaron;&iacute;ch filmov&yacute;ch hitů i nad&scaron;ence do filmov&eacute; klasiky. <strong data-start=\"274\" data-end=\"385\">Prom&iacute;t&aacute;n&iacute; pod hvězdami přinese nejen jedinečnou atmosf&eacute;ru, ale i pestrou nab&iacute;dku ž&aacute;nrů a doprovodn&yacute;ch akc&iacute;.</strong></p>\r\n<h3 data-start=\"389\" data-end=\"425\">Program pln&yacute; filmov&yacute;ch z&aacute;žitků</h3>\r\n<p data-start=\"427\" data-end=\"806\">Letn&iacute; kino zah&aacute;j&iacute; sez&oacute;nu už v polovině června a prom&iacute;t&aacute;n&iacute; bude prob&iacute;hat až do konce srpna. Div&aacute;ci se mohou tě&scaron;it na <strong data-start=\"543\" data-end=\"641\">akčn&iacute; blockbustery, romantick&eacute; komedie, rodinn&eacute; animovan&eacute; sn&iacute;mky i oceňovan&eacute; festivalov&eacute; filmy</strong>. Mezi oček&aacute;van&eacute; tituly leto&scaron;n&iacute;ho l&eacute;ta patř&iacute; např&iacute;klad nejnověj&scaron;&iacute; sn&iacute;mek z popul&aacute;rn&iacute; sci-fi s&eacute;rie, česk&aacute; komedie s hvězdn&yacute;m obsazen&iacute;m a kultovn&iacute; klasika z 80. let.</p>\r\n<p data-start=\"808\" data-end=\"1097\">Nezapomenuteln&eacute; okamžiky nab&iacute;dne tak&eacute; <strong data-start=\"846\" data-end=\"882\">večer věnovan&yacute; filmov&yacute;m legend&aacute;m</strong>, kdy si div&aacute;ci budou moci už&iacute;t ikonick&eacute; filmy v původn&iacute;m zněn&iacute; s česk&yacute;mi titulky. Na programu nebude chybět ani prom&iacute;t&aacute;n&iacute; filmů oceněn&yacute;ch na prestižn&iacute;ch festivalech, což ocen&iacute; zejm&eacute;na n&aacute;ročněj&scaron;&iacute; filmov&iacute; fanou&scaron;ci.</p>\r\n<h3 data-start=\"1099\" data-end=\"1126\">Pohodl&iacute; a občerstven&iacute;</h3>\r\n<p data-start=\"1128\" data-end=\"1403\">Are&aacute;l letn&iacute;ho kina pro&scaron;el v posledn&iacute;ch letech modernizac&iacute;, d&iacute;ky čemuž si div&aacute;ci mohou vychutnat filmy <strong data-start=\"1230\" data-end=\"1264\">v lep&scaron;&iacute; kvalitě zvuku i obrazu</strong>. Pro vět&scaron;&iacute; pohodl&iacute; bude k dispozici půjčovna dek a pol&scaron;t&aacute;řů, takže i chladněj&scaron;&iacute; letn&iacute; večery si n&aacute;v&scaron;těvn&iacute;ci užij&iacute; v maxim&aacute;ln&iacute;m komfortu.</p>\r\n<p data-start=\"1405\" data-end=\"1623\">Chybět nebude <strong data-start=\"1419\" data-end=\"1449\">bohat&aacute; nab&iacute;dka občerstven&iacute;</strong>, včetně dom&aacute;c&iacute; limon&aacute;dy, čerstv&eacute;ho popcornu nebo grilovan&yacute;ch specialit. Pro milovn&iacute;ky dobr&eacute;ho v&iacute;na a piva bude připraven speci&aacute;ln&iacute; st&aacute;nek s nab&iacute;dkou region&aacute;ln&iacute;ch produktů.</p>\r\n<h3 data-start=\"1625\" data-end=\"1665\">Doprovodn&eacute; akce a tematick&eacute; večery</h3>\r\n<p data-start=\"1667\" data-end=\"1934\">Kromě samotn&yacute;ch prom&iacute;t&aacute;n&iacute; se mohou n&aacute;v&scaron;těvn&iacute;ci tě&scaron;it i na různ&eacute; <strong data-start=\"1731\" data-end=\"1751\">tematick&eacute; večery</strong>, kter&eacute; obohat&iacute; filmov&yacute; z&aacute;žitek. Např&iacute;klad hororov&yacute; speci&aacute;l nab&iacute;dne <strong data-start=\"1819\" data-end=\"1850\">maraton stra&scaron;ideln&yacute;ch filmů</strong>, zat&iacute;mco retro večer přinese projekce kultovn&iacute;ch sn&iacute;mků v doprovodu dobov&eacute; hudby.</p>\r\n<p data-start=\"1936\" data-end=\"2199\">Letos poprv&eacute; se uskutečn&iacute; tak&eacute; <strong data-start=\"1967\" data-end=\"1983\">filmov&yacute; kv&iacute;z</strong>, kde si div&aacute;ci budou moci otestovat sv&eacute; znalosti kinematografie a zasoutěžit si o voln&eacute; vstupenky na dal&scaron;&iacute; projekce. <strong data-start=\"2101\" data-end=\"2121\">Nejmlad&scaron;&iacute; div&aacute;ci</strong> se mohou tě&scaron;it na dětsk&aacute; odpoledne s projekc&iacute; poh&aacute;dek a z&aacute;bavn&yacute;m programem.</p>\r\n<h3 data-start=\"2201\" data-end=\"2228\">Kdy a kde se prom&iacute;t&aacute;?</h3>\r\n<p data-start=\"2230\" data-end=\"2493\">Prom&iacute;t&aacute;n&iacute; se bude konat <strong data-start=\"2254\" data-end=\"2278\">každ&yacute; večer od 21:00</strong>, přičemž vstupenky bude možn&eacute; zakoupit <strong data-start=\"2318\" data-end=\"2345\">online i př&iacute;mo na m&iacute;stě</strong>. Organiz&aacute;toři doporučuj&iacute; dorazit s předstihem, aby si div&aacute;ci mohli vybrat nejlep&scaron;&iacute; m&iacute;sta a už&iacute;t si pohodovou letn&iacute; atmosf&eacute;ru před zač&aacute;tkem filmu.</p>\r\n<p data-start=\"2495\" data-end=\"2698\" data-is-last-node=\"\" data-is-only-node=\"\">Letn&iacute; kino v Chrudimi tak slibuje nejen skvěl&yacute; filmov&yacute; z&aacute;žitek, ale i př&iacute;jemně str&aacute;ven&yacute; večer pod &scaron;ir&yacute;m nebem. Pokud jste fanou&scaron;ky filmů a letn&iacute; pohody, rozhodně byste si tuto ud&aacute;lost neměli nechat uj&iacute;t.</p>\r\n<p data-start=\"2495\" data-end=\"2698\" data-is-last-node=\"\" data-is-only-node=\"\">&nbsp;</p>', '2025-03-11 11:44:23', '2025-03-25 09:56:30', 11, 19, 1, 4);
