INSERT INTO `komentare` (`idKomentare`, `obsah`, `created_at`, `updated_at`, `stav`, `Clanky_idClanky`, `Uzivatele_idUzivatele`, `idNadKomentar`) VALUES
(2, 'Expozice zní opravdu zajímavě! Jičín a Valdštejn k sobě historicky neodmyslitelně patří, a je skvělé, že muzeum tuto kapitolu dějin představuje moderní a interaktivní formou. Určitě si návštěvu naplánuji, zejména mě láká možnost virtuální prohlídky historického Jičína.', '2025-03-16 15:24:48', '2025-03-16 15:24:48', 1, 163, 17, NULL),
(3, 'To zní skvěle! Jsou tam i nějaké informace o Valdštejnových plánech na přestavbu města? Vím, že měl obrovské ambice a chtěl z Jičína udělat úplně nové centrum.\n', '2025-03-16 15:27:37', '2025-03-16 15:30:39', 1, 163, 22, 2),
(4, 'Ano, expozice se tomu věnuje docela podrobně! Ukazují i mapy plánované výstavby a modely některých budov, které se nakonec nerealizovaly. Bylo fascinující vidět, jak mohl Jičín vypadat, kdyby jeho vize vyšla.', '2025-03-16 15:30:28', '2025-03-16 15:30:28', 1, 163, 18, 2),
(5, 'Téma určitě zajímavé, ale zajímalo by mě, jestli se v expozici věnují i Valdštejnově záhadné smrti a jeho údajnému spojení s astrologií. To je aspekt, který mi na jeho příběhu vždy připadal nejzajímavější. Pokud někdo navštívil, můžete potvrdit?', '2025-03-16 15:31:10', '2025-03-16 15:31:10', 1, 163, 18, NULL),
(6, 'Super zpráva! Jičín je nádherné město s bohatou historií, takže si taková výstava určitě zaslouží pozornost. Navíc propojení s moderními technologiemi může zaujmout i mladší generaci, což je skvělý způsob, jak jim přiblížit naši historii.', '2025-03-16 15:31:34', '2025-03-16 15:31:34', 1, 163, 17, NULL);
