INSERT INTO `uzivatele` (`idUzivatele`, `jmeno`, `email`, `heslo`, `created_at`, `updated_at`, `popis`, `profilovka`, `Role_idRole`) VALUES
(1, 'Admin', 'admin@mail.com', '$2y$10$a8xCX/a4VTmSjSKtUbIcH.tzmNCEJG880jp/.H7iKTShX1/bUvUAm', '2025-03-03 10:41:27', '2025-03-18 12:19:32', NULL, NULL, 4),
(2, 'Admin', 'admin@email.cz', '$2y$10$a8xCX/a4VTmSjSKtUbIcH.tzmNCEJG880jp/.H7iKTShX1/bUvUAm', '2025-03-25 12:03:24', '2025-03-25 12:03:24', NULL, NULL, 0),
(17, 'Jan Novotný', 'jan.novotny@email.cz', '$2y$10$HsVoYdLQwaZBMntuBqHvN.vsP860wcdUfGWtKMGe4oyLMW9h4cPaO', '2025-03-03 11:39:29', '2025-03-18 10:09:16', 'Jsem novinář a autor píšící pro webový zpravodaj Východních Čech. Zaměřuji se na aktuální dění v regionu, přináším čtenářům objektivní a podrobné zpravodajství o politice, kultuře, ekonomice i společenských tématech. Mým cílem je poskytovat kvalitní informace, které pomohou lidem lépe porozumět dění kolem nich. Rád se věnuji investigativní práci, rozhovorům se zajímavými osobnostmi a reportážím přímo z místa událostí. Neustále sleduji nové trendy v žurnalistice a snažím se přinášet čtivé a poutavé články, které mají skutečný dopad.', '/assets/img/931846bb4701757b97f8fc039be171157f3cdcbf.jpg', 2),
(18, 'Petra Dvořáková', 'petra.dvorakova@email.cz', '$2y$10$HsVoYdLQwaZBMntuBqHvN.vsP860wcdUfGWtKMGe4oyLMW9h4cPaO', '2025-03-03 11:39:53', '2025-03-18 10:24:03', 'Jsem novinářka píšící pro Zpravodaj východních Čech, kde se věnuji aktuálnímu regionálnímu dění, reportážím a analýzám společenských, kulturních a ekonomických témat. Snažím se přinášet čtenářům srozumitelné, objektivní a podrobné informace, které jim pomohou lépe se orientovat v událostech ovlivňujících náš kraj.', '/assets/img/bdeb52374a7b1e7e07f5f8c633aaa2ec5b898016.jpg', 2),
(19, 'Michal Beneš', 'michal.benes@email.cz', '$2y$10$kud0Iaq/7FqdU1Inc6o/peUiziWvG2SuWCi7zPtmnHQKVS6rNNSnu', '2025-03-03 11:44:42', '2025-03-18 10:05:37', 'Jsem novinář píšící pro Zpravodaj východních Čech, kde se věnuji aktuálnímu dění, investigativním reportážím a analýzám společenských i politických témat. Mým cílem je přinášet objektivní, srozumitelné a ucelené informace, které pomohou čtenářům lépe porozumět událostem v našem regionu. Ve své práci se snažím zachytit podstatné souvislosti, přinášet zajímavé rozhovory a zprostředkovat názory odborníků i obyčejných lidí. Důležitá je pro mě nejen fakta, ale také lidské příběhy, které za nimi stojí.', '/assets/img/465ad9495853cf473a3e14dffbef8542ea24b8ba.jpg', 2),
(20, 'Veronika Svobodová', 'veronika.svobodova@email.cz', '$2y$10$bp4A2vb5HozW1zJxDgmTI.HohN1SNgyMaYtzRnl8Uwozm2NtdUVkO', '2025-03-03 11:46:05', '2025-03-11 13:15:26', NULL, NULL, 3),
(21, 'Jakub Vacek', 'jakub.vacek@email.cz', '$2y$10$cFdTXTGzUEWkZapoXldZ8eOvU31tEwY/uSftdTjhc2qhd9xVPJYmy', '2025-03-03 11:46:21', '2025-03-11 13:15:29', NULL, NULL, 3),
(22, 'Pepa Novotný', 'pepa.novotny@email.cz', '$2y$10$rWpsjD95miBzSPQDjcpbcuy98GItmDYkaAprIvWQpfwI4QqTBJniu', '2025-03-04 13:28:56', '2025-03-11 13:15:32', NULL, NULL, 1);
